def _env_bool(name, default=False):
    raw = str(os.getenv(name, "true" if default else "false")).strip().lower()
    if raw in {"1", "true", "yes", "on", "enabled"}:
        return True
    if raw in {"0", "false", "no", "off", "disabled"}:
        return False
    return bool(default)

