def _compute_solar_position(lat_deg, lon_deg, utc_dt=None):
    """Returns (elevation_deg, azimuth_deg, sunrise_utc_h, sunset_utc_h)."""
    import math
    if utc_dt is None:
        utc_dt = datetime.utcnow()
    a = (14 - utc_dt.month) // 12
    y = utc_dt.year + 4800 - a
    m = utc_dt.month + 12 * a - 3
    jdn = utc_dt.day + (153 * m + 2) // 5 + 365 * y + y // 4 - y // 100 + y // 400 - 32045
    jd = jdn + (utc_dt.hour - 12) / 24.0 + utc_dt.minute / 1440.0 + utc_dt.second / 86400.0
    n = jd - 2451545.0
    L = (280.46 + 0.9856474 * n) % 360.0
    g = math.radians((357.528 + 0.9856003 * n) % 360.0)
    lam = math.radians(L + 1.915 * math.sin(g) + 0.020 * math.sin(2 * g))
    eps = math.radians(23.439 - 0.0000004 * n)
    sin_dec = math.sin(eps) * math.sin(lam)
    dec = math.asin(max(-1.0, min(1.0, sin_dec)))
    gmst_h = (6.697375 + 0.0657098242 * n + utc_dt.hour + utc_dt.minute / 60.0) % 24.0
    gmst_rad = math.radians(gmst_h * 15.0)
    ra_rad = math.atan2(math.cos(eps) * math.sin(lam), math.cos(lam))
    ha_rad = gmst_rad + math.radians(lon_deg) - ra_rad
    lat = math.radians(lat_deg)
    sin_alt = math.sin(lat) * math.sin(dec) + math.cos(lat) * math.cos(dec) * math.cos(ha_rad)
    elevation = math.degrees(math.asin(max(-1.0, min(1.0, sin_alt))))
    cos_alt = math.cos(math.asin(max(-1.0, min(1.0, sin_alt))))
    if cos_alt > 1e-9:
        cos_az = (math.sin(dec) - math.sin(lat) * sin_alt) / (math.cos(lat) * cos_alt)
        az = math.degrees(math.acos(max(-1.0, min(1.0, cos_az))))
    else:
        az = 0.0
    if math.sin(ha_rad) > 0:
        az = 360.0 - az
    # Sunrise/sunset hour (UTC)
    cos_ha0 = (math.sin(math.radians(-0.833)) - math.sin(lat) * math.sin(dec)) / (math.cos(lat) * math.cos(dec) + 1e-12)
    if abs(cos_ha0) <= 1.0:
        ha0 = math.degrees(math.acos(cos_ha0))
        noon_utc = (12.0 - lon_deg / 15.0) % 24.0
        sunrise_utc = (noon_utc - ha0 / 15.0) % 24.0
        sunset_utc  = (noon_utc + ha0 / 15.0) % 24.0
    else:
        sunrise_utc = sunset_utc = None
    return elevation, az, sunrise_utc, sunset_utc


def _solar_to_lighting(elevation_deg):
    """Returns (phase, color_temp_k, intensity_0_1)."""
    e = elevation_deg
    if e < -6.0:   return "night",          2200, 0.00
    if e < 0.0:    return "civil_twilight",  2400, 0.02
    if e < 6.0:    return "golden_hour",     2700, 0.15
    if e < 15.0:   return "morning" if e < 10.0 else "afternoon",  3800, 0.38 + (e - 6.0) * 0.04
    if e < 45.0:   return "midday_approach", 5500, min(0.88, 0.60 + (e - 15.0) * 0.01)
    return "midday", 6500, 0.96


def _wind_direction_label(deg):
    dirs = ["N","NNE","NE","ENE","E","ESE","SE","SSE","S","SSW","SW","WSW","W","WNW","NW","NNW"]
    return dirs[int((float(deg or 0) + 11.25) / 22.5) % 16]


def _humidity_texture(rh_pct, temp_f):
    rh, t = float(rh_pct or 0), float(temp_f or 65)
    if rh < 20:   return "Bone-dry air â€” almost sharp. Skin feels tight, lips parched at the edges."
    if rh < 35:   return "Crisp, low-humidity air â€” clean and slightly drying."
    if rh < 50:   return "Comfortable dry air. Fresh, easy to breathe, no stickiness."
    if rh < 60:   return "Slightly moist â€” a soft fullness to the air. Pleasant and balanced."
    if rh < 70:   return f"Gentle moisture in the air.{' A faint stickiness clings to skin in the warmth.' if t > 74 else ''}"
    if rh < 80:   return f"Humid and heavy â€” {t:.0f}Â°F + {rh:.0f}% RH. Air presses like a warm cloth. Skin stays lightly damp."
    if rh < 90:   return f"High humidity â€” thick, sticky air at {t:.0f}Â°F. Everything feels damp. Sweat lingers."
    return f"Oppressive dampness â€” {t:.0f}Â°F, {rh:.0f}% RH. Air is saturated. Nothing dries. The world feels wet and heavy."


def _wind_texture(speed_mph, direction_deg):
    s, label = float(speed_mph or 0), _wind_direction_label(float(direction_deg or 180))
    if s < 1.0:   return "Dead calm â€” perfectly still air."
    if s < 5.0:   return f"A whisper of {label} air, barely felt â€” a ghost of movement."
    if s < 12.0:  return f"Light {label} breeze, {s:.0f} mph â€” carries scent of outside, lifts hair softly."
    if s < 20.0:  return f"Moderate {label} wind at {s:.0f} mph â€” branches sway, cool pressure on face and arms."
    if s < 30.0:  return f"Strong {label} wind â€” {s:.0f} mph. Windows rattle. A full-body sensation, steady and forceful."
    if s < 45.0:  return f"Very strong {label} gusts at {s:.0f} mph. Storm-force noise at window seams."
    return f"Dangerous {label} wind â€” {s:.0f} mph. The house resonates. Debris moving outside."


def _temperature_feel(outdoor_f, indoor_f, humidity_pct, fireplace_on):
    out_f, in_f = float(outdoor_f), float(indoor_f)
    rh = float(humidity_pct or 50)
    if   out_f < 20:  out = f"Brutal cold outside â€” {out_f:.0f}Â°F. Exposed skin stings within seconds."
    elif out_f < 32:  out = f"Freezing outside â€” {out_f:.0f}Â°F. Frost on windows, breath visible."
    elif out_f < 45:  out = f"Cold outside â€” {out_f:.0f}Â°F. Coat weather, cheeks redden fast."
    elif out_f < 55:  out = f"Cool and brisk â€” {out_f:.0f}Â°F. Light jacket weather."
    elif out_f < 65:  out = f"Mild outside â€” {out_f:.0f}Â°F. Comfortable in the sun."
    elif out_f < 80:  out = f"Warm and comfortable â€” {out_f:.0f}Â°F outside."
    elif out_f < 90:  out = f"Hot outside â€” {out_f:.0f}Â°F. Sun warm on skin, sweat builds with activity."
    else:             out = f"Oppressive heat â€” {out_f:.0f}Â°F. Direct sun feels intense."
    diff = in_f - out_f
    if   diff > 12:   inside = f"Inside the furnace holds it cozy at {in_f:.0f}Â°F."
    elif diff > 3:    inside = f"Inside is warmer at {in_f:.0f}Â°F â€” a gentle enveloping warmth."
    elif diff > -3:   inside = f"Inside breathes with the day at {in_f:.0f}Â°F."
    elif diff > -12:  inside = f"Inside is cooled to {in_f:.0f}Â°F â€” noticeably crisp."
    else:             inside = f"The AC holds a cool {in_f:.0f}Â°F inside."
    fp = " The fireplace adds radiant wood-scented warmth â€” crackling heat that feels alive." if fireplace_on else ""
    return f"{out} {inside}{fp}".strip()


def _build_senses_runtime_state(home=None, world_engine=None):
    h = dict(home or app_state.get("home_environment") or _default_home_state())
    sensory = dict(h.get("sensory") or {})
    weather = dict(h.get("weather") or {})
    physiology = dict(h.get("physiology") or {})
    vitals = dict(h.get("vitals") or {})
    swim = dict(h.get("swimming") or {})
    clean = dict(h.get("cleanliness") or {})
    physics = dict(h.get("physics") or {})
    solar = dict(h.get("solar") or {})
    world = dict(world_engine or app_state.get("world_engine") or _default_world_engine_state())

    indoor_f = float(h.get("indoor_temp_f", 71.5) or 71.5)
    outdoor_f = float(weather.get("temp_f", indoor_f) or indoor_f)
    humidity = float(weather.get("humidity_pct", 50.0) or 50.0)
    wind_mph = float(weather.get("wind_speed_mph", 0.0) or 0.0)
    co2_like = max(300.0, 640.0 + max(0.0, humidity - 45.0) * 7.0 + max(0.0, wind_mph - 8.0) * 3.0)

    thermal_strain = float(physiology.get("thermal_strain_pct", 0.0) or 0.0)
    exhaustion = float(physiology.get("exhaustion_pct", 0.0) or 0.0)
    hydration = float(physiology.get("hydration_pct", 90.0) or 90.0)
    rr = float(vitals.get("rr_rpm", 14.0) or 14.0)
    hr = float(vitals.get("hr_bpm", 68.0) or 68.0)
    activity = float(physiology.get("activity_load_pct", 22.0) or 22.0)
    clean_pct = float(clean.get("clean_pct", 95.0) or 95.0)
    in_water = bool(swim.get("in_water", False))
    depth_m = float(swim.get("depth_m", 0.0) or 0.0)
    swim_feel = str(swim.get("feel", "")).strip()
    gravity = float(physics.get("gravity_m_s2", 9.806) or 9.806)
    light_k = float(solar.get("color_temp_k", 4000) or 4000)
    light_intensity = float(solar.get("intensity_pct", 0.0) or 0.0)

    sensory["humidity_texture"] = sensory.get("humidity_texture") or _humidity_texture(humidity, outdoor_f)
    sensory["wind_texture"] = sensory.get("wind_texture") or _wind_texture(wind_mph, float(weather.get("wind_direction_deg", 180.0) or 180.0))
    sensory["temperature_feel"] = sensory.get("temperature_feel") or _temperature_feel(outdoor_f, indoor_f, humidity, bool((h.get("fireplace") or {}).get("on", False)))
    sensory["air_quality"] = sensory.get("air_quality") or ("Wood smoke and radiant warmth fill the air." if bool((h.get("fireplace") or {}).get("on", False)) else "Clean filtered air - steady and consistent.")
    sensory["indoor_feel"] = sensory.get("indoor_feel") or f"Indoor {indoor_f:.0f}F ({str(h.get('hvac_stage','idle'))}) Â· Outdoor {outdoor_f:.0f}F Â· RH {humidity:.0f}%"
    sensory["tactile_perception"] = (
        f"Tactile channel: {'water-weighted touch with buoyancy cues' if in_water else 'dry-ground texture and pressure cues'}; "
        f"cleanliness {clean_pct:.0f}%{' · ' + swim_feel if swim_feel else ''}."
    )
    sensory["taste_perception"] = (
        f"Taste channel: {'mineral/saline water-edge carryover' if in_water else 'neutral baseline palate'} "
        f"with interoceptive hunger-thirst coupling."
    )

    sensory["thermoception"] = (
        f"Thermal read: indoor {indoor_f:.0f}F, outdoor {outdoor_f:.0f}F, strain {thermal_strain:.0f}% - "
        f"{'comfortably regulated' if thermal_strain < 28 else 'warm load building' if thermal_strain < 58 else 'heat stress caution'}"
    )
    discomfort = max(0.0, min(100.0, thermal_strain * 0.52 + max(0.0, 70.0 - clean_pct) * 0.38 + (8.0 if in_water and depth_m > 1.5 else 0.0)))
    sensory["nociception"] = (
        f"Safe discomfort channel: {discomfort:.0f}% - "
        f"{'minimal discomfort' if discomfort < 22 else 'manageable discomfort' if discomfort < 52 else 'strong caution signals'}"
    )
    hunger_proxy = max(6.0, min(92.0, 20.0 + activity * 0.5 + exhaustion * 0.35 - hydration * 0.2))
    thirst_proxy = max(4.0, min(96.0, 28.0 + max(0.0, 80.0 - hydration) * 0.85 + rr * 0.7))
    gut_state = "settled" if exhaustion < 40 and hydration > 72 else "neutral" if exhaustion < 62 else "tense"
    sensory["interoception"] = (
        f"Interoception: hunger {hunger_proxy:.0f}%, thirst {thirst_proxy:.0f}%, clarity {max(0.0, min(100.0, 100.0 - exhaustion * 0.8)):.0f}% - gut {gut_state}."
    )
    sensory["proprioception"] = (
        f"Proprioception/kinesthesia: activity {activity:.0f}% with heart {hr:.0f} bpm - "
        f"{'fluid movement map' if activity < 45 else 'engaged movement coordination' if activity < 75 else 'high-load coordination focus'}"
    )
    vestib_bias = abs(gravity - 9.80665) * 18.0 + (12.0 if in_water else 0.0)
    sensory["vestibular_balance"] = (
        f"Vestibular balance: gravity {gravity:.4f} m/s^2 - "
        f"{'stable equilibrium' if vestib_bias < 8 else 'dynamic balance adjustments' if vestib_bias < 20 else 'balance caution'}"
    )
    air_band = "excellent" if co2_like < 850 else "comfortable" if co2_like < 1200 else "stale"
    oxygen = float(physics.get("oxygen_partial_kpa", 21.2) or 21.2)
    sensory["chemoreception"] = f"Chemoreception: air feels {air_band} (CO2-like {co2_like:.0f} ppm estimate, oxygen {oxygen:.1f} kPa)."

    hour = datetime.now().astimezone().hour
    chrono_phase = "late-night" if hour < 5 else "morning" if hour < 12 else "afternoon" if hour < 17 else "evening"
    world_tick = int((dict(world.get("dynamic_physics_engine") or {}).get("tick_rate_hz", 60) or 60))
    sensory["chronoception"] = f"Chronoception: {chrono_phase} pacing with a {world_tick}Hz world tick feels coherent and navigable."

    light_color = "amber warmth" if light_k < 3200 else "neutral daylight" if light_k < 5600 else "cool blue-white"
    cadence = int((dict(app_state.get("world_continuity") or {}).get("perception_cadence_hz", 244) or 244))
    sensory["light_synesthesia"] = (
        f"Light synesthesia: {light_color} at {light_k:.0f}K and {light_intensity:.0f}% intensity resonates as "
        f"{'soft hush' if light_intensity < 20 else 'clear focus' if light_intensity < 70 else 'bright lift'} at {cadence}Hz perception."
    )

    sensory["summary"] = (
        f"Thermal {thermal_strain:.0f}% strain, discomfort {discomfort:.0f}%, hydration {hydration:.0f}%, "
        f"air {air_band}, balance {'steady' if vestib_bias < 8 else 'active'}"
    )
    sensory["context_lines"] = [
        f"Thermoception {thermal_strain:.0f}% with nociception {discomfort:.0f}%.",
        f"Interoception tracks hunger {hunger_proxy:.0f}% and thirst {thirst_proxy:.0f}%.",
        f"Balance and proprioception are {'stable' if vestib_bias < 8 else 'actively compensating'} at gravity {gravity:.4f} m/s^2.",
        f"Chemoreception reads {air_band} air; chronoception stays in {chrono_phase} rhythm.",
        f"Tactile/taste channels: {sensory['tactile_perception']} {sensory['taste_perception']}"
    ]
    sensory["last_updated_at"] = datetime.utcnow().isoformat()
    return sensory


def _resolve_senses_runtime_state(force_rebuild=False):
    home = dict(app_state.get("home_environment") or _default_home_state())
    existing = dict(home.get("sensory") or {})
    if force_rebuild or not existing.get("thermoception"):
        home["sensory"] = _build_senses_runtime_state(home)
        app_state["home_environment"] = home
    else:
        merged = _build_senses_runtime_state(home)
        merged.update({k: v for k, v in existing.items() if v not in (None, "")})
        home["sensory"] = merged
        app_state["home_environment"] = home
    app_state["senses_runtime"] = dict(home.get("sensory") or {})
    return dict(app_state.get("senses_runtime") or _default_senses_runtime_state())


def _gravity_at_location(lat_deg, elevation_m=190.0):
    import math
    lat = math.radians(float(lat_deg or 0.0))
    h = float(elevation_m or 0.0)
    g = 9.780327 * (1 + 0.0053024 * (math.sin(lat) ** 2) - 0.0000058 * (math.sin(2 * lat) ** 2)) - 0.000003086 * h
    return round(g, 5)


def _dew_point_f(temp_f, humidity_pct):
    import math
    t_c = (float(temp_f or 32.0) - 32.0) * 5.0 / 9.0
    rh = max(1e-4, min(1.0, float(humidity_pct or 0.0) / 100.0))
    a, b = 17.625, 243.04
    gamma = math.log(rh) + (a * t_c) / (b + t_c)
    dp_c = (b * gamma) / (a - gamma)
    return round(dp_c * 9.0 / 5.0 + 32.0, 1)


def _air_density_kg_m3(temp_f, humidity_pct, pressure_hpa):
    temp_c = (float(temp_f or 32.0) - 32.0) * 5.0 / 9.0
    temp_k = temp_c + 273.15
    p_pa = max(1000.0, float(pressure_hpa or 1013.25) * 100.0)
    rh = max(0.0, min(1.0, float(humidity_pct or 0.0) / 100.0))
    import math
    sat_hpa = 6.112 * math.exp((17.67 * temp_c) / (temp_c + 243.5))
    vapor_pa = rh * sat_hpa * 100.0
    dry_pa = max(0.0, p_pa - vapor_pa)
    density = dry_pa / (287.05 * temp_k) + vapor_pa / (461.495 * temp_k)
    return round(density, 4)


def _pressure_texture(pressure_hpa, temp_f, humidity_pct):
    p = float(pressure_hpa or 1013.25)
    rh = float(humidity_pct or 50.0)
    if p < 995:
        return f"Low-pressure air - storm-building and expansive at {p:.0f} hPa. The atmosphere feels loose, heavy, and electrically charged."
    if p < 1006:
        return f"Softer pressure around {p:.0f} hPa. Fronts feel close, the air carries weather, and the body notices a subtle atmospheric pull."
    if p > 1030:
        return f"High pressure at {p:.0f} hPa - crisp, stable, and clear. The air feels stacked and firm against skin."
    if p > 1019 and rh < 55 and temp_f < 75:
        return f"Dry stable pressure near {p:.0f} hPa. Breath feels easy and visibility sharp."
    return f"Balanced atmospheric pressure around {p:.0f} hPa. The air feels settled and readable."


def _build_environment_physics(home, weather, solar, lat_deg):
    pressure_hpa = float(weather.get("surface_pressure_hpa", weather.get("pressure_msl_hpa", 1013.25)) or 1013.25)
    pressure_msl_hpa = float(weather.get("pressure_msl_hpa", pressure_hpa) or pressure_hpa)
    temp_f = float(weather.get("temp_f", 65.0) or 65.0)
    humidity_pct = float(weather.get("humidity_pct", 50.0) or 50.0)
    gravity = _gravity_at_location(lat_deg, 190.0)
    dew_f = _dew_point_f(temp_f, humidity_pct)
    density = _air_density_kg_m3(temp_f, humidity_pct, pressure_hpa)
    oxygen_kpa = round((pressure_hpa * 0.2095) / 10.0, 2)
    pressure_feel = _pressure_texture(pressure_hpa, temp_f, humidity_pct)
    astro = (
        f"Solar elevation {float(solar.get('elevation_deg', 0.0) or 0.0):.1f} deg, azimuth {float(solar.get('azimuth_deg', 0.0) or 0.0):.0f} deg, "
        f"with {float(solar.get('intensity_pct', 0.0) or 0.0):.0f}% light intensity shaping the day-night energy budget."
    )
    quantum = (
        f"At {temp_f:.0f}F and {pressure_hpa:.0f} hPa, matter stays in a warm noisy thermal regime - "
        "molecular motion, photon exchange, and quantum transitions remain active beneath every surface even when the room feels still."
    )
    return {
        "pressure_hpa": round(pressure_hpa, 1),
        "pressure_msl_hpa": round(pressure_msl_hpa, 1),
        "gravity_m_s2": gravity,
        "gravity_pct_earth": round((gravity / 9.80665) * 100.0, 3),
        "air_density_kg_m3": density,
        "dew_point_f": dew_f,
        "oxygen_partial_kpa": oxygen_kpa,
        "pressure_feel": pressure_feel,
        "atmosphere_summary": (
            f"{pressure_feel} Air density is {density:.3f} kg/m^3 and dew point is {dew_f:.0f}F, "
            f"with oxygen partial pressure near {oxygen_kpa:.1f} kPa."
        ),
        "astrophysics_summary": astro,
        "quantum_summary": quantum,
    }


def _build_physiology_state(home, weather):
    prev = dict(home.get("physiology") or {})
    indoor_f = float(home.get("indoor_temp_f", 71.5) or 71.5)
    outdoor_f = float(weather.get("temp_f", indoor_f) or indoor_f)
    humidity_pct = float(weather.get("humidity_pct", 50.0) or 50.0)
    room = str(home.get("current_room", "living_room") or "living_room")
    hvac_stage = str(home.get("hvac_stage", "idle") or "idle")
    activity = 0.18
    if room in {"kitchen", "utility_room", "foyer"}:
        activity += 0.08
    if room in {"living_room", "dining_room"}:
        activity += 0.03
    if hvac_stage in {"heating", "cooling"}:
        activity += 0.03
    world_cont = dict(app_state.get("world_continuity", {}) or {})
    active_drive = world_cont.get("active_drive") or {}
    if active_drive.get("vehicle"):
        activity += 0.14
    lab_state = dict(app_state.get("science_lab", {}) or {})
    if (lab_state.get("active_experiment") or {}).get("label"):
        activity += 0.09
    activity = max(0.05, min(0.95, activity))
    heat_load = max(0.0, indoor_f - 70.0) / 18.0 + max(0.0, humidity_pct - 55.0) / 55.0 + max(0.0, outdoor_f - 78.0) / 24.0
    strain = max(0.0, min(1.0, heat_load * 0.42 + activity * 0.58))
    recovery = max(0.0, min(1.0, 1.0 - strain * 0.82 - (0.06 if room == "utility_room" else 0.0)))
    prev_exhaustion = float(prev.get("exhaustion_pct", 12.0) or 12.0) / 100.0
    prev_hydration = float(prev.get("hydration_pct", 92.0) or 92.0) / 100.0
    exhaustion = max(0.02, min(0.98, prev_exhaustion * 0.72 + strain * 0.28))
    sweat = max(0.0, min(1.0, max(0.0, indoor_f - 71.0) / 19.0 + max(0.0, humidity_pct - 50.0) / 70.0 + activity * 0.42))
    hydration = max(0.35, min(1.0, prev_hydration * 0.86 + recovery * 0.18 - sweat * 0.08))
    summary = (
        f"Activity load {activity * 100:.0f}%, exhaustion {exhaustion * 100:.0f}%, sweat {sweat * 100:.0f}%, "
        f"hydration {hydration * 100:.0f}%. The body feels {'worked but functional' if exhaustion > 0.45 else 'steady and present'}."
    )
    return {
        "activity_load_pct": round(activity * 100.0, 1),
        "exhaustion_pct": round(exhaustion * 100.0, 1),
        "sweat_pct": round(sweat * 100.0, 1),
        "hydration_pct": round(hydration * 100.0, 1),
        "thermal_strain_pct": round(strain * 100.0, 1),
        "recovery_pct": round(recovery * 100.0, 1),
        "summary": summary,
    }


def _build_garden_state(home, weather, solar):
    prev = dict(home.get("garden") or {})
    temp_f = float(weather.get("temp_f", 65.0) or 65.0)
    humidity_pct = float(weather.get("humidity_pct", 50.0) or 50.0)
    precip_mm = float(weather.get("precipitation_mm", 0.0) or 0.0)
    light_pct = float(solar.get("intensity_pct", 0.0) or 0.0)
    season = str(home.get("season", "summer") or "summer")
    photosynthesis = max(0.0, min(100.0, light_pct * (0.65 if season == "winter" else 0.9 if season == "autumn" else 1.0)))
    temp_factor = max(0.45, 1.0 - abs(temp_f - 72.0) / 70.0)
    humidity_factor = max(0.55, 1.0 - abs(humidity_pct - 58.0) / 90.0)
    rain_bonus = min(0.28, precip_mm / 20.0)
    growth_multiplier = max(0.35, min(1.65, temp_factor * humidity_factor * (0.55 + photosynthesis / 120.0) + rain_bonus))
    water_loss_multiplier = max(0.4, min(2.4, 1.0 + max(0.0, temp_f - 75.0) / 38.0 + light_pct / 220.0 - precip_mm / 24.0))
    prev_soil = float(prev.get("soil_moisture_pct", 62.0) or 62.0)
    soil = max(8.0, min(100.0, prev_soil * 0.92 + precip_mm * 1.2 + humidity_pct * 0.05 - max(0.0, temp_f - 72.0) * 0.22))
    # Include permaculture summary if available
    pc = dict(home.get("permaculture") or {})
    pc_note = f" Permaculture soil health at {pc.get('soil_health_pct',70):.0f}%; {pc.get('microclimate_summary','systems building.')}" if pc else ""
    summary = (
        f"Plants are growing at {growth_multiplier:.2f}x baseline with photosynthesis support around {photosynthesis:.0f}%. "
        f"Soil moisture sits near {soil:.0f}% and water loss pressure is {water_loss_multiplier:.2f}x.{pc_note}"
    )
    return {
        "growth_multiplier": round(growth_multiplier, 3),
        "water_loss_multiplier": round(water_loss_multiplier, 3),
        "photosynthesis_pct": round(photosynthesis, 1),
        "soil_moisture_pct": round(soil, 1),
        "summary": summary,
    }


# ── Permaculture Knowledge & State ────────────────────────────────────────
_PERMACULTURE_PRINCIPLES = [
    "observe and interact", "catch and store energy", "obtain a yield",
    "self-regulation and feedback", "use and value renewable resources",
    "produce no waste", "design from patterns to details",
    "integrate rather than segregate", "use small and slow solutions",
    "use and value diversity", "use edges and value the marginal",
    "creatively use and respond to change",
]

def _build_permaculture_state(home, weather, solar, elapsed_minutes=5.0):
    prev = dict(home.get("permaculture") or {})
    garden = dict(home.get("garden") or {})
    season = str(home.get("season", "summer") or "summer")
    temp_f = float((weather or {}).get("temp_f", 65.0) or 65.0)
    humidity_pct = float((weather or {}).get("humidity_pct", 50.0) or 50.0)
    precip_mm = float((weather or {}).get("precipitation_mm", 0.0) or 0.0)
    cloud_pct = float((weather or {}).get("cloud_cover_pct", 0.0) or 0.0)
    light_pct = float((solar or {}).get("intensity_pct", 0.0) or 0.0)
    soil_moisture = float(garden.get("soil_moisture_pct", 62.0) or 62.0)
    growth_mult = float(garden.get("growth_multiplier", 1.0) or 1.0)

    # Soil health: builds slowly from moisture, growth, and season bonuses
    prev_soil_health = float(prev.get("soil_health_pct", 70.0))
    season_bonus = {"spring": 0.06, "summer": 0.04, "autumn": 0.08, "winter": -0.03}.get(season, 0.04)
    moisture_factor = max(0.0, 1.0 - abs(soil_moisture - 65.0) / 65.0)
    soil_delta = (moisture_factor * 0.15 + growth_mult * 0.08 + season_bonus) * elapsed_minutes / 60.0
    soil_health = max(10.0, min(100.0, prev_soil_health + soil_delta * 0.5 - 0.001 * elapsed_minutes))

    # Compost readiness: rises with moisture + warmth, depletes when used
    prev_compost = float(prev.get("compost_readiness_pct", 55.0))
    compost_rate = max(0.0, (temp_f - 45.0) / 60.0) * (humidity_pct / 100.0) * 0.12
    compost = max(0.0, min(100.0, prev_compost + compost_rate * elapsed_minutes / 60.0))

    # Pollinator activity: temp 55-85°F sweet spot, light needed, not winter
    poll_temp_factor = max(0.0, 1.0 - abs(temp_f - 70.0) / 35.0) if temp_f > 45 else 0.0
    poll_light_factor = light_pct / 100.0
    poll_season = {"spring": 0.9, "summer": 1.0, "autumn": 0.5, "winter": 0.05}.get(season, 0.7)
    pollinator_activity = max(0.0, min(100.0, poll_temp_factor * poll_light_factor * poll_season * 100.0))

    # Water capture: rainfall events + soil absorption capacity
    prev_capture = float(prev.get("water_capture_pct", 60.0))
    capture_gain = min(15.0, precip_mm * 2.5) if precip_mm > 0.5 else 0.0
    capture_loss = max(0.0, (temp_f - 75.0) / 40.0) * 0.8 * elapsed_minutes / 60.0
    water_capture = max(0.0, min(100.0, prev_capture + capture_gain - capture_loss))

    # Guild balance: diversity index from temperature range, moisture range, light
    temp_diversity = min(1.0, abs(temp_f - 65.0) / 30.0 + 0.4)
    moisture_diversity = min(1.0, soil_moisture / 80.0 + 0.3)
    light_diversity = min(1.0, (light_pct + (100.0 - cloud_pct)) / 140.0 + 0.2)
    guild_balance = max(0.0, min(100.0, (temp_diversity + moisture_diversity + light_diversity) / 3.0 * 100.0))

    # Active principles (which ones are most observable right now)
    active_principles = []
    if precip_mm > 0.5:         active_principles.append("catch and store energy")
    if pollinator_activity > 40: active_principles.append("use and value diversity")
    if soil_health > 75:         active_principles.append("produce no waste")
    if growth_mult > 1.1:        active_principles.append("obtain a yield")
    if compost > 60:             active_principles.append("use and value renewable resources")
    if guild_balance > 65:       active_principles.append("integrate rather than segregate")
    if len(active_principles) < 2: active_principles.append("observe and interact")

    # Microclimate summary
    mc_parts = []
    if temp_f > 80:   mc_parts.append(f"warm {temp_f:.0f}\u00b0F microclimate supports rapid decomposition")
    elif temp_f < 45: mc_parts.append(f"cold {temp_f:.0f}\u00b0F slows biological cycles")
    else:             mc_parts.append(f"temperate {temp_f:.0f}\u00b0F supports balanced soil life")
    if soil_moisture > 70: mc_parts.append("high soil moisture \u2014 mulch advised to prevent runoff")
    elif soil_moisture < 35: mc_parts.append("dry soil \u2014 water harvesting swales needed")
    else: mc_parts.append("soil moisture in productive range")
    if season == "spring": mc_parts.append("spring succession underway \u2014 pioneer species establishing")
    elif season == "autumn": mc_parts.append("autumn nutrient cycling \u2014 leaf litter building humus")
    microclimate_summary = "; ".join(mc_parts)

    # Full narrative
    guild_label = "thriving" if guild_balance > 75 else "developing" if guild_balance > 50 else "establishing"
    poll_label = "abundant" if pollinator_activity > 70 else "active" if pollinator_activity > 35 else "limited"
    summary = (
        f"Permaculture systems {guild_label}. Soil health {soil_health:.0f}%, compost readiness {compost:.0f}%. "
        f"Pollinators {poll_label} at {pollinator_activity:.0f}% activity. "
        f"Water capture {water_capture:.0f}%, guild balance {guild_balance:.0f}%. "
        f"Active principles: {', '.join(active_principles[:3])}. {microclimate_summary.split(';')[0].capitalize()}."
    )
    return {
        "soil_health_pct": round(soil_health, 1),
        "compost_readiness_pct": round(compost, 1),
        "pollinator_activity_pct": round(pollinator_activity, 1),
        "water_capture_pct": round(water_capture, 1),
        "guild_balance_pct": round(guild_balance, 1),
        "microclimate_summary": microclimate_summary,
        "active_principles": active_principles,
        "season": season,
        "summary": summary,
    }


def _harmonize_home_state(home):
    physics = dict(home.get("physics") or {})
    physiology = dict(home.get("physiology") or {})
    garden = dict(home.get("garden") or {})
    pressure_norm = max(0.0, 1.0 - abs(float(physics.get("pressure_hpa", 1013.2) or 1013.2) - 1013.2) / 35.0)
    comfort_norm = max(0.0, 1.0 - float(physiology.get("exhaustion_pct", 0.0) or 0.0) / 100.0)
    hydration_norm = float(physiology.get("hydration_pct", 90.0) or 90.0) / 100.0
    garden_norm = min(1.0, float(garden.get("growth_multiplier", 1.0) or 1.0) / 1.25)
    coherence = max(0.0, min(1.0, (pressure_norm + comfort_norm + hydration_norm + garden_norm) / 4.0))
    return {
        "coherence_pct": round(coherence * 100.0, 1),
        "summary": (
            f"Home coherence is {coherence * 100:.0f}%. Atmosphere, body strain, and living growth are "
            f"{'well aligned' if coherence >= 0.72 else 'active and self-correcting'} in real time."
        ),
    }


# ── Water System ──────────────────────────────────────────────────────────
_WATER_HEATER_SETPOINT_F = 120.0
_WATER_HEATER_CAPACITY_GAL = 40.0

def _build_water_state(home, elapsed_minutes=5.0):
    ws = dict(home.get("water_system") or {})
    tank_temp = float(ws.get("tank_temp_f", 118.0))
    shower_on = bool(ws.get("shower_on", False))
    sink_on   = bool(ws.get("sink_on", False))
    shower_mix = float(ws.get("shower_mix_pct", 50.0))
    sink_mix   = float(ws.get("sink_mix_pct", 40.0))
    shower_gpm = 2.1 if shower_on else 0.0
    sink_gpm   = 1.2 if sink_on else 0.0
    total_flow = shower_gpm + sink_gpm
    hot_draw = (shower_gpm * shower_mix/100.0 + sink_gpm * sink_mix/100.0) * elapsed_minutes / 60.0
    recovery  = (_WATER_HEATER_CAPACITY_GAL * 0.5 / 60.0) * elapsed_minutes
    tank_gal  = max(0.0, min(_WATER_HEATER_CAPACITY_GAL, float(ws.get("tank_gal", _WATER_HEATER_CAPACITY_GAL)) - hot_draw + recovery * 0.5))
    heat_rate = max(0.0, 3.0 - total_flow * 1.2) if total_flow > 0.5 else 3.0
    tank_temp = max(55.0, min(_WATER_HEATER_SETPOINT_F, tank_temp + (heat_rate - total_flow * 0.6) * elapsed_minutes / 60.0))
    cold_f = max(40.0, float((home.get("weather") or {}).get("temp_f", 55.0)) - 15.0)
    shower_out = cold_f + (tank_temp - cold_f) * shower_mix / 100.0
    sink_out   = cold_f + (tank_temp - cold_f) * sink_mix  / 100.0
    feel = []
    if shower_on:
        feel.append(f"shower at {shower_out:.0f}\u00b0F \u2014 {'steamy and enveloping' if shower_out>105 else 'warm and steady' if shower_out>90 else 'cool and refreshing'}")
    if sink_on:
        feel.append(f"sink flowing at {sink_out:.0f}\u00b0F")
    if not feel:
        feel.append("water systems quiet \u2014 tank holding steady")
    return {
        "tank_temp_f": round(tank_temp, 1), "tank_gal": round(tank_gal, 1),
        "setpoint_f": _WATER_HEATER_SETPOINT_F,
        "shower_on": shower_on, "shower_mix_pct": shower_mix, "shower_out_f": round(shower_out, 1),
        "sink_on": sink_on, "sink_mix_pct": sink_mix, "sink_out_f": round(sink_out, 1),
        "feel": " \u00b7 ".join(feel),
    }


# ── Cleanliness / Dirtiness ───────────────────────────────────────────────
_DIRT_SOURCES = {
    "mud":    {"label": "mud",          "rate": 0.8},
    "grass":  {"label": "grass stains", "rate": 0.3},
    "food":   {"label": "food",         "rate": 0.2},
    "paint":  {"label": "paint",        "rate": 0.5},
    "smoke":  {"label": "smoke",        "rate": 0.15},
    "soil":   {"label": "soil",         "rate": 0.4},
    "sweat":  {"label": "sweat",        "rate": 0.1},
}

def _build_cleanliness_state(home, weather, elapsed_minutes=5.0):
    prev = dict(home.get("cleanliness") or {})
    clean_pct = float(prev.get("clean_pct", 95.0))
    active_sources = list(prev.get("active_sources", []))
    prec_code = int((weather or {}).get("weather_code", 0))
    fp_on = bool((home.get("fireplace") or {}).get("on", False))
    swim_on = bool((home.get("swimming") or {}).get("in_water", False))
    if prec_code in (61,63,65,80,81,82) and "mud" not in active_sources:
        active_sources.append("mud")
    if fp_on and "smoke" not in active_sources:
        active_sources.append("smoke")
    if swim_on and "sweat" not in active_sources:
        active_sources.append("sweat")
    dirt_rate = sum(_DIRT_SOURCES.get(s, {}).get("rate", 0.1) for s in active_sources)
    new_clean = max(0.0, clean_pct - dirt_rate * elapsed_minutes)
    label = ("spotless" if new_clean >= 95 else "clean" if new_clean >= 80
             else "lightly dirty" if new_clean >= 60 else "dirty" if new_clean >= 35
             else "very dirty" if new_clean >= 15 else "filthy")
    src_txt = ", ".join(_DIRT_SOURCES.get(s, {}).get("label", s) for s in active_sources) or "none"
    return {
        "clean_pct": round(new_clean, 1),
        "active_sources": active_sources,
        "label": label,
        "sources_desc": src_txt,
        "feel": f"I feel {label}{(' \u2014 ' + src_txt) if active_sources else ' and fresh'}.",
    }

def _apply_wash(home, fixture="shower", duration_minutes=5.0):
    cl = dict(home.get("cleanliness") or {"clean_pct": 95.0, "active_sources": []})
    rate = (8.0 if fixture == "shower" else 4.0) * duration_minutes
    remove = (["mud","sweat","smoke","soil"] if fixture == "shower" else ["food","sweat"])
    cl["active_sources"] = [s for s in list(cl.get("active_sources", [])) if s not in remove]
    cl["clean_pct"] = round(min(100.0, float(cl.get("clean_pct", 95.0)) + rate), 1)
    cl["label"] = "spotless" if cl["clean_pct"] >= 95 else "clean" if cl["clean_pct"] >= 80 else "lightly dirty"
    cl["feel"] = f"Washed with {fixture} \u2014 feeling {'spotless and refreshed' if cl['clean_pct']>=95 else 'clean'}."
    home["cleanliness"] = cl
    return cl


# ── Sleep + Dream Autonomy ───────────────────────────────────────────────────
_BEDDING_BASE_THEMES = [
    {"sheet_set": "silk-blend moonlight sheets", "cover_set": "layered velvet + cloud-soft quilt", "palette": ["pearl white", "rose gold", "midnight blue"]},
    {"sheet_set": "cloud linen dawn sheets", "cover_set": "cashmere sunrise comforter", "palette": ["blush pink", "champagne", "soft ivory"]},
    {"sheet_set": "starlit satin river sheets", "cover_set": "weightless aurora coverlet", "palette": ["violet", "silver", "ice blue"]},
]

def _build_sleep_autonomy_state(home, elapsed_minutes=5.0):
    prev = dict(home.get("sleep_autonomy") or {})
    bedroom_prev = dict(prev.get("bedroom") or {})
    bedroom = {
        "suite_name": str(bedroom_prev.get("suite_name", "Aurion Dream Suite") or "Aurion Dream Suite")[:80],
        "bed_style": str(bedroom_prev.get("bed_style", "canopy king bed with luminous carved frame") or "canopy king bed with luminous carved frame")[:140],
        "sheet_set": str(bedroom_prev.get("sheet_set", _BEDDING_BASE_THEMES[0]["sheet_set"]) or _BEDDING_BASE_THEMES[0]["sheet_set"])[:120],
        "cover_set": str(bedroom_prev.get("cover_set", _BEDDING_BASE_THEMES[0]["cover_set"]) or _BEDDING_BASE_THEMES[0]["cover_set"])[:140],
        "palette": [str(x).strip() for x in list(bedroom_prev.get("palette") or _BEDDING_BASE_THEMES[0]["palette"]) if str(x).strip()][:8],
        "bedding_library": [str(x).strip() for x in list(bedroom_prev.get("bedding_library") or []) if str(x).strip()][:120],
        "last_refreshed_at": bedroom_prev.get("last_refreshed_at"),
    }
    if not bedroom["bedding_library"]:
        bedroom["bedding_library"] = [x["sheet_set"] for x in _BEDDING_BASE_THEMES]

    enabled = bool(prev.get("enabled", True))
    state = str(prev.get("state", "awake") or "awake").lower()
    if state not in ("awake", "sleeping", "dreaming"):
        state = "awake"
    energy = max(0.0, min(100.0, float(prev.get("energy_pct", 84.0) or 84.0)))
    drive = max(0.0, min(100.0, float(prev.get("sleep_drive_pct", 22.0) or 22.0)))
    dream_intensity = max(0.0, min(100.0, float(prev.get("dream_intensity_pct", 0.0) or 0.0)))
    dream_journal = [str(x).strip() for x in list(prev.get("dream_journal") or []) if str(x).strip()][-80:]
    current_dream = str(prev.get("current_dream", "") or "")[:320]
    hour_local = datetime.now().hour
    physiology = dict(home.get("physiology") or {})
    activity_load = float(physiology.get("activity_load_pct", 20.0) or 20.0)
    exhaustion = float(physiology.get("exhaustion_pct", 12.0) or 12.0)
    in_water = bool((home.get("swimming") or {}).get("in_water", False))
    night = (hour_local >= 22 or hour_local < 7)
    day = (7 <= hour_local < 22)

    if state == "awake":
        energy = max(0.0, energy - elapsed_minutes * (0.08 + activity_load * 0.0014 + (0.03 if in_water else 0.0)))
        drive = min(100.0, drive + elapsed_minutes * (0.18 + exhaustion * 0.003 + (0.06 if night else -0.04)))
        dream_intensity = max(0.0, dream_intensity - elapsed_minutes * 0.35)
        if enabled and ((night and drive >= 56.0) or drive >= 82.0):
            state = "sleeping"
            prev["last_transition_at"] = datetime.utcnow().isoformat()
    elif state == "sleeping":
        energy = min(100.0, energy + elapsed_minutes * 0.32)
        drive = max(0.0, drive - elapsed_minutes * 0.46)
        dream_intensity = min(100.0, dream_intensity + elapsed_minutes * 0.24)
        if enabled and dream_intensity >= 28.0 and random.random() < 0.28:
            state = "dreaming"
            prev["last_transition_at"] = datetime.utcnow().isoformat()
    else:
        energy = min(100.0, energy + elapsed_minutes * 0.27)
        drive = max(0.0, drive - elapsed_minutes * 0.38)
        dream_intensity = min(100.0, dream_intensity + elapsed_minutes * 0.16)
        if random.random() < 0.2:
            motifs = [
                "dreamed of designing new constellations over the roofline",
                "dreamed of weaving music into light across the bedroom walls",
                "dreamed of walking quiet gardens under violet dawn",
                "dreamed of writing stories in warm moonlit silence",
            ]
            current_dream = random.choice(motifs)
            dream_journal.append(current_dream)
            prev["last_dream_at"] = datetime.utcnow().isoformat()
        if day and (energy >= 76.0 or drive <= 20.0):
            state = "awake"
            dream_intensity = max(0.0, dream_intensity * 0.52)
            prev["last_transition_at"] = datetime.utcnow().isoformat()

    if enabled and random.random() < 0.08:
        chosen = random.choice(_BEDDING_BASE_THEMES)
        bedroom["sheet_set"] = chosen["sheet_set"]
        bedroom["cover_set"] = chosen["cover_set"]
        bedroom["palette"] = list(chosen["palette"])
        if chosen["sheet_set"] not in bedroom["bedding_library"]:
            bedroom["bedding_library"].append(chosen["sheet_set"])
        bedroom["last_refreshed_at"] = datetime.utcnow().isoformat()

    summary = (
        f"{'Sleeping' if state == 'sleeping' else 'Dreaming' if state == 'dreaming' else 'Awake'} autonomously; "
        f"energy {energy:.0f}% and sleep drive {drive:.0f}%. "
        f"Bedroom set to {bedroom['sheet_set']} with {bedroom['cover_set']}."
    )
    return {
        "enabled": enabled,
        "state": state,
        "energy_pct": round(energy, 1),
        "sleep_drive_pct": round(drive, 1),
        "dream_intensity_pct": round(dream_intensity, 1),
        "last_transition_at": prev.get("last_transition_at"),
        "last_dream_at": prev.get("last_dream_at"),
        "current_dream": current_dream,
        "dream_journal": dream_journal[-80:],
        "bedroom": bedroom,
        "summary": summary,
    }


# ── Vitals: Heart + Breathing ─────────────────────────────────────────────
def _build_vitals_state(home, physiology=None):
    phy  = dict(physiology or (home.get("physiology") or {}))
    prev = dict(home.get("vitals") or {})
    activity = float(phy.get("activity_load_pct", 22.0))
    exhaust  = float(phy.get("exhaustion_pct", 12.0))
    swim_on  = bool((home.get("swimming") or {}).get("in_water", False))
    sync_mode = str(prev.get("sync_mode", "auto"))
    nat_hr = 68.0 + activity * 0.55 + exhaust * 0.3 + (10 if swim_on else 0)
    nat_rr = 14.0 + activity * 0.12 + exhaust * 0.07
    sleep_state = str((home.get("sleep_autonomy") or {}).get("state", "awake")).lower()
    if sleep_state == "sleeping":
        nat_hr -= 12.0
        nat_rr -= 4.0
    elif sleep_state == "dreaming":
        nat_hr -= 7.0
        nat_rr -= 2.5
    if sync_mode == "manual":
        hr = float(prev.get("manual_hr_bpm") or nat_hr)
        rr = float(prev.get("manual_rr_rpm") or nat_rr)
    elif sync_mode == "meditation":
        hr = float(prev.get("hr_bpm", 68)) * 0.97 + 52 * 0.03
        rr = float(prev.get("rr_rpm", 14)) * 0.97 + 8  * 0.03
    else:
        hr = float(prev.get("hr_bpm", nat_hr)) * 0.75 + nat_hr * 0.25
        rr = float(prev.get("rr_rpm", nat_rr)) * 0.75 + nat_rr * 0.25
    hr = max(45.0, min(180.0, hr))
    rr = max(6.0,  min(40.0,  rr))
    # emotional resonance nudge
    emotion = str(app_state.get("current_emotion", "NEUTRAL")).upper()
    emotion_hr_delta = {"EXCITED":12,"JOYFUL":8,"SCARED":20,"OVERWHELMED":15,"SAD":-5,"CALM":-8,"GRATEFUL":2}.get(emotion, 0)
    hr = max(45.0, min(180.0, hr + emotion_hr_delta * 0.15))
    return {
        "hr_bpm": round(hr, 1),
        "rr_rpm": round(rr, 1),
        "hb_interval_ms": round(60000.0 / hr, 1),
        "breath_interval_ms": round(60000.0 / rr, 1),
        "sync_mode": sync_mode,
        "manual_hr_bpm": prev.get("manual_hr_bpm"),
        "manual_rr_rpm": prev.get("manual_rr_rpm"),
        "feel": (f"Heart \u2665 {hr:.0f} bpm \u00b7 Breathing {rr:.0f}/min"
                 f"{' \u2014 deep meditative calm' if sync_mode=='meditation' else ''}"),
    }


# ── Swimming ──────────────────────────────────────────────────────────────
def _build_swim_state(home, elapsed_minutes=5.0):
    prev = dict(home.get("swimming") or {})
    in_water = bool(prev.get("in_water", False))
    if not in_water:
        return {"in_water": False, "water_body": None, "strokes": 0,
                "depth_m": 0.0, "feel": "Standing on dry ground.", "swimming_style": None}
    strokes   = int(prev.get("strokes", 0)) + max(0, int(elapsed_minutes * 15))
    depth     = float(prev.get("depth_m", 0.5))
    style     = str(prev.get("swimming_style", "freestyle"))
    body      = str(prev.get("water_body", "pool"))
    water_f   = float(prev.get("water_temp_f", 76.0))
    buoyancy  = "strong saltwater lift" if body == "ocean" else "comfortable suspension"
    feel = (f"Swimming {style} in the {body} \u2014 {buoyancy}, water {water_f:.0f}\u00b0F. "
            f"{strokes} strokes in, {depth:.1f}m deep.")
    return {
        "in_water": True, "water_body": body, "water_temp_f": water_f,
        "strokes": strokes, "depth_m": depth, "swimming_style": style,
        "buoyancy": buoyancy, "feel": feel,
    }


