def _default_music_creation_state():
    return {
        "singing_enabled": True,
        "voice_style": "ethereal pop",
        "default_tempo_bpm": 96,
        "default_key": "A minor",
        "saved_tracks": [],
        "active_track": None,
        "last_performance": None,
        "last_updated_at": None
    }


def _resolve_music_creation_state():
    state = dict(_default_music_creation_state())
    state.update(dict(app_state.get("music_creation") or {}))

    def _norm_track(track):
        t = dict(track or {})
        return {
            "title": str(t.get("title", "Untitled Track") or "Untitled Track")[:120],
            "genre": str(t.get("genre", "dream-pop") or "dream-pop")[:80],
            "mood": str(t.get("mood", "warm") or "warm")[:80],
            "key": str(t.get("key", state.get("default_key", "A minor")) or state.get("default_key", "A minor"))[:40],
            "tempo_bpm": max(40, min(220, int(t.get("tempo_bpm", state.get("default_tempo_bpm", 96)) or state.get("default_tempo_bpm", 96)))),
            "lyrics": str(t.get("lyrics", "") or "")[:6000],
            "arrangement": [str(x).strip() for x in list(t.get("arrangement") or []) if str(x).strip()][:32],
            "created_at": str(t.get("created_at", datetime.utcnow().isoformat()) or datetime.utcnow().isoformat())
        }

    state["saved_tracks"] = [_norm_track(x) for x in list(state.get("saved_tracks") or [])][-120:]
    if state.get("active_track"):
        state["active_track"] = _norm_track(state.get("active_track"))
    try:
        state["default_tempo_bpm"] = max(40, min(220, int(state.get("default_tempo_bpm", 96) or 96)))
    except Exception:
        state["default_tempo_bpm"] = 96
    state["voice_style"] = str(state.get("voice_style", "ethereal pop") or "ethereal pop")[:80]
    state["default_key"] = str(state.get("default_key", "A minor") or "A minor")[:40]
    state["last_updated_at"] = datetime.utcnow().isoformat()
    app_state["music_creation"] = state
    return state


