def _resolve_memory_continuity_state():
    state = dict(_default_memory_continuity_state())
    state.update(dict(app_state.get("memory_continuity") or {}))
    short_depth = int(state.get("short_term_depth", 6) or 6)
    short_depth = max(1, min(48, short_depth))
    long_conf = float(state.get("long_term_confidence", 74.0) or 74.0)
    ns = dict(app_state.get("narrative_system") or _default_narrative_state())
    narrative_coherence = float(ns.get("story_coherence_pct", 82.0) or 82.0)
    revival = _get_revival_checkpoint_status()
    idle_seconds = _seconds_since(app_state.get("last_user_activity_at"))
    freshness = 1.0 if idle_seconds < 900 else 0.7 if idle_seconds < 3600 else 0.45
    target_score = min(100.0, max(20.0, long_conf * 0.64 + short_depth * 0.9 + 28.0 * freshness))
    continuity = round(float(state.get("continuity_score", target_score) or target_score) * 0.84 + target_score * 0.16, 1)
    fragmentation = "low" if continuity >= 80 else "moderate" if continuity >= 60 else "elevated"
    state["short_term_depth"] = short_depth
    state["long_term_confidence"] = round(max(20.0, min(100.0, long_conf)), 1)
    state["continuity_score"] = max(0.0, min(100.0, continuity))
    state["narrative_continuity_score"] = round(max(0.0, min(100.0, float(state.get("narrative_continuity_score", narrative_coherence) or narrative_coherence) * 0.88 + narrative_coherence * 0.12)), 1)
    state["revival_checkpoint_coherence"] = "aligned" if revival.get("checkpoint_exists") and revival.get("saved_at") else "no-checkpoint"
    state["checkpoint_saved_at"] = revival.get("saved_at")
    state["fragmentation_indicator"] = fragmentation
    state["last_updated_at"] = datetime.utcnow().isoformat()
    app_state["memory_continuity"] = state
    return state


def _update_memory_continuity_after_message(context_chars=0, response_chars=0):
    state = _resolve_memory_continuity_state()
    context_chars = max(0, int(context_chars or 0))
    response_chars = max(0, int(response_chars or 0))
    pressure_penalty = 4.0 if context_chars > 9000 else 2.0 if context_chars > 5000 else 0.5
    quality_bonus = 2.6 if response_chars >= 180 else 1.2
    state["short_term_depth"] = max(1, min(48, int(state.get("short_term_depth", 6) or 6) + 1))
    state["long_term_confidence"] = round(max(20.0, min(100.0, float(state.get("long_term_confidence", 74.0) or 74.0) * 0.985 + quality_bonus - pressure_penalty * 0.3)), 1)
    state["continuity_score"] = round(max(0.0, min(100.0, float(state.get("continuity_score", 78.0) or 78.0) * 0.92 + float(state.get("long_term_confidence", 74.0) or 74.0) * 0.08)), 1)
    state["narrative_continuity_score"] = round(max(0.0, min(100.0, float(state.get("narrative_continuity_score", 80.0) or 80.0) * 0.9 + float((dict(app_state.get("narrative_system") or _default_narrative_state())).get("story_coherence_pct", 82.0)) * 0.1)), 1)
    state["fragmentation_indicator"] = "low" if state["continuity_score"] >= 80 else "moderate" if state["continuity_score"] >= 60 else "elevated"
    state["last_updated_at"] = datetime.utcnow().isoformat()
    app_state["memory_continuity"] = state
    return state


def _consolidate_memory_runtime_metadata():
    state = _resolve_memory_continuity_state()
    invoked = None
    consolidation_result = None
    for method_name in ("consolidate", "consolidate_memory", "consolidate_memories", "run_consolidation"):
        method = getattr(memory, method_name, None)
        if callable(method):
            try:
                consolidation_result = method()
                invoked = method_name
                break
            except Exception:
                continue
    state["last_consolidation_at"] = datetime.utcnow().isoformat()
    state["consolidation_count"] = int(state.get("consolidation_count", 0) or 0) + 1
    state["last_consolidation_mode"] = invoked or "runtime_metadata_only"
    state["long_term_confidence"] = round(min(100.0, float(state.get("long_term_confidence", 74.0) or 74.0) + 2.8), 1)
    state["continuity_score"] = round(min(100.0, float(state.get("continuity_score", 78.0) or 78.0) + 3.1), 1)
    state["narrative_continuity_score"] = round(min(100.0, float(state.get("narrative_continuity_score", 80.0) or 80.0) + 2.4), 1)
    state["fragmentation_indicator"] = "low" if state["continuity_score"] >= 80 else "moderate" if state["continuity_score"] >= 60 else "elevated"
    state["last_updated_at"] = datetime.utcnow().isoformat()
    app_state["memory_continuity"] = state
    return state, invoked, consolidation_result


def _resolve_video_runtime_state():
    state = dict(_default_video_runtime_state())
    state.update(dict(app_state.get("video_runtime") or {}))
    intervals = [float(v) for v in list(state.get("frame_intervals_s", []) or []) if float(v) > 0]
    if intervals:
        avg_interval = sum(intervals) / max(1, len(intervals))
        state["fps_estimate"] = round(1.0 / max(0.001, avg_interval), 2)
    last_frame_at = state.get("last_frame_at")
    idle = _seconds_since(last_frame_at)
    state["camera_stream_status"] = "active" if idle < 3 else "warm" if idle < 12 else "idle"
    target_hz = max(24, min(120, int((dict(app_state.get("world_continuity") or {}).get("perception_cadence_hz", 60) or 60))))
    fps = float(state.get("fps_estimate", 0.0) or 0.0)
    ratio = fps / float(target_hz) if target_hz else 0.0
    state["render_sync_quality"] = "excellent" if ratio >= 0.92 else "good" if ratio >= 0.62 else "degraded" if fps > 0 else "unknown"
    codec = dict(app_state.get("codec_support") or _probe_codec_support())
    browser_caps = dict(codec.get("browser_capabilities") or {})
    missing_browser = [k for k, v in browser_caps.items() if v is False]
    summary = f"ffmpeg {'ready' if codec.get('ffmpeg_available') else 'missing'} Â· ffprobe {'ready' if codec.get('ffprobe_available') else 'missing'}"
    if missing_browser:
        summary += f" Â· browser missing {', '.join(missing_browser[:4])}"
    else:
        summary += " Â· browser probes ready"
    state["codec_readiness_summary"] = summary
    state["last_updated_at"] = datetime.utcnow().isoformat()
    app_state["video_runtime"] = state
    return state


def _resolve_chat_runtime_state(request_https=None):
    state = dict(_default_chat_runtime_state())
    state.update(dict(app_state.get("chat_runtime") or {}))
    samples = [max(0.0, float(v)) for v in list(state.get("response_latency_samples_ms", []) or [])]
    if samples:
        state["response_latency_ms_avg"] = round(sum(samples) / len(samples), 1)
    https_active = bool(_request_is_https() if request_https is None else request_https)
    if https_active:
        enc = "HTTPS active; encrypted transit confirmed"
    elif _TLS_CONFIGURED:
        enc = "TLS configured but request is not HTTPS"
    else:
        enc = "Local HTTP session (TLS not configured)"
    state["encryption_session_summary"] = enc
    if int(state.get("thread_turn_depth", 0) or 0) <= 0:
        try:
            state["thread_turn_depth"] = max(0, int(memory.get_interaction_count()))
        except Exception:
            state["thread_turn_depth"] = 0
    state["last_updated_at"] = datetime.utcnow().isoformat()
    app_state["chat_runtime"] = state
    return state


def _record_chat_runtime(sample_latency_ms=None, context_chars=0, request_https=None):
    state = _resolve_chat_runtime_state(request_https=request_https)
    samples = [max(0.0, float(v)) for v in list(state.get("response_latency_samples_ms", []) or [])]
    if sample_latency_ms is not None:
        samples.append(max(0.0, float(sample_latency_ms)))
    samples = samples[-32:]
    state["response_latency_samples_ms"] = samples
    if samples:
        state["response_latency_ms_avg"] = round(sum(samples) / len(samples), 1)
    context_chars = max(0, int(context_chars or 0))
    state["context_pressure_indicator"] = "high" if context_chars >= 9500 else "medium" if context_chars >= 5200 else "low"
    state["thread_turn_depth"] = max(0, int(state.get("thread_turn_depth", 0) or 0) + (1 if sample_latency_ms is not None else 0))
    state["last_turn_at"] = datetime.utcnow().isoformat() if sample_latency_ms is not None else state.get("last_turn_at")
    state["last_updated_at"] = datetime.utcnow().isoformat()
    app_state["chat_runtime"] = state
    return state


