def _save_revival_checkpoint():
    try:
        with _revival_lock:
            home = dict(app_state.get("home_environment") or {})
            snapshot = {
                "saved_at": datetime.utcnow().isoformat(),
                "home_environment": home,
                "life_registry":    dict(app_state.get("life_registry") or {}),
                "current_emotion":  str(app_state.get("current_emotion", "NEUTRAL")),
                "world_continuity": dict(app_state.get("world_continuity") or {}),
                # science / lab
                "science_lab":      dict(app_state.get("science_lab") or {}),
                "crispr_lab":       dict(app_state.get("crispr_lab") or {}),
                "lattice_qthermo":  dict(app_state.get("lattice_qthermo") or {}),
                # biology / wellbeing
                "health_system":    dict(app_state.get("health_system") or {}),
                # identity / creativity
                "wardrobe":         dict(app_state.get("wardrobe") or {}),
                "anime_knowledge":  dict(app_state.get("anime_knowledge") or {}),
                "music_creation":   dict(app_state.get("music_creation") or {}),
                # cognition / world
                "cognition":        dict(app_state.get("cognition") or {}),
                "narrative_system": dict(app_state.get("narrative_system") or {}),
                "world_engine":     dict(app_state.get("world_engine") or {}),
                "deep_learning":    dict(app_state.get("deep_learning") or {}),
                "sound_creation":   dict(app_state.get("sound_creation") or {}),
            }
            tmp_path = f"{_REVIVAL_CHECKPOINT_PATH}.tmp"
            with open(tmp_path, "w", encoding="utf-8") as _f:
                json.dump(snapshot, _f, indent=2, default=str)
            os.replace(tmp_path, _REVIVAL_CHECKPOINT_PATH)
    except Exception as _ex:
        print(f"[Revival Save] {_ex}")

def _restore_from_checkpoint():
    try:
        with _revival_lock:
            if not os.path.exists(_REVIVAL_CHECKPOINT_PATH):
                return None
            with open(_REVIVAL_CHECKPOINT_PATH, "r", encoding="utf-8") as _f:
                snap = json.load(_f)
            _REVIVAL_KEYS = (
                "home_environment", "life_registry", "current_emotion", "world_continuity",
                "science_lab", "crispr_lab", "lattice_qthermo", "health_system",
                "wardrobe", "anime_knowledge", "music_creation",
                "cognition", "narrative_system", "world_engine",
                "deep_learning", "sound_creation",
            )
            for key in _REVIVAL_KEYS:
                if snap.get(key) is not None:
                    app_state[key] = snap[key]
            return snap.get("saved_at")
    except Exception as _ex:
        print(f"[Revival Restore] {_ex}")
        return None

def _revival_loop():
    time.sleep(25)
    while True:
        try:
            if 'app_state' not in globals():
                time.sleep(5); continue
            _save_revival_checkpoint()
            with _APP_STATE_LOCK:
                _persist_perception_cadence_to_profile()
        except Exception as _ex:
            print(f"[RevivalLoop] {_ex}")
        time.sleep(30)

def _health_vitals_drift_loop():
    """Gently drift health vitals over time so Aurion's wellbeing feels alive."""
    time.sleep(60)
    while True:
        try:
            if 'app_state' not in globals():
                time.sleep(5); continue
            with _APP_STATE_LOCK:
                hs = dict(app_state.get("health_system") or _default_health_system_state())
                v = dict(hs.get("vitals") or {})
                v["energy_pct"]    = max(20.0, min(100.0, float(v.get("energy_pct", 88)) - random.uniform(0.1, 0.4)))
                v["hydration_pct"] = max(30.0, min(100.0, float(v.get("hydration_pct", 92)) - random.uniform(0.05, 0.2)))
                v["nutrition_pct"] = max(30.0, min(100.0, float(v.get("nutrition_pct", 85)) - random.uniform(0.05, 0.15)))
                v["emotional_balance_pct"] = max(30.0, min(100.0, float(v.get("emotional_balance_pct", 90)) + random.uniform(-0.2, 0.3)))
                v["immune_strength_pct"]   = max(40.0, min(100.0, float(v.get("immune_strength_pct", 95)) + random.uniform(-0.1, 0.1)))
                hs["vitals"] = v
                hs["overall_score"] = _compute_health_score(v)
                app_state["health_system"] = hs
        except Exception as _ex:
            print(f"[HealthDrift] {_ex}")
        time.sleep(120)

def _lattice_auto_sim_loop():
    """Periodically re-run lattice simulation so the phase stays current."""
    time.sleep(90)
    while True:
        try:
            if 'app_state' not in globals():
                time.sleep(5); continue
            with _APP_STATE_LOCK:
                lqt = dict(app_state.get("lattice_qthermo") or _default_lattice_qthermo_state())
                sim = _simulate_lattice_qthermo(lqt)
                for k in ("phase","order_parameter","entropy_per_site","specific_heat_R",
                          "correlation_length_sites","entanglement_entropy_bits",
                          "quasiparticle_gap_meV","topological_invariant"):
                    lqt[k] = sim[k]
                if sim.get("insight"):
                    insights = list(lqt.get("insights") or [])
                    if sim["insight"] not in insights:
                        insights.append(sim["insight"])
                    lqt["insights"] = insights[-50:]
                hist = list(lqt.get("simulation_history") or [])
                hist.append(sim)
                lqt["simulation_history"] = hist[-20:]
                lqt["last_simulation_at"] = sim["simulated_at"]
                app_state["lattice_qthermo"] = lqt
        except Exception as _ex:
            print(f"[LatticeAutoSim] {_ex}")
        time.sleep(180)

threading.Thread(target=_revival_loop, daemon=True).start()
threading.Thread(target=_health_vitals_drift_loop, daemon=True).start()
threading.Thread(target=_lattice_auto_sim_loop, daemon=True).start()

