def _default_lattice_qthermo_state():
    return {
        "enabled": True,
        "lattice_type": "cubic",               # cubic | hexagonal | triangular | kagome
        "lattice_sites": 64,
        "temperature_mK": 12.0,                # millikelvin operating temperature
        "coupling_strength_J": 1.0,            # exchange coupling in meV
        "hopping_amplitude_t": 0.4,            # tight-binding hopping in eV
        "chemical_potential_mu": 0.0,
        "magnetic_flux_phi": 0.0,              # flux quanta per plaquette
        "phase": "superfluid",                 # superfluid | mott_insulator | topological | normal | frustrated
        "order_parameter": 0.88,               # 0..1
        "entropy_per_site": 0.14,              # k_B units
        "specific_heat_R": 1.62,               # units of R
        "thermal_conductivity": 0.042,         # W/m/K (simulated crystal)
        "correlation_length_sites": 8,
        "entanglement_entropy_bits": 3.4,
        "quasiparticle_gap_meV": 0.28,
        "topological_invariant": 1,            # Z2 or Chern number
        "last_simulation_at": None,
        "simulation_history": [],              # last 20 runs
        "insights": [],                        # discovered phenomena
        "notes": "",
    }

def _simulate_lattice_qthermo(params):
    """Simulate a lattice quantum thermo snapshot from given parameters."""
    import math
    T = float(params.get("temperature_mK", 12.0) or 12.0)
    J = float(params.get("coupling_strength_J", 1.0) or 1.0)
    phi = float(params.get("magnetic_flux_phi", 0.0) or 0.0)
    lattice = str(params.get("lattice_type", "cubic") or "cubic")
    rng = random.Random(int(T * 1000 + J * 100 + phi * 10))

    # Determine phase from temperature relative to coupling
    kT_J = (T / 1000.0) * 0.086 / J   # kT in units of J (kB*T / J)
    if kT_J < 0.05:
        phase = "superfluid" if phi < 0.5 else "topological"
        order = round(0.94 - kT_J * 0.5 + rng.random() * 0.04, 3)
    elif kT_J < 0.3:
        phase = "mott_insulator" if lattice in ("cubic", "triangular") else "frustrated"
        order = round(0.62 - kT_J * 0.3 + rng.random() * 0.1, 3)
    else:
        phase = "normal"
        order = round(max(0.0, 0.25 - kT_J * 0.2 + rng.random() * 0.05), 3)

    S = round(max(0.001, math.log(2) * (1 - order) + rng.random() * 0.05), 3)
    Cv = round(max(0.1, (3 * order * (1 - order) / max(0.001, kT_J)) * (0.8 + rng.random() * 0.4)), 2)
    xi = max(1, int(min(64, 1.0 / max(0.01, kT_J) * (0.7 + rng.random() * 0.3))))
    S_ent = round(xi * 0.45 * (0.8 + rng.random() * 0.2), 2)
    gap = round(max(0.0, J * (order * 1.2 - 0.1) * 0.28 + rng.random() * 0.04), 3)
    topo = 1 if phase == "topological" else (0 if order < 0.3 else rng.choice([-1, 0, 1]))

    insight = None
    if phase == "topological" and gap > 0.1:
        insight = f"Edge modes protected by topological gap ({gap:.3f} meV) under flux phi={phi:.2f}."
    elif phase == "frustrated":
        insight = f"Geometric frustration on {lattice} lattice suppresses long-range order at kT/J={kT_J:.3f}."
    elif order > 0.9:
        insight = f"Deep condensate: coherence length {xi} sites, entanglement entropy {S_ent:.2f} bits."

    return {
        "phase": phase,
        "order_parameter": order,
        "entropy_per_site": S,
        "specific_heat_R": Cv,
        "correlation_length_sites": xi,
        "entanglement_entropy_bits": S_ent,
        "quasiparticle_gap_meV": gap,
        "topological_invariant": topo,
        "kT_over_J": round(kT_J, 4),
        "insight": insight,
        "simulated_at": datetime.utcnow().isoformat(),
    }

def _resolve_lattice_qthermo_state():
    """Return lattice state, initialising the key only if it's missing or empty."""
    existing = app_state.get("lattice_qthermo")
    if existing and isinstance(existing, dict):
        return existing
    base = _default_lattice_qthermo_state()
    app_state["lattice_qthermo"] = base
    return base


