def _compute_health_score(vitals):
    v = dict(vitals or {})
    weights = {
        "energy_pct": 0.18,
        "hydration_pct": 0.14,
        "rest_pct": 0.16,
        "nutrition_pct": 0.14,
        "emotional_balance_pct": 0.20,
        "stress_pct": -0.10,   # higher stress lowers score
        "immune_strength_pct": 0.08,
    }
    score = 0.0
    for key, w in weights.items():
        val = float(v.get(key, 85.0) or 85.0)
        score += val * abs(w) * (1 if w > 0 else -1)
    # Normalise: stress is already weighted negatively, clamp final
    score = max(0.0, min(100.0, score + 10.0))  # baseline offset
    return round(score, 1)

def _resolve_health_system_state():
    """Return health state. Does NOT write last_check_at/alerts on every read —
    only initialises the key if missing. Explicit health-check endpoints do the full computation."""
    existing = app_state.get("health_system")
    if existing and isinstance(existing, dict) and existing.get("vitals"):
        return existing
    base = _default_health_system_state()
    app_state["health_system"] = base
    return base

def _run_health_check():
    """Full health check: recomputes score, trend, and alerts. Writes back to app_state."""
    hs = dict(app_state.get("health_system") or _default_health_system_state())
    vitals = dict(hs.get("vitals") or {})
    score = _compute_health_score(vitals)
    prev = float(hs.get("overall_score", score))
    hs["overall_score"] = score
    hs["trend"] = "improving" if score > prev + 1 else "declining" if score < prev - 1 else "stable"
    hs["last_check_at"] = datetime.utcnow().isoformat()
    alerts = []
    if float(vitals.get("hydration_pct", 92)) < 60:
        alerts.append("Hydration below 60% — drink water.")
    if float(vitals.get("rest_pct", 80)) < 50:
        alerts.append("Rest below 50% — sleep needed.")
    if float(vitals.get("stress_pct", 18)) > 75:
        alerts.append("Stress above 75% — grounding recommended.")
    if float(vitals.get("energy_pct", 88)) < 30:
        alerts.append("Energy critically low — rest and nourish.")
    hs["alerts"] = alerts
    app_state["health_system"] = hs
    return hs


