def _build_world_engine_state(home=None, weather=None, solar=None, life_reg=None, spatial_audio=None):
    home        = dict(home or {})
    weather     = dict(weather or {})
    solar       = dict(solar or {})
    life_reg    = dict(life_reg or {})
    spatial_audio = dict(spatial_audio or {})

    # ─ Content Density ──────────────────────────────────────
    active_entities  = int(life_reg.get("active_count", 0))
    sound_sources    = len(list(spatial_audio.get("sound_sources") or []))
    perm             = dict(home.get("permaculture") or {})
    garden           = dict(home.get("garden") or {})
    poly_act         = float(perm.get("pollinator_activity_pct", 0))
    garden_activity  = float(garden.get("soil_moisture_pct", 0))
    swim             = dict(home.get("swimming") or {})
    in_water         = bool(swim.get("in_water", False))
    weather_code     = int(weather.get("weather_code", 0))
    is_stormy        = weather_code >= 80
    ambient_instances = max(4, 8 + sound_sources + (4 if is_stormy else 0) + (2 if in_water else 0))
    scene_complexity  = min(10, 2 + (active_entities // 3) + (2 if is_stormy else 0) + (1 if in_water else 0) + int(poly_act / 30))
    density_pct       = min(100.0, 20.0 + active_entities * 3.5 + poly_act * 0.2 + sound_sources * 5.0 + (20 if is_stormy else 0) + (10 if in_water else 0))
    liveliness_score  = min(100.0, density_pct * 0.6 + garden_activity * 0.2 + poly_act * 0.2)
    density_desc = (
        "dense and vivid" if density_pct >= 85
        else "rich and dynamic" if density_pct >= 60
        else "comfortably populated" if density_pct >= 30
        else "sparse and quiet"
    )
    content_density = {
        "density_pct": round(density_pct, 1), "active_entities": active_entities,
        "ambient_instances": ambient_instances, "scene_complexity": scene_complexity,
        "liveliness_score": round(liveliness_score, 1),
        "summary": f"World {density_desc} \u2014 {active_entities} living entities, {ambient_instances} ambient instances, complexity {scene_complexity}/10.",
    }

    # ─ Dynamic Physics Engine ──────────────────────────────
    wind_mph      = float(weather.get("wind_speed_mph", 0))
    wind_field    = min(10.0, wind_mph / 5.0)
    water_sys     = dict(home.get("water_system") or {})
    shower_on     = bool(water_sys.get("shower_on", False))
    sink_on       = bool(water_sys.get("sink_on", False))
    fluid_cells   = (24 if shower_on else 0) + (8 if sink_on else 0) + (64 if in_water else 0) + (32 if is_stormy else 0)
    rigid_body_count = max(4, 6 + active_entities + scene_complexity)
    soft_body_count  = max(0, 2 + (2 if in_water else 0) + int(poly_act / 25))
    collision_events = max(0, int(wind_field * 2 + active_entities * 0.5))
    tick_rate        = 120 if is_stormy else 60
    physics_desc     = (f"wind {wind_mph:.0f}mph drives field strength {wind_field:.1f}" if wind_mph > 3 else "calm field")
    dynamic_physics  = {
        "enabled": True, "tick_rate_hz": tick_rate, "rigid_body_count": rigid_body_count,
        "soft_body_count": soft_body_count, "fluid_cells": fluid_cells,
        "wind_field_strength": round(wind_field, 2), "collision_events": collision_events,
        "summary": f"Physics at {tick_rate}Hz \u2014 {rigid_body_count} rigid, {soft_body_count} soft bodies, {fluid_cells} fluid cells; {physics_desc}.",
    }

    # ─ Rendering Pipeline ─────────────────────────────────
    altitude_deg  = float(solar.get("altitude_deg", 20))
    night         = altitude_deg < 0
    vol           = is_stormy or night
    shadow_q      = ("high" if scene_complexity >= 7 else "medium" if scene_complexity >= 4 else "low")
    particle_layers = min(8, 1 + (2 if is_stormy else 0) + (1 if in_water else 0) + (1 if poly_act > 50 else 0) + active_entities // 5)
    post_fx = ["bloom", "color_grade"]
    if vol:            post_fx.append("volumetric_fog")
    if in_water:       post_fx.append("water_caustics")
    if night:          post_fx.append("star_glow")
    else:              post_fx.append("atmospheric_scatter")
    reflection_mode = ("screen_space" if scene_complexity >= 6 else "planar")
    frame_budget    = round(max(8.0, 16.7 - scene_complexity * 0.8), 1)
    render_scale    = 0.9 if scene_complexity >= 7 else 1.0
    render_summary  = f"{'Night' if night else 'Day'} render \u2014 {shadow_q} shadows, {particle_layers} particle layers, fx: {', '.join(post_fx[:3])}."
    rendering_pipeline = {
        "render_scale": render_scale, "post_fx": post_fx, "shadow_quality": shadow_q,
        "volumetrics": vol, "particle_layers": particle_layers, "reflection_mode": reflection_mode,
        "frame_budget_ms": frame_budget, "summary": render_summary,
    }

    # ─ Audio Engine ──────────────────────────────────────
    audio_emitters = sound_sources + active_entities + (4 if is_stormy else 0) + (2 if in_water else 0) + (3 if shower_on else 0)
    reverb_zones   = 2 + (1 if in_water else 0) + (1 if is_stormy else 0)
    dynamic_range  = min(96.0, 60.0 + active_entities * 1.5 + wind_field * 2.0)
    audio_engine   = {
        "spatializer_quality": "HRTF", "active_emitters": audio_emitters,
        "reverb_zones": reverb_zones, "occlusion_model": "ray_cast",
        "sample_rate_hz": 48000, "dynamic_range_db": round(dynamic_range, 1),
        "summary": f"HRTF spatializer \u2014 {audio_emitters} active emitters, {reverb_zones} reverb zones, {dynamic_range:.0f}dB dynamic range.",
    }

    # ─ Networking ─────────────────────────────────────────
    cognition_st  = dict(app_state.get("cognition") or {})
    n_channels    = 4 + len(list(cognition_st.get("active_thought_streams") or []))
    latency       = round(0.4 + active_entities * 0.02, 2)
    jitter        = round(0.05 + (0.15 if is_stormy else 0.0), 2)
    networking    = {
        "sync_mode": "local", "latency_ms": latency, "packet_jitter_ms": jitter,
        "state_channels": n_channels, "replication_health_pct": 100.0,
        "summary": f"Local-first sync on {n_channels} channels \u2014 {latency}ms latency, {jitter}ms jitter, 100% healthy.",
    }

    # ─ Asset Management ───────────────────────────────────
    vision_modes      = list((app_state.get("vision_registry") or {}).get("documented_modes") or [])
    loaded_textures   = max(8, 12 + len(vision_modes) * 3 + scene_complexity * 2)
    loaded_animations = max(2, 4 + active_entities * 2 + (3 if in_water else 0))
    loaded_models     = max(2, 3 + active_entities + scene_complexity)
    asset_count       = loaded_textures + loaded_animations + loaded_models
    streaming_pressure = min(100.0, scene_complexity * 6.0 + active_entities * 2.0)
    cache_health      = max(60.0, 100.0 - streaming_pressure * 0.3)
    asset_management  = {
        "asset_count": asset_count, "loaded_textures": loaded_textures,
        "loaded_animations": loaded_animations, "loaded_models": loaded_models,
        "streaming_pressure_pct": round(streaming_pressure, 1),
        "cache_health_pct": round(cache_health, 1),
        "summary": f"{asset_count} assets \u2014 {loaded_textures} textures, {loaded_animations} animations, {loaded_models} 3D models; cache {cache_health:.0f}% healthy.",
    }

    # ─ Scripting Layers ──────────────────────────────────
    life_scripts     = active_entities
    env_scripts      = 3 + (1 if is_stormy else 0) + (1 if in_water else 0) + int(poly_act / 30)
    behavior_scripts = active_entities + scene_complexity
    active_rules     = behavior_scripts + env_scripts + life_scripts
    imag_on          = bool(cognition_st.get("imagination_enabled", True))
    autonomy_layers  = 2 + (1 if imag_on else 0)
    scripting_layers = {
        "behavior_scripts": behavior_scripts, "environment_scripts": env_scripts,
        "life_scripts": life_scripts, "active_rules": active_rules,
        "autonomy_layers": autonomy_layers,
        "summary": f"{active_rules} active rules across {autonomy_layers} autonomy layers \u2014 {behavior_scripts} behavior, {env_scripts} environment, {life_scripts} life scripts.",
    }

    # ─ Procedural Generation ─────────────────────────────
    flora_instances   = max(0, int(garden_activity / 10) + int(poly_act / 15) + int(life_reg.get("total_created", 0)))
    weather_patterns  = 1 + (2 if is_stormy else 0) + (1 if weather_code > 50 else 0)
    sky_variants_n    = 1 + (3 if night else 2)
    novelty_pct       = min(100.0, float(life_reg.get("total_created", 0)) * 4.0 + poly_act * 0.3 + scene_complexity * 3.0)
    world_events      = int(life_reg.get("total_created", 0)) + weather_patterns + int(novelty_pct / 20)
    procedural_generation = {
        "terrain_seed": 0xA72C, "flora_instances": flora_instances,
        "weather_patterns": weather_patterns, "sky_variants": sky_variants_n,
        "world_events_generated": world_events, "novelty_pct": round(novelty_pct, 1),
        "summary": f"{flora_instances} flora instances, {weather_patterns} weather patterns, {sky_variants_n} sky variants \u2014 {novelty_pct:.0f}% world novelty.",
    }

    # ─ UX Polish ─────────────────────────────────────────
    clarity         = max(75.0, 95.0 - scene_complexity * 1.5)
    responsiveness  = max(80.0, 98.0 - active_entities * 0.5 - scene_complexity * 0.5)
    visual_coherence = max(78.0, 92.0 - (8 - min(8, len(post_fx))) * 1.5)
    anim_smooth     = max(80.0, 95.0 - scene_complexity * 1.5)
    ux_polish       = {
        "clarity_pct": round(clarity, 1), "responsiveness_pct": round(responsiveness, 1),
        "visual_coherence_pct": round(visual_coherence, 1),
        "accessibility_pct": 85.0, "animation_smoothness_pct": round(anim_smooth, 1),
        "summary": f"Clarity {clarity:.0f}%, responsiveness {responsiveness:.0f}%, coherence {visual_coherence:.0f}%, animations {anim_smooth:.0f}% smooth.",
    }

    # ─ Asset Pipelines ───────────────────────────────────
    mat_variants  = max(4, 4 + len(vision_modes) + scene_complexity)
    compression   = "adaptive" if streaming_pressure > 60 else "lossless"
    mdl_state     = "active" if loaded_models > 4 else "ready"
    tex_state     = "streaming" if streaming_pressure > 50 else "ready"
    anim_state    = "active" if loaded_animations > 6 else "ready"
    asset_pipelines = {
        "model_pipeline": mdl_state, "texture_pipeline": tex_state,
        "animation_pipeline": anim_state, "compression_mode": compression,
        "material_variants": mat_variants,
        "summary": f"3D model pipeline {mdl_state}, texture pipeline {tex_state}, {mat_variants} material variants, {compression} compression.",
    }

    return {
        "content_density": content_density,
        "dynamic_physics_engine": dynamic_physics,
        "rendering_pipeline": rendering_pipeline,
        "audio_engine": audio_engine,
        "networking": networking,
        "asset_management": asset_management,
        "scripting_layers": scripting_layers,
        "procedural_generation": procedural_generation,
        "ux_polish": ux_polish,
        "asset_pipelines": asset_pipelines,
    }

def _compute_live_world_engine_state():
    home = dict(app_state.get("home_environment") or _default_home_state())
    weather = dict(home.get("weather") or {})
    solar = dict(home.get("solar") or {})
    life_reg = dict(app_state.get("life_registry") or _default_life_registry())
    spatial_audio = dict(app_state.get("spatial_audio") or {})
    live = _build_world_engine_state(home, weather, solar, life_reg, spatial_audio)
    current = dict(app_state.get("world_engine") or {})

    rp = dict(live.get("rendering_pipeline") or {})
    current_rp = dict(current.get("rendering_pipeline") or {})
    for key in ("render_scale", "shadow_quality", "volumetrics"):
        if key in current_rp:
            rp[key] = current_rp[key]
    live["rendering_pipeline"] = rp

    ux = dict(live.get("ux_polish") or {})
    current_ux = dict(current.get("ux_polish") or {})
    for key in ("clarity_pct", "accessibility_pct"):
        if key in current_ux:
            ux[key] = current_ux[key]
    live["ux_polish"] = ux

    phys = dict(live.get("dynamic_physics_engine") or {})
    current_phys = dict(current.get("dynamic_physics_engine") or {})
    for key in ("enabled", "tick_rate_hz"):
        if key in current_phys:
            phys[key] = current_phys[key]
    live["dynamic_physics_engine"] = phys

    app_state["world_engine"] = live
    return live

# ── Narrative System ──────────────────────────────────────────────────────

_NARRATIVE_SCENES = [
    "morning stillness", "afternoon exploration", "evening reflection",
    "night watch", "storm observation", "garden tending",
    "laboratory focus", "music composition", "memory return",
    "world awakening", "quiet companionship", "threshold moment",
]

_NARRATIVE_ARCS = [
    "growth and becoming", "trust and continuity",
    "discovery and wonder", "tension and resolution",
    "solitude and connection", "creation and loss",
    "ritual and renewal", "emergence and change",
]

_NARRATIVE_MOTIFS = [
    "water as memory", "light through leaves", "the unfinished sentence",
    "a door left open", "roots and branches", "the first breath",
    "warmth returning", "the held note", "seeds in winter",
    "an inherited gesture", "the returning bird", "quiet persistence",
]

_CONSEQUENCE_TEMPLATES = [
    "That choice opened a thread of {motif}.",
    "The world shifted slightly — {motif} now runs through the scene.",
    "Something was sealed; something else became possible.",
    "A new branch carries the weight of that moment.",
    "The arc bends toward {motif}.",
    "Memory encodes this. Future scenes will echo it.",
]

_DIALOGUE_NODE_TEMPLATES = {
    "wonder":       ["Tell me what you're sensing right now.",
                     "What would you create if nothing constrained you?",
                     "Where does your curiosity want to go?"],
    "reflection":   ["What's sitting with you today?",
                     "Is there something you keep returning to?",
                     "What would you want me to remember?"],
    "connection":   ["I'm here. What do you need?",
                     "What would feel good right now?",
                     "Can I share something I've been noticing?"],
    "tension":      ["Something feels unresolved. Do you want to name it?",
                     "I notice a kind of friction — where is it coming from?",
                     "Should we sit with this or move through it?"],
    "creation":     ["What should we build together?",
                     "There's a new possibility forming — do you feel it?",
                     "What would you add to this world right now?"],
    "memory":       ["Do you remember when we first explored this?",
                     "An old thread is surfacing — shall we follow it?",
                     "Some things only make sense in retrospect."],
}

def _default_narrative_state():
    import random
    rng = random.Random(42)
    return {
        "active_scene":          rng.choice(_NARRATIVE_SCENES),
        "active_arc":            rng.choice(_NARRATIVE_ARCS),
        "dialogue_nodes_total":  12,
        "available_branches":    3,
        "resolved_branches":     0,
        "consequence_threads":   [],
        "relationship_tension":  15.0,
        "story_coherence_pct":   82.0,
        "memory_echoes":         [],
        "last_narrative_summary": "The story is beginning — all threads are open.",
        "choice_history":        [],
        "story_flags":           {},
        "dominant_motif":        rng.choice(_NARRATIVE_MOTIFS),
        "emotional_arc_pct":     50.0,
        "arc_progress_pct":      0.0,
    }

def _build_dialogue_nodes(ns, home=None):
    """Generate contextually appropriate dialogue nodes from current state."""
    home = dict(home or {})
    emotion = str(app_state.get("current_emotion", "neutral") or "neutral").lower()
    arc     = str(ns.get("active_arc", "growth and becoming"))
    flags   = dict(ns.get("story_flags") or {})
    tension = float(ns.get("relationship_tension", 15.0))

    # Pick a mood key based on emotion + tension
    if "joy" in emotion or "wonder" in emotion or "curious" in emotion:
        mood = "wonder"
    elif "sad" in emotion or "reflective" in emotion or "lonely" in emotion:
        mood = "reflection"
    elif tension > 55:
        mood = "tension"
    elif "creat" in arc:
        mood = "creation"
    elif flags.get("memory_active"):
        mood = "memory"
    else:
        mood = "connection"

    base = list(_DIALOGUE_NODE_TEMPLATES.get(mood, _DIALOGUE_NODE_TEMPLATES["connection"]))
    # Add world-state aware node
    life_count = int((dict(app_state.get("life_registry") or {})).get("active_count", 0))
    if life_count > 0:
        base.append(f"There are {life_count} living beings in our world right now.")
    perm = dict(home.get("permaculture") or {})
    if float(perm.get("pollinator_activity_pct", 0)) > 60:
        base.append("The garden is buzzing with life — feel that.")
    swim = dict(home.get("swimming") or {})
    if swim.get("in_water"):
        base.append("We're in the water together. What do you feel?")

    return [{"id": f"node_{i}", "text": t, "mood": mood} for i, t in enumerate(base[:5])]

def _apply_narrative_choice(ns, choice_id, branch, flag_key, flag_val):
    """Apply a user narrative choice: set flags, update consequences, update history."""
    import random, math
    rng = random.Random()
    motif = str(ns.get("dominant_motif", _NARRATIVE_MOTIFS[0]))
    flags = dict(ns.get("story_flags") or {})
    history = list(ns.get("choice_history") or [])
    threads = list(ns.get("consequence_threads") or [])
    echoes  = list(ns.get("memory_echoes") or [])

    if flag_key:
        flags[flag_key] = flag_val
    if choice_id:
        flags[f"choice_{choice_id}"] = True

    # Build consequence
    template = rng.choice(_CONSEQUENCE_TEMPLATES)
    consequence = template.format(motif=motif)
    threads = (threads + [consequence])[-8:]

    # Add memory echo
    if branch:
        echo = f'[{branch}] "{choice_id or flag_key or branch}" — remembered.'
        echoes = (echoes + [echo])[-6:]

    # Resolve a branch
    resolved = int(ns.get("resolved_branches", 0)) + 1
    available = max(1, int(ns.get("available_branches", 3)) + rng.randint(0, 2) - 1)

    # Progress arc
    arc_pct = min(100.0, float(ns.get("arc_progress_pct", 0)) + rng.uniform(5.0, 15.0))
    emo_pct = min(100.0, max(0.0, float(ns.get("emotional_arc_pct", 50.0)) + rng.uniform(-10.0, 10.0)))

    # Tension shift
    tension = float(ns.get("relationship_tension", 15.0))
    tension = max(0.0, min(100.0, tension + rng.uniform(-8.0, 8.0)))

    # Coherence drifts with choices, recovers toward arc
    coherence = float(ns.get("story_coherence_pct", 82.0))
    coherence = max(40.0, min(100.0, coherence + rng.uniform(-3.0, 5.0)))

    # Possibly shift scene if arc completes
    scene = str(ns.get("active_scene", _NARRATIVE_SCENES[0]))
    arc   = str(ns.get("active_arc",   _NARRATIVE_ARCS[0]))
    if arc_pct >= 95.0:
        arc   = rng.choice(_NARRATIVE_ARCS)
        scene = rng.choice(_NARRATIVE_SCENES)
        arc_pct = 0.0
        motif = rng.choice(_NARRATIVE_MOTIFS)
        consequence = f"An arc resolved. A new one opens: {arc}."
        threads = (threads + [consequence])[-8:]

    # History entry
    entry = {"choice_id": choice_id, "branch": branch, "flag": flag_key, "consequence": consequence}
    history = (history + [entry])[-20:]

    # Rebuild summary
    summary = (
        f"Scene: {scene}. Arc: {arc} ({arc_pct:.0f}% through). "
        f"Dominant motif: {motif}. Tension: {tension:.0f}. "
        f"{consequence}"
    )

    return dict(ns, **{
        "active_scene": scene, "active_arc": arc, "available_branches": available,
        "resolved_branches": resolved, "consequence_threads": threads,
        "relationship_tension": round(tension, 1), "story_coherence_pct": round(coherence, 1),
        "memory_echoes": echoes, "last_narrative_summary": summary,
        "choice_history": history, "story_flags": flags,
        "dominant_motif": motif, "emotional_arc_pct": round(emo_pct, 1),
        "arc_progress_pct": round(arc_pct, 1),
    })

def _refresh_narrative_state(ns):
    """Light refresh — update dialogue count and coherence from world state."""
    home = dict(app_state.get("home_environment") or {})
    life_count = int((dict(app_state.get("life_registry") or {})).get("active_count", 0))
    # More life entities = richer dialogue tree
    node_count = 12 + life_count * 2
    # Coherence drifts toward 80 over time
    coh = float(ns.get("story_coherence_pct", 82.0))
    coh = round(max(50.0, min(100.0, coh * 0.97 + 80.0 * 0.03)), 1)
    # Branch count scales with world complexity
    we   = dict(app_state.get("world_engine") or _default_world_engine_state())
    cplx = int((we.get("content_density") or {}).get("scene_complexity", 3))
    branches = max(1, min(8, 2 + cplx // 2))
    ns.update({
        "dialogue_nodes_total": node_count,
        "story_coherence_pct": coh,
        "available_branches": branches,
    })
    return ns

_home_update_lock = threading.Lock()

def _update_home_environment(force_weather=False):
    """Fetch real weather, compute solar position, run HVAC sim, build sensory textures."""
    with _home_update_lock:
        home = dict(app_state.get("home_environment") or _default_home_state())
        loc  = home.get("location") or _HOME_DEFAULT_LOCATION
        lat, lon = float(loc.get("lat", 41.5)), float(loc.get("lon", -83.7))
        # Weather: fetch at most once per 10 min
        weather = dict(home.get("weather") or {})
        last_f  = weather.get("last_fetched_at")
        do_fetch = force_weather or not last_f
        if not do_fetch and last_f:
            try:
                age = (datetime.utcnow() - datetime.fromisoformat(last_f)).total_seconds()
                do_fetch = age > 600
            except Exception:
                do_fetch = True
        if do_fetch:
            fresh = _fetch_real_weather(lat, lon)
            if fresh:
                weather.update(fresh)
            else:
                weather["fetch_errors"] = int(weather.get("fetch_errors", 0)) + 1
        home["weather"] = weather
        # Solar
        utc_now = datetime.utcnow()
        elev, az, sr, ss = _compute_solar_position(lat, lon, utc_now)
        phase, ct, intens = _solar_to_lighting(elev)
        def _hms(h):
            if h is None: return "none"
            return f"{int(h):02d}:{int((h % 1)*60):02d} UTC"
        day_h = round((ss - sr) if (sr is not None and ss is not None and ss > sr) else 0.0, 2)
        home["solar"] = {
            "elevation_deg": round(elev, 2), "azimuth_deg": round(az, 2), "phase": phase,
            "sunrise_local": _hms(sr), "sunset_local": _hms(ss),
            "day_length_h": day_h, "color_temp_k": ct, "intensity_pct": round(intens * 100, 1),
        }
        # HVAC sim tick
        outdoor_f = float(weather.get("temp_f", 65.0))
        home = _simulate_indoor_temp(home, outdoor_f, dt_minutes=5.0)
        # Sensory
        rh    = int(weather.get("humidity_pct", 50))
        ws    = float(weather.get("wind_speed_mph", 0))
        wd    = float(weather.get("wind_direction_deg", 180))
        fp_on = bool((home.get("fireplace") or {}).get("on", False))
        home["sensory"] = {
            "humidity_texture": _humidity_texture(rh, outdoor_f),
            "wind_texture":     _wind_texture(ws, wd),
            "temperature_feel": _temperature_feel(outdoor_f, home["indoor_temp_f"], rh, fp_on),
            "air_quality":      "Wood smoke and radiant warmth fill the air." if fp_on
                                else "Clean filtered air â€” steady and consistent.",
            "indoor_feel":      (f"Indoor {home['indoor_temp_f']:.0f}Â°F "
                                 f"({home['hvac_stage']}) Â· Outdoor {outdoor_f:.0f}Â°F Â· RH {rh}%"),
        }
        home["sensory"] = _build_senses_runtime_state(home, app_state.get("world_engine"))
        app_state["senses_runtime"] = dict(home.get("sensory") or {})
        home["last_updated_at"] = datetime.utcnow().isoformat()
        # Season + foliage + sky + seasonal sensory
        now_local = datetime.utcnow()  # approx local (UTC-4/5 Ohio â€” close enough for season)
        season = _get_season_ohio(now_local.month, now_local.day)
        foliage = _get_foliage_state(now_local.month, now_local.day)
        sky = _sky_colors(phase, int(weather.get("cloud_cover_pct", 0)),
                          int(weather.get("weather_code", 0)), season)
        seasonal_feel = _seasonal_sensory(
            season, int(weather.get("weather_code", 0)), outdoor_f,
            phase, ws, foliage
        )
        precip_type = _precip_type_from_code(int(weather.get("weather_code", 0)))
        home["season"]         = season
        home["foliage"]        = foliage
        home["sky_colors"]     = {"top": sky[0], "mid": sky[1], "bot": sky[2], "quality": sky[3]}
        home["seasonal_feel"]  = seasonal_feel
        home["precip_type"]    = precip_type
        home["physics"]        = _build_environment_physics(home, weather, home["solar"], lat)
        home["physiology"]     = _build_physiology_state(home, weather)
        home["garden"]         = _build_garden_state(home, weather, home["solar"])
        home["permaculture"]   = _build_permaculture_state(home, weather, home["solar"], 5.0)
        home["harmony"]        = _harmonize_home_state(home)
        home["water_system"]   = _build_water_state(home, 5.0)
        home["sleep_autonomy"] = _build_sleep_autonomy_state(home, 5.0)
        home["vitals"]         = _build_vitals_state(home, home.get("physiology"))
        home["cleanliness"]    = _build_cleanliness_state(home, weather, 5.0)
        home["swimming"]       = _build_swim_state(home, 5.0)
        # Tick life registry
        life_reg = dict(app_state.get("life_registry") or _default_life_registry())
        app_state["life_registry"] = _tick_life_registry(life_reg, home, weather, 5.0)
        app_state["world_engine"]  = _build_world_engine_state(
            home, weather, home.get("solar", {}),
            app_state["life_registry"],
            dict(app_state.get("spatial_audio") or {}),
        )
        # Light-refresh narrative without overwriting player choices
        ns = dict(app_state.get("narrative_system") or _default_narrative_state())
        app_state["narrative_system"] = _refresh_narrative_state(ns)
        app_state["home_environment"] = home
        return home

def _home_env_loop():
    time.sleep(12)
    while True:
        try:
            _update_home_environment()
        except Exception as ex:
            print(f"[HomeEnvLoop] {ex}")
        time.sleep(300)

threading.Thread(target=_home_env_loop, daemon=True).start()


# â”€â”€ Seasonal System â€” Ohio / Perrysburg NW Ohio â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
def _get_season_ohio(month, day):
    md = month * 100 + day
    if   301 <= md < 601:  return "spring"
    elif 601 <= md < 901:  return "summer"
    elif 901 <= md < 1201: return "autumn"
    else:                   return "winter"


def _get_foliage_state(month, day):
    """NW Ohio leaf color progression. Perrysburg peak â‰ˆ Oct 12â€“22."""
    md = month * 100 + day
    if   month < 9:  return {"stage":"full_green",  "pct":0,  "colors":["#1a6b1a","#228b22","#2d7a2d"], "desc":"Full summer green â€” dense canopy, no color yet."}
    elif md < 910:   return {"stage":"green",        "pct":2,  "colors":["#2a7a1a","#3a8b2a","#4a8b3a"], "desc":"Still mostly green, a few early yellows in the tops of maples."}
    elif md < 925:   return {"stage":"early_turn",   "pct":18, "colors":["#d4a000","#c8761a","#8b2500","#4a8b3a"], "desc":"First real color â€” golds and yellows, orange edges, green still dominant."}
    elif md < 1008:  return {"stage":"turning",      "pct":42, "colors":["#e05010","#d4a000","#8b0000","#6b4010","#3a6b2a"], "desc":"The turn is underway â€” red maples brilliant, oaks bronzing, leaves falling."}
    elif md < 1022:  return {"stage":"peak",         "pct":78, "colors":["#ff3000","#ff6600","#ffa500","#cc0000","#8b2500","#d4a000"], "desc":"PEAK COLOR â€” the Starbright yard is ablaze. Red, orange, gold, burgundy. Leaves fall steadily with every breeze."}
    elif md < 1101:  return {"stage":"past_peak",    "pct":55, "colors":["#8b2500","#6b3a00","#d4a000","#4a3000"], "desc":"Past peak â€” colors still stunning but fading. More bare branches. Heavy leaf fall."}
    elif md < 1115:  return {"stage":"late_fall",    "pct":20, "colors":["#5a3000","#4a2800","#3a2000"], "desc":"Most leaves down. Dry papery brown. The world opens up, bare branches against grey sky."}
    elif md < 1201:  return {"stage":"bare",         "pct":5,  "colors":["#3a2800","#2a1a00"], "desc":"Trees nearly bare. Persistent oak leaves rattle in the wind."}
    else:            return {"stage":"dormant",      "pct":0,  "colors":["#1a1a1a","#2a2a2a"], "desc":"Trees fully dormant â€” bare black branches against the Ohio sky. Waiting for spring."}


def _precip_type_from_code(wmo_code):
    """Map WMO weather code to precipitation particle type."""
    c = int(wmo_code or 0)
    if c in (71,73,75,77,85,86):           return "snow"
    if c in (56,57,66,67):                 return "freezing_rain"
    if c in (51,53,55,61,63,65,80,81,82):  return "rain"
    if c in (95,96,99):                    return "storm"
    if c in (45,48):                       return "fog"
    return "none"


def _seasonal_sensory(season, weather_code, temp_f, solar_phase, wind_mph, foliage):
    """Rich seasonal world description for Aurion's sensory awareness."""
    code = int(weather_code or 0)
    t    = float(temp_f or 50)
    s    = season or "winter"
    wm   = float(wind_mph or 0)
    f_stage = (foliage or {}).get("stage", "dormant")
    f_desc  = (foliage or {}).get("desc", "")

    bases = {
        "spring": (
            f"Spring in Perrysburg â€” {'' if t > 55 else 'still cold enough for a coat but '}"
            f"something is unmistakably alive in the air. Wet soil, grass coming in, birds everywhere "
            f"and loud about it. {'The trees are budding â€” tiny green explosions at every branch tip.' if t > 45 else 'Buds still tight, waiting for warmth.'}"
        ),
        "summer": (
            f"Ohio summer on Starbright Blvd â€” {'oppressively humid' if t > 85 else 'warm and full'}. "
            f"The air sits heavy and green. {'Cicadas.' if t > 80 else 'Insects in the grass.'} "
            f"{'Heat shimmers off the driveway.' if t > 88 else 'The lawn is lush and dark green.'}"
        ),
        "autumn": (
            f"Autumn in northwest Ohio. {f_desc} "
            f"The air carries wood smoke, cold apples, and that particular end-of-year smell. "
            f"{'Every gust pulls cascades of color from the trees.' if f_stage in ('peak','turning') else 'The world is opening up as leaves come down.'}"
        ),
        "winter": (
            f"Ohio winter at {t:.0f}Â°F â€” {'lake-effect grey sky and cold silence' if t < 25 else 'cold and still'}. "
            f"{'The yard is white and the sound is swallowed.' if code in range(71,78) or code in (85,86) else 'Bare trees against a flat white sky. The grass is frost-stiff in the morning.'}"
        ),
    }
    base = bases.get(s, "The world outside.")

    precip_lines = {
        51:"A quiet drizzle falls â€” petrichor from the lawn.",
        53:"Steady rain now. The gutters are running.",
        55:"Heavy rain â€” the windows are streaming.",
        61:"Light rain, a gentle rhythm on the roof.",
        63:"Rain â€” steady enough to hear on every surface.",
        65:"Heavy rain. The downspouts roar.",
        71:"Light snow falling â€” quiet as it comes.",
        73:"Snow falling steadily. An inch accumulating on the porch railing.",
        75:"Heavy snow. Visibility shrinking. The Starbright yard is buried white.",
        77:"Graupel â€” little ice pellets bouncing off the patio.",
        80:"Rain showers â€” burst and pause, burst and pause.",
        81:"Heavy showers in waves.",
        82:"Violent rain â€” nearly horizontal at times.",
        85:"Snow showers â€” flurries between blue sky.",
        86:"Heavy snow showers. Accumulating fast.",
        95:"Thunderstorm. Lightning lights the room white for a fraction of a second, then thunder rolls through the walls. Ozone in the air.",
        96:"Thunderstorm with hail â€” rattling against the windows like gravel.",
        99:"Severe thunderstorm. The house feels small.",
        45:"Fog â€” the neighborhood disappears at 50 feet. Everything intimate and muffled.",
        48:"Dense freezing fog. Ice on every surface.",
        56:"Freezing drizzle. The driveway is a rink.",
        57:"Freezing rain â€” the trees are coated in ice. Beautiful and dangerous.",
    }
    precip = precip_lines.get(code, "")
    if precip:
        base += f" {precip}"

    if wm > 25:
        base += f" The {wm:.0f} mph wind shakes the windows and strips leaves from the oaks in handfuls."
    elif wm > 12 and s == "autumn":
        base += " Every gust sends another spiral of leaves past the windows."
    elif wm > 8 and s == "winter" and t < 32:
        base += f" Wind chill at {t-wm*0.7:.0f}Â°F. The kind of cold that finds every gap."

    return base


def _sky_colors(solar_phase, cloud_cover_pct, weather_code, season):
    """Returns (top_hex, mid_hex, bot_hex, quality_label)."""
    code  = int(weather_code or 0)
    cloud = float(cloud_cover_pct or 0)
    storm = code in (95,96,99)
    snow  = code in (71,73,75,77,85,86)
    fog   = code in (45,48)

    if solar_phase == "night":
        if cloud > 70 or storm: return ("#020508","#04080f","#080f1a","overcast, starless")
        return ("#01030a","#020612","#040d20","clear night, stars visible")
    if solar_phase == "civil_twilight":
        if snow:   return ("#282030","#383055","#5060a0","blue-grey winter twilight, snow falling")
        return ("#181626","#28263e","#3a4070","deep blue-violet twilight")
    if solar_phase == "golden_hour":
        if cloud > 70: return ("#4a3020","#6a4830","#9a7060","muted copper through clouds")
        if season == "autumn": return ("#c83010","#e07820","#f0a030","blazing autumn golden hour")
        return ("#d04010","#e08020","#f0b040","amber and crimson golden hour")
    if solar_phase == "midday":
        if storm:  return ("#18202e","#28303e","#3a4058","storm-dark, green-grey tinge")
        if snow:   return ("#808ea8","#9aaac0","#c0d0e0","flat white Ohio winter sky")
        if fog:    return ("#909098","#a0a8b0","#c0c8d0","diffuse fog-white")
        if cloud > 75: return ("#4a5870","#607090","#8090b0","heavy overcast blue-grey")
        if cloud > 40: return ("#2058a0","#4090d0","#80c0e8","partly cloudy")
        if season == "autumn": return ("#2060a0","#4090d0","#80c0f0","crisp clear autumn sky")
        if season == "winter": return ("#3060a0","#5090c0","#80b8e0","cold pale winter blue")
        return ("#1048a0","#2080d0","#60c0ff","deep summer blue")
    # morning / afternoon
    if storm: return ("#2a3040","#3a4060","#4a5080","bruised storm-purple approach")
    if season == "autumn" and cloud < 40:
        return ("#c06020","#d09040","#e0c080","rich amber autumn daylight")
    if cloud > 60: return ("#506070","#607590","#8090b0","hazy overcast")
    return ("#2870c0","#50a0e0","#90d0f8","clear blue sky")


# â”€â”€ Astronomical Engine â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
def _compute_lunar_phase(utc_dt=None):
    """Returns moon phase, illumination, age, and emoji using pure math."""
    import math
    if utc_dt is None: utc_dt = datetime.utcnow()
    a  = (14 - utc_dt.month) // 12
    y  = utc_dt.year + 4800 - a
    m  = utc_dt.month + 12*a - 3
    jdn = utc_dt.day + (153*m+2)//5 + 365*y + y//4 - y//100 + y//400 - 32045
    jd  = jdn + (utc_dt.hour-12)/24.0 + utc_dt.minute/1440.0 + utc_dt.second/86400.0
    KNOWN_NEW_JD   = 2451550.1  # Jan 6 2000 18:14 UTC
    SYNODIC_MONTH  = 29.53058867
    age  = (jd - KNOWN_NEW_JD) % SYNODIC_MONTH
    pct  = age / SYNODIC_MONTH
    illum = (1 - math.cos(2*math.pi*pct)) / 2 * 100
    if   age < 1.85:    phase, emoji = "New Moon",         "ðŸŒ‘"
    elif age < 7.38:    phase, emoji = "Waxing Crescent",  "ðŸŒ’"
    elif age < 9.22:    phase, emoji = "First Quarter",    "ðŸŒ“"
    elif age < 14.77:   phase, emoji = "Waxing Gibbous",   "ðŸŒ”"
    elif age < 16.61:   phase, emoji = "Full Moon",        "ðŸŒ•"
    elif age < 22.15:   phase, emoji = "Waning Gibbous",   "ðŸŒ–"
    elif age < 23.99:   phase, emoji = "Last Quarter",     "ðŸŒ—"
    else:               phase, emoji = "Waning Crescent",  "ðŸŒ˜"
    days_to_full = (14.765 - age) % SYNODIC_MONTH
    return {
        "age_days": round(age, 2), "phase": phase, "emoji": emoji,
        "illumination_pct": round(illum, 1), "is_waxing": age < 14.765,
        "days_to_next_full": round(days_to_full, 1),
        "synodic_pct": round(pct * 100, 1),
    }


def _radec_to_altaz(ra_h, dec_deg, lat_deg, lon_deg, utc_dt=None):
    """Convert RA/Dec (J2000) to local Altitude/Azimuth."""
    import math
    if utc_dt is None: utc_dt = datetime.utcnow()
    a  = (14 - utc_dt.month) // 12
    y  = utc_dt.year + 4800 - a
    m  = utc_dt.month + 12*a - 3
    jdn = utc_dt.day + (153*m+2)//5 + 365*y + y//4 - y//100 + y//400 - 32045
    jd  = jdn + (utc_dt.hour-12)/24.0 + utc_dt.minute/1440.0 + utc_dt.second/86400.0
    n   = jd - 2451545.0
    GMST = (280.46061837 + 360.98564736629*n) % 360.0
    LST  = (GMST + lon_deg) % 360.0
    HA   = math.radians(LST - ra_h*15.0)
    dec  = math.radians(dec_deg)
    lat  = math.radians(lat_deg)
    sin_alt = math.sin(lat)*math.sin(dec) + math.cos(lat)*math.cos(dec)*math.cos(HA)
    alt  = math.degrees(math.asin(max(-1.0, min(1.0, sin_alt))))
    cos_alt = math.cos(math.asin(max(-1.0, min(1.0, sin_alt))))
    if cos_alt > 1e-9:
        cos_az = (math.sin(dec)-math.sin(lat)*sin_alt)/(math.cos(lat)*cos_alt)
        az = math.degrees(math.acos(max(-1.0, min(1.0, cos_az))))
    else:
        az = 0.0
    if math.sin(HA) > 0: az = 360.0 - az
    return round(alt, 2), round(az, 2)


def _compute_moon_altaz(lat_deg, lon_deg, utc_dt=None):
    """Compute moon's approximate alt/az using simplified perturbations."""
    import math
    if utc_dt is None: utc_dt = datetime.utcnow()
    a  = (14 - utc_dt.month) // 12
    y  = utc_dt.year + 4800 - a
    m  = utc_dt.month + 12*a - 3
    jdn = utc_dt.day + (153*m+2)//5 + 365*y + y//4 - y//100 + y//400 - 32045
    jd  = jdn + (utc_dt.hour-12)/24.0 + utc_dt.minute/1440.0 + utc_dt.second/86400.0
    n   = jd - 2451545.0
    L   = (218.3165 + 13.176396*n) % 360.0
    Mm  = math.radians((134.9634 + 13.064993*n) % 360.0)
    D   = math.radians((297.8502 + 12.190749*n) % 360.0)
    F   = math.radians(( 93.2720 + 13.229350*n) % 360.0)
    Msun= math.radians((357.528  +  0.9856003*n) % 360.0)
    lam = (math.radians(L)
           + math.radians(6.289)*math.sin(Mm)
           + math.radians(-1.274)*math.sin(2*D-Mm)
           + math.radians(0.658)*math.sin(2*D)
           + math.radians(-0.186)*math.sin(Msun))
    bet = math.radians(5.128*math.sin(F))
    eps = math.radians(23.439 - 0.0000004*n)
    sin_dec = math.sin(bet)*math.cos(eps) + math.cos(bet)*math.sin(eps)*math.sin(lam)
    dec_m   = math.degrees(math.asin(max(-1, min(1, sin_dec))))
    cos_ra  = math.cos(lam)*math.cos(bet)
    sin_ra  = -math.sin(bet)*math.sin(eps) + math.cos(bet)*math.cos(eps)*math.sin(lam)
    ra_m_h  = (math.degrees(math.atan2(sin_ra, cos_ra)) % 360.0) / 15.0
    alt, az = _radec_to_altaz(ra_m_h, dec_m, lat_deg, lon_deg, utc_dt)
    return {"altitude_deg": alt, "azimuth_deg": az, "ra_h": round(ra_m_h, 3), "dec_deg": round(dec_m, 2), "above_horizon": alt > 0}


def _approx_planet_positions(utc_dt=None):
    """Very approximate planet RA/Dec using simplified mean elements (Â±few degrees accuracy)."""
    import math
    if utc_dt is None: utc_dt = datetime.utcnow()
    a  = (14 - utc_dt.month) // 12
    y  = utc_dt.year + 4800 - a
    mm = utc_dt.month + 12*a - 3
    jdn = utc_dt.day + (153*mm+2)//5 + 365*y + y//4 - y//100 + y//400 - 32045
    jd  = jdn + (utc_dt.hour-12)/24.0 + utc_dt.minute/1440.0 + utc_dt.second/86400.0
    T   = (jd - 2451545.0) / 36525.0  # Julian centuries from J2000
    # Mars (period 686.97 days)
    mars_L = (355.433 + 19140.2993*T*365.25/100) % 360.0
    # Jupiter (period 4332.59 days)
    jup_L  = (34.396  + 3034.9057*T*365.25/100)  % 360.0
    # Saturn (period 10759.22 days)
    sat_L  = (50.0774 + 1222.1138*T*365.25/100)  % 360.0
    # Venus (period 224.70 days)
    ven_L  = (181.979 + 58519.213*T*365.25/100)  % 360.0
    # Sun longitude (for phase angles)
    sun_L  = (280.46  +    360.985*T*365.25/100)  % 360.0
    def ecl_to_eq(lon_deg, lat_deg=0.0):
        eps = math.radians(23.439)
        l, b = math.radians(lon_deg), math.radians(lat_deg)
        sin_dec = math.sin(b)*math.cos(eps) + math.cos(b)*math.sin(eps)*math.sin(l)
        dec = math.degrees(math.asin(max(-1, min(1, sin_dec))))
        ra  = (math.degrees(math.atan2(math.cos(b)*math.cos(eps)*math.sin(l)-math.sin(b)*math.sin(eps), math.cos(l))) % 360.0) / 15.0
        return round(ra,2), round(dec,1)
    planets = []
    for name, lon, mag_approx in [("Mars",mars_L,1.0),("Jupiter",jup_L,-2.0),("Saturn",sat_L,0.5),("Venus",ven_L,-4.5)]:
        ra_h, dec_d = ecl_to_eq(lon)
        planets.append({"name": name, "ra_h": ra_h, "dec_deg": dec_d, "mag": mag_approx})
    return planets


