def _get_sky_state(lat=41.546, lon=-83.596, utc_dt=None):
    """Compute complete sky state: moon, planets, visible named stars."""
    if utc_dt is None: utc_dt = datetime.utcnow()
    moon_phase  = _compute_lunar_phase(utc_dt)
    moon_altaz  = _compute_moon_altaz(lat, lon, utc_dt)
    planets     = _approx_planet_positions(utc_dt)
    # Compute alt/az for each planet
    for p in planets:
        alt, az = _radec_to_altaz(p["ra_h"], p["dec_deg"], lat, lon, utc_dt)
        p["altitude_deg"] = alt; p["azimuth_deg"] = az; p["above_horizon"] = alt > 0
    # Compute alt/az for bright stars (send to frontend for plotting)
    stars = []
    for row in _BRIGHT_STARS:
        name, ra_h, dec_d, mag, spec, desc = row
        alt, az = _radec_to_altaz(ra_h, dec_d, lat, lon, utc_dt)
        stars.append({"name":name,"ra_h":ra_h,"dec":dec_d,"mag":mag,"spec":spec,
                       "alt":alt,"az":az,"visible":alt>0,"desc":desc})
    # Compute visibility for DSOs
    dsos = []
    for obj in _MESSIER_OBJECTS:
        alt, az = _radec_to_altaz(obj["ra_h"], obj["dec"], lat, lon, utc_dt)
        dsos.append({**obj,"alt":alt,"az":az,"visible":alt>0})
    # GMST for client-side rotation
    a  = (14 - utc_dt.month)//12; yr = utc_dt.year+4800-a; mo = utc_dt.month+12*a-3
    jdn = utc_dt.day+(153*mo+2)//5+365*yr+yr//4-yr//100+yr//400-32045
    jd  = jdn+(utc_dt.hour-12)/24.0+utc_dt.minute/1440.0+utc_dt.second/86400.0
    n   = jd - 2451545.0
    lst = (280.46061837 + 360.98564736629*n + lon) % 360.0
    return {
        "moon": {**moon_phase, **moon_altaz},
        "planets": planets,
        "stars": stars,
        "dsos": dsos,
        "constellations": _CONSTELLATION_LINES,
        "lst_deg": round(lst, 2),
        "lat": lat, "lon": lon,
        "utc_iso": utc_dt.isoformat(),
    }

