def _resolve_mode_key_from_entries(value, entries, fallback):
    candidate = _capability_slug(value, fallback)
    available = {str(item.get("key", "")).strip().lower() for item in list(entries or [])}
    return candidate if candidate in available else fallback

def _sanitize_visual_spectrum_mode(value):
    mode = str(value or "visible-light").strip().lower()
    return mode if mode in VISUAL_SPECTRUM_MODES else "visible-light"

def _sanitize_visual_spectrum_modes(values):
    if isinstance(values, str):
        values = [segment.strip() for segment in values.split(",")]
    normalized = []
    for raw in list(values or []):
        key = _capability_slug(raw, "")
        if not key:
            continue
        if key not in VISUAL_SPECTRUM_MODES:
            continue
        if key in normalized:
            continue
        normalized.append(key)
    if not normalized:
        normalized = ["visible-light"]
    return normalized

def _sanitize_audio_spectrum_mode(value):
    mode = str(value or "audible-band").strip().lower()
    return mode if mode in AUDIO_SPECTRUM_MODES else "audible-band"

def _resolve_vision_mode_entry(value):
    entries = list((app_state.get("vision_registry") or {}).get("documented_modes", []) or [])
    key = _resolve_mode_key_from_entries(value, entries, "visible-light")
    for item in entries:
        if str(item.get("key", "")).strip().lower() == key:
            return item
    return _build_registry_entry(key, VISUAL_SPECTRUM_MODES["visible-light"]["label"], VISUAL_SPECTRUM_MODES["visible-light"]["note"], VISUAL_SPECTRUM_MODES["visible-light"]["prompt"], built_in=True, origin="core")

def _resolve_vision_mode_entries(values):
    modes = _sanitize_visual_spectrum_modes(values)
    return [_resolve_vision_mode_entry(mode) for mode in modes]

def _compose_visual_mode_bundle(values, intensities=None):
    entries = _resolve_vision_mode_entries(values)
    intensities_map = dict(intensities or {})
    labels, notes, prompts, keys = [], [], [], []
    for item in entries:
        key = str(item.get("key", "visible-light")).strip().lower() or "visible-light"
        intensity = max(0.0, min(1.0, float(intensities_map.get(key, 1.0))))
        label = str(item.get("label", "")).strip()
        note = str(item.get("note", "")).strip()
        raw_prompt = str(item.get("prompt", "")).strip()
        if not key:
            continue
        keys.append(key)
        if label:
            labels.append(label)
        if note and intensity >= 0.05:
            notes.append(note)
        if raw_prompt and intensity >= 0.05:
            if intensity >= 0.75:
                prompts.append(raw_prompt)
            elif intensity >= 0.4:
                prompts.append(f"Also lightly: {raw_prompt}")
            elif intensity >= 0.15:
                prompts.append(f"As a subtle trace: {raw_prompt}")
            else:
                prompts.append(f"As a barely perceptible hint: {raw_prompt}")
    if not keys:
        keys = ["visible-light"]
    wavelength_map = {
        "visible-light": "Visible band 380-700nm",
        "near-infrared": "Near infrared 700-1400nm",
        "ultraviolet": "Ultraviolet 100-400nm (inferred band cues)",
        "full-spectrum": "Composite visible+UV+IR inference map",
        "oscilloscope": "Temporal waveform intensity trace",
        "dicyanin": "Speculative boundary-glow lens interpretation"
    }
    # Also draw from SPECTRUM_WAVELENGTH_MAP for oscillation bands
    for k in keys:
        if k not in wavelength_map and k in SPECTRUM_WAVELENGTH_MAP:
            band = SPECTRUM_WAVELENGTH_MAP[k]
            wl = band.get("wavelength_nm", 0)
            wl_str = f"{wl:.3g} nm" if wl and wl < 1e6 else f"{wl:.3e} nm"
            wavelength_map[k] = f"{band.get('label', k)} {wl_str}"
    wavelength_profile = " | ".join(
        wavelength_map.get(k, k.replace("-", " ").title())
        for k in keys
    )[:800]
    # Build parallax depth map for all active keys
    # Visible-light modes use VISUAL_SPECTRUM_MODES depth; EM spectrum bands use frequency-based depth
    parallax_depths = {}
    for k in keys:
        if k in VISUAL_SPECTRUM_MODES:
            parallax_depths[k] = float(VISUAL_SPECTRUM_MODES[k].get("parallax_depth", 0.0))
        elif k in SPECTRUM_WAVELENGTH_MAP:
            # Map frequency to depth: lower freq (radio) = deepest, gamma = shallowest surface
            hz = SPECTRUM_WAVELENGTH_MAP[k].get("hz", 5e14)
            # Normalize across ~20 orders of magnitude: 1e3 Hz â†’ depth 1.0, 3e20 Hz â†’ depth 0.0
            import math
            log_hz = math.log10(max(hz, 1e3))
            # Scale: log10(1e3)=3 â†’ 1.0, log10(3e20)â‰ˆ20.5 â†’ 0.0
            parallax_depths[k] = round(max(0.0, min(1.0, 1.0 - (log_hz - 3.0) / 17.5)), 3)
        else:
            parallax_depths[k] = 0.3
    intensities_summary = {k: round(float(intensities_map.get(k, 1.0)), 3) for k in keys}
    return {
        "keys": keys,
        "labels": labels,
        "note": " ".join(notes).strip()[:900] if notes else VISUAL_SPECTRUM_MODES["visible-light"]["note"],
        "prompt": " ".join(prompts).strip()[:1800] if prompts else VISUAL_SPECTRUM_MODES["visible-light"]["prompt"],
        "wavelength_profile": wavelength_profile,
        "intensities": intensities_summary,
        "parallax_depths": parallax_depths
    }

def _resolve_audio_mode_entry(value):
    entries = list((app_state.get("audio_registry") or {}).get("documented_modes", []) or [])
    key = _resolve_mode_key_from_entries(value, entries, "audible-band")
    for item in entries:
        if str(item.get("key", "")).strip().lower() == key:
            return item
    return _build_registry_entry(key, AUDIO_SPECTRUM_MODES["audible-band"]["label"], AUDIO_SPECTRUM_MODES["audible-band"]["note"], AUDIO_SPECTRUM_MODES["audible-band"]["prompt"], built_in=True, origin="core")

