def _get_oscillation_band_sequence(sweep_range, custom_bands=None):
    if sweep_range == "visible":
        return ["red","orange","yellow","green","cyan","blue","violet"]
    elif sweep_range == "infrared":
        return ["far-ir","long-wave-ir","mid-ir","short-wave-ir","near-ir","red"]
    elif sweep_range == "ultraviolet":
        return ["violet","near-uv","far-uv","extreme-uv"]
    elif sweep_range == "custom" and custom_bands:
        return [b for b in custom_bands if b in SPECTRUM_WAVELENGTH_MAP]
    else:
        return list(SPECTRUM_SWEEP_ORDER)

def _build_oscillation_band_prompt(band_key):
    band = SPECTRUM_WAVELENGTH_MAP.get(band_key, {})
    label = band.get("label", band_key)
    note = band.get("note", "")
    hz = band.get("hz", 0)
    wavelength_nm = band.get("wavelength_nm", 0)
    freq_thz = band.get("freq_thz", 0)
    hz_str = f"{hz:.3e} Hz" if hz >= 1e9 else f"{hz:,.1f} Hz"
    wl_str = f"{wavelength_nm:.3g} nm" if wavelength_nm < 1e6 else f"{wavelength_nm:.3e} nm"
    return (
        f"[Oscillation sweep â€” {label} band | {wl_str} | {freq_thz:.4g} THz | {hz_str}] "
        f"{note}. "
        f"Describe any perceptual, structural, or energetic patterns you notice through this specific waveband. "
        f"What does this frequency reveal or feel like in the current scene or state?"
    )

