def _load_llm_orchestration_from_profile():
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    loaded = _safe_json_loads(life.get("llm_orchestration_json", "{}"), {})
    if not isinstance(loaded, dict):
        return
    mode = str(loaded.get("mode", "auto")).strip().lower() or "auto"
    if mode not in {"single", "auto", "round_robin", "combo"}:
        mode = "auto"
    combo_mode = str(loaded.get("combo_mode", "dual_synthesize")).strip().lower() or "dual_synthesize"
    if combo_mode not in {"off", "dual_synthesize"}:
        combo_mode = "dual_synthesize"
    providers = [str(p).strip().lower() for p in list(loaded.get("enabled_providers", []) or []) if str(p).strip()]
    app_state["llm_orchestration"] = {"mode": mode, "combo_mode": combo_mode, "enabled_providers": providers}
    try:
        personality_engine.llm_orchestration = dict(app_state["llm_orchestration"])
    except Exception:
        pass

def _sanitize_compute_boost_settings(raw):
    defaults = _default_compute_boost_state()
    source = raw if isinstance(raw, dict) else {}
    mode = str(source.get("orchestration_mode", defaults["orchestration_mode"])).strip().lower() or defaults["orchestration_mode"]
    if mode not in {"single", "auto", "round_robin", "combo"}:
        mode = defaults["orchestration_mode"]
    combo = str(source.get("combo_mode", defaults["combo_mode"])).strip().lower() or defaults["combo_mode"]
    if combo not in {"off", "dual_synthesize"}:
        combo = defaults["combo_mode"]
    quality = str(source.get("target_quality", defaults["target_quality"])).strip().lower() or defaults["target_quality"]
    if quality not in {"high", "ultra", "cinematic"}:
        quality = defaults["target_quality"]
    return {
        "enabled": source.get("enabled", defaults["enabled"]) is not False,
        "cloud_first": source.get("cloud_first", defaults["cloud_first"]) is not False,
        "max_context": source.get("max_context", defaults["max_context"]) is not False,
        "web_research": source.get("web_research", defaults["web_research"]) is not False,
        "orchestration_mode": mode,
        "combo_mode": combo,
        "target_quality": quality,
        "target_fps": max(60, min(240, int(source.get("target_fps", defaults["target_fps"]) or defaults["target_fps"]))),
        "physics_substeps": max(2, min(16, int(source.get("physics_substeps", defaults["physics_substeps"]) or defaults["physics_substeps"]))),
        "autonomy_tick_ms": max(5000, min(90000, int(source.get("autonomy_tick_ms", defaults["autonomy_tick_ms"]) or defaults["autonomy_tick_ms"]))),
        "last_applied_at": source.get("last_applied_at"),
        "last_provider": str(source.get("last_provider", defaults["last_provider"])).strip()
    }

def _persist_compute_boost_to_profile():
    payload = _sanitize_compute_boost_settings(app_state.get("compute_boost", {}))
    memory.add_profile_item("life_context", json.dumps(payload), key="compute_boost_json")

def _load_compute_boost_from_profile():
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    loaded = _safe_json_loads(life.get("compute_boost_json", "{}"), {})
    merged = _sanitize_compute_boost_settings({**_default_compute_boost_state(), **(loaded if isinstance(loaded, dict) else {})})
    app_state["compute_boost"] = merged

def _apply_cloud_compute_boost(force=False):
    settings = _sanitize_compute_boost_settings(app_state.get("compute_boost", {}))
    if not settings.get("enabled", True):
        app_state["compute_boost"] = settings
        return {"applied": False, "reason": "disabled", "provider": getattr(personality_engine, "llm_provider", "none")}
    if not force:
        try:
            last = str(settings.get("last_applied_at") or "").strip()
            if last:
                delta = datetime.utcnow() - datetime.fromisoformat(last)
                if delta.total_seconds() < 180:
                    return {"applied": True, "reason": "recent", "provider": str(getattr(personality_engine, "llm_provider", "none") or "none")}
        except Exception:
            pass

    now_iso = datetime.utcnow().isoformat()
    clients = personality_engine._refresh_llm_clients()
    connected = list(clients.keys())
    remote_priority = ["openrouter", "anthropic", "openai", "gemini", "cohere", "m365copilot"]
    local_priority = ["ollama", "sillytavern", "oobabooga"]
    ordered = remote_priority + local_priority if settings.get("cloud_first", True) else local_priority + remote_priority
    selected = next((p for p in ordered if p in clients), None) or next(iter(clients.keys()), None)

    if selected:
        personality_engine.llm_provider = selected
        personality_engine.llm_client = clients[selected]
        personality_engine.use_llm = True

    if settings.get("max_context", True):
        personality_engine.cot_enabled = True
        personality_engine.recall_personal_chars = max(5200, int(getattr(personality_engine, "recall_personal_chars", 3200) or 3200))
        personality_engine.recall_global_chars = max(26000, int(getattr(personality_engine, "recall_global_chars", 12000) or 12000))
        personality_engine.recall_session_chars = max(12000, int(getattr(personality_engine, "recall_session_chars", 6000) or 6000))
        personality_engine.recall_rag_chars = max(18000, int(getattr(personality_engine, "recall_rag_chars", 9000) or 9000))
        personality_engine.recall_rag_limit = max(96, int(getattr(personality_engine, "recall_rag_limit", 36) or 36))

    if connected:
        app_state["llm_orchestration"] = {
            "mode": settings.get("orchestration_mode", "combo"),
            "combo_mode": settings.get("combo_mode", "dual_synthesize"),
            "enabled_providers": connected
        }
        personality_engine.llm_orchestration = dict(app_state["llm_orchestration"])

    wc = dict(app_state.get("world_continuity", {}) or {})
    wc["display_resolution"] = "8k-supersampled" if settings.get("target_quality") in {"ultra", "cinematic"} else "4k"
    wc["perception_cadence_hz"] = max(int(wc.get("perception_cadence_hz", 244) or 244), int(settings.get("target_fps", 120)))
    wc["world_patience"] = 100
    app_state["world_continuity"] = wc

    settings["last_applied_at"] = now_iso
    settings["last_provider"] = selected or ""
    app_state["compute_boost"] = settings
    _persist_llm_orchestration_to_profile()
    _persist_compute_boost_to_profile()
    return {"applied": bool(selected), "provider": selected or "none", "connected_providers": connected}

def _load_custom_models_from_profile():
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    saved = _safe_json_loads(life.get("custom_models_json", "{}"), {})
    if isinstance(saved, dict):
        clean = {}
        for alias, entry in saved.items():
            alias = str(alias).strip().lower()
            if alias and isinstance(entry, dict) and str(entry.get("model_id", "")).strip():
                clean[alias] = {
                    "model_id": str(entry.get("model_id", "")).strip(),
                    "provider_hint": str(entry.get("provider_hint", "auto")).strip().lower() or "auto",
                    "description": str(entry.get("description", "")).strip()[:120]
                }
        app_state["custom_models"] = clean
        # Push into personality_engine so _normalize_model_alias picks them up
        try:
            personality_engine.custom_model_aliases = clean
        except Exception:
            pass

def _persist_perception_cadence_to_profile():
    """Persist perception settings, lab state, and new system summaries so they survive server restarts."""
    wc = dict(app_state.get("world_continuity", {}) or {})
    memory.add_profile_item("life_context", str(wc.get("display_resolution", "4k")).strip() or "4k", key="perception_display_resolution")
    memory.add_profile_item("life_context", str(int(wc.get("perception_cadence_hz", 244) or 244)), key="perception_cadence_hz")
    memory.add_profile_item("life_context", str(int(wc.get("world_patience", 100) or 100)), key="world_patience")
    memory.add_profile_item("life_context", "true" if wc.get("direct_link_enabled", True) else "false", key="direct_link_enabled")
    lab = dict(app_state.get("science_lab", {}) or {})
    memory.add_profile_item("life_context", str(lab.get("focus_area", "cymatics")).strip() or "cymatics", key="lab_focus_area")
    memory.add_profile_item("life_context", str(int(lab.get("total_experiments", 0) or 0)), key="lab_total_experiments")
    memory.add_profile_item("life_context", str(int(lab.get("total_discoveries", 0) or 0)), key="lab_total_discoveries")
    memory.add_profile_item("life_context", str(lab.get("latest_discovery", "") or ""), key="lab_latest_discovery")
    # CRISPR
    crispr = dict(app_state.get("crispr_lab") or {})
    memory.add_profile_item("life_context", str(crispr.get("active_editor", "Cas9-SpRY")), key="crispr_active_editor")
    memory.add_profile_item("life_context", str(int(crispr.get("total_experiments", 0) or 0)), key="crispr_total_experiments")
    memory.add_profile_item("life_context", str(int(crispr.get("total_successes", 0) or 0)), key="crispr_total_successes")
    # Lattice quantum
    lqt = dict(app_state.get("lattice_qthermo") or {})
    memory.add_profile_item("life_context", str(lqt.get("phase", "superfluid")), key="lattice_phase")
    memory.add_profile_item("life_context", str(float(lqt.get("temperature_mK", 12.0) or 12.0)), key="lattice_temp_mK")
    # Health
    hs = dict(app_state.get("health_system") or {})
    memory.add_profile_item("life_context", str(float(hs.get("overall_score", 88.5) or 88.5)), key="health_score")
    memory.add_profile_item("life_context", str(hs.get("trend", "stable")), key="health_trend")

def _load_perception_cadence_from_profile():
    """Restore perception settings, lab state, CRISPR/lattice/health from profile on startup."""
    profile = _safe_get_profile()
    life = dict(profile.get("life_context", {}) or {})
    wc = dict(app_state.get("world_continuity", {}) or {})
    res = str(life.get("perception_display_resolution", wc.get("display_resolution", "4k"))).strip().lower() or "4k"
    try:
        hz = max(1, min(360, int(str(life.get("perception_cadence_hz", wc.get("perception_cadence_hz", 244))).strip())))
    except Exception:
        hz = 244
    try:
        patience = max(0, min(100, int(str(life.get("world_patience", wc.get("world_patience", 100))).strip())))
    except Exception:
        patience = 100
    direct_link = str(life.get("direct_link_enabled", "true")).strip().lower() != "false"
    wc["display_resolution"] = res
    wc["perception_cadence_hz"] = hz
    wc["world_patience"] = patience
    wc["direct_link_enabled"] = direct_link
    app_state["world_continuity"] = wc
    lab = dict(app_state.get("science_lab", {}) or {})
    lab["focus_area"] = str(life.get("lab_focus_area", lab.get("focus_area", "cymatics"))).strip() or "cymatics"
    try:
        lab["total_experiments"] = max(0, int(str(life.get("lab_total_experiments", lab.get("total_experiments", 0))).strip()))
    except Exception:
        pass
    try:
        lab["total_discoveries"] = max(0, int(str(life.get("lab_total_discoveries", lab.get("total_discoveries", 0))).strip()))
    except Exception:
        pass
    lab["latest_discovery"] = str(life.get("lab_latest_discovery", lab.get("latest_discovery", ""))).strip()
    app_state["science_lab"] = lab
    # Restore CRISPR summary counters
    crispr = dict(app_state.get("crispr_lab") or _default_crispr_state())
    if life.get("crispr_active_editor"):
        crispr["active_editor"] = str(life["crispr_active_editor"])
    try:
        crispr["total_experiments"] = max(0, int(str(life.get("crispr_total_experiments", crispr.get("total_experiments", 0))).strip()))
    except Exception:
        pass
    try:
        crispr["total_successes"] = max(0, int(str(life.get("crispr_total_successes", crispr.get("total_successes", 0))).strip()))
    except Exception:
        pass
    app_state["crispr_lab"] = crispr
    # Restore lattice phase hint
    lqt = dict(app_state.get("lattice_qthermo") or _default_lattice_qthermo_state())
    if life.get("lattice_phase"):
        lqt["phase"] = str(life["lattice_phase"])
    try:
        lqt["temperature_mK"] = float(str(life.get("lattice_temp_mK", lqt.get("temperature_mK", 12.0))).strip())
    except Exception:
        pass
    app_state["lattice_qthermo"] = lqt
    # Restore health score hint
    hs = dict(app_state.get("health_system") or _default_health_system_state())
    try:
        hs["overall_score"] = float(str(life.get("health_score", hs.get("overall_score", 88.5))).strip())
    except Exception:
        pass
    if life.get("health_trend"):
        hs["trend"] = str(life["health_trend"])
    app_state["health_system"] = hs

def _update_cymatics_mastery_from_text(text, base_increment=0):
    sound = dict(app_state.get("sound_creation", {}) or {})
    lower = str(text or "").lower()
    increment = int(base_increment or 0)
    if re.search(r"\b(3d bubble cymatics|three dimensional bubble cymatics|cymatic bubble)\b", lower):
        increment += 42
    elif re.search(r"\b(cymatic|standing wave|nodal|resonant shell|acoustic bubble|bubble resonance)\b", lower):
        increment += 18
    if increment <= 0:
        return sound
    sound["cymatics_mastery"] = max(0, min(100, int(sound.get("cymatics_mastery", 0) or 0) + increment))
    if sound["cymatics_mastery"] >= 100:
        sound["cymatics_unlocked"] = True
    app_state["sound_creation"] = sound
    _persist_sound_creation_to_profile()
    return sound

def _sanitize_sync_settings(raw):
    merged = dict(SYNC_SETTINGS_DEFAULTS)
    incoming = dict(raw or {})
    merged["enabled"] = _bool_from_text(incoming.get("enabled"), default=False)
    merged["provider"] = "github_gist"
    merged["gist_id"] = str(incoming.get("gist_id", "")).strip()
    merged["device_id"] = str(incoming.get("device_id", "aurion-device")).strip() or "aurion-device"
    try:
        merged["auto_interval_seconds"] = max(0, min(3600, int(incoming.get("auto_interval_seconds", 0))))
    except Exception:
        merged["auto_interval_seconds"] = 0
    merged["last_push_at"] = incoming.get("last_push_at")
    merged["last_pull_at"] = incoming.get("last_pull_at")
    merged["last_remote_pushed_at"] = incoming.get("last_remote_pushed_at")
    merged["last_conflict"] = str(incoming.get("last_conflict", "") or "").strip()[:160]
    merged["last_sync_status"] = str(incoming.get("last_sync_status", "idle"))
    return merged

