def _resolve_sync_token(request_token=None):
    token = str(request_token or "").strip()
    if token:
        return token
    runtime_token = str(app_state.get("sync_runtime_token", "") or "").strip()
    if runtime_token:
        return runtime_token
    return str(os.getenv("AURION_SYNC_GITHUB_TOKEN", "")).strip()

def _github_sync_headers(token):
    return {
        "Authorization": f"Bearer {token}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28"
    }

_sync_lock = threading.Lock()

def _sync_token_available():
    token = _resolve_sync_token()
    return bool(str(token or "").strip())

def _sync_is_ready(settings):
    normalized = _sanitize_sync_settings(settings)
    return bool(
        normalized.get("enabled")
        and str(normalized.get("gist_id", "")).strip()
        and _sync_token_available()
    )

def _effective_sync_interval_seconds(settings):
    normalized = _sanitize_sync_settings(settings)
    raw = int(normalized.get("auto_interval_seconds", 0) or 0)
    # If interval is 0, still sync frequently for continuity.
    return 30 if raw <= 0 else max(10, min(3600, raw))

def _latest_sync_marker(settings):
    pull_at = _safe_parse_iso(settings.get("last_pull_at"))
    push_at = _safe_parse_iso(settings.get("last_push_at"))
    if pull_at and push_at:
        return max(pull_at, push_at)
    return pull_at or push_at

def _fetch_sync_payload_from_gist(gist_id, token):
    url = f"https://api.github.com/gists/{gist_id}"
    response = requests.get(url, headers=_github_sync_headers(token), timeout=20)
    if response.status_code >= 400:
        raise RuntimeError(f"GitHub GET failed: HTTP {response.status_code}")
    data = response.json()
    files = data.get("files", {}) or {}
    sync_file = files.get("aurion_sync.json")
    if not sync_file:
        raise RuntimeError("aurion_sync.json not found in gist")
    content = sync_file.get("content")
    if content:
        return json.loads(content)
    raw_url = sync_file.get("raw_url")
    if not raw_url:
        raise RuntimeError("Sync file has no content or raw_url")
    raw_resp = requests.get(raw_url, timeout=20)
    raw_resp.raise_for_status()
    return raw_resp.json()

def _push_sync_payload_to_gist(gist_id, token, payload):
    url = f"https://api.github.com/gists/{gist_id}"
    body = {
        "files": {
            "aurion_sync.json": {
                "content": json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
            }
        }
    }
    response = requests.patch(url, headers=_github_sync_headers(token), json=body, timeout=25)
    if response.status_code >= 400:
        raise RuntimeError(f"GitHub PATCH failed: HTTP {response.status_code}")

def _sync_now(direction="both", reason="manual"):
    settings = _sanitize_sync_settings(app_state.get("sync_settings", {}))
    gist_id = str(settings.get("gist_id", "")).strip()
    token = _resolve_sync_token()
    if not gist_id:
        settings["last_sync_status"] = "sync_not_configured:gist_missing"
        app_state["sync_settings"] = settings
        _persist_sync_settings_to_profile(settings)
        return {"success": False, "error": "Missing gist_id"}
    if not token:
        settings["last_sync_status"] = "sync_not_configured:token_missing"
        app_state["sync_settings"] = settings
        _persist_sync_settings_to_profile(settings)
        return {"success": False, "error": "Missing GitHub token"}

    with _sync_lock:
        pulled_stats = {}
        if direction in {"both", "pull"}:
            payload = _fetch_sync_payload_from_gist(gist_id, token)
            remote_source = dict(payload.get("source", {}) or {})
            remote_pushed_at_text = str(remote_source.get("pushed_at", "")).strip() or None
            remote_pushed_at = _safe_parse_iso(remote_pushed_at_text)
            local_push_at = _safe_parse_iso(settings.get("last_push_at"))
            auto_reason = str(reason or "").strip().lower() in {"startup", "status_poll", "message", "auto"}
            should_skip_pull = (
                direction == "both"
                and auto_reason
                and remote_pushed_at is not None
                and local_push_at is not None
                and remote_pushed_at < local_push_at
            )
            if should_skip_pull:
                pulled_stats = {"skipped_pull": True, "skip_reason": "remote_older_than_local"}
                settings["last_conflict"] = "remote_older_than_local"
            else:
                pulled_stats = memory.import_sync_snapshot(payload)
                settings["last_pull_at"] = datetime.utcnow().isoformat()
                settings["last_conflict"] = ""
            settings["last_remote_pushed_at"] = remote_pushed_at_text
        if direction in {"both", "push"}:
            payload = memory.export_sync_snapshot()
            payload["source"] = {
                "device_id": str(settings.get("device_id", "aurion-device")).strip() or "aurion-device",
                "pushed_at": datetime.utcnow().isoformat(),
                "reason": str(reason or "manual")
            }
            _push_sync_payload_to_gist(gist_id, token, payload)
            settings["last_push_at"] = datetime.utcnow().isoformat()
            settings["last_remote_pushed_at"] = settings["last_push_at"]

        settings["last_sync_status"] = f"{direction}_ok"
        app_state["sync_settings"] = settings
        _persist_sync_settings_to_profile(settings)
        return {"success": True, **pulled_stats}

def _auto_sync_if_due(reason="auto"):
    settings = _sanitize_sync_settings(app_state.get("sync_settings", {}))
    if not _sync_is_ready(settings):
        if settings.get("enabled"):
            if not str(settings.get("gist_id", "")).strip():
                settings["last_sync_status"] = "sync_not_configured:gist_missing"
            elif not _sync_token_available():
                settings["last_sync_status"] = "sync_not_configured:token_missing"
            app_state["sync_settings"] = settings
            _persist_sync_settings_to_profile(settings)
        return {"skipped": True, "reason": "not_ready"}

    interval = _effective_sync_interval_seconds(settings)
    marker = _latest_sync_marker(settings)
    if marker and (datetime.utcnow() - marker).total_seconds() < interval:
        return {"skipped": True, "reason": "interval_not_due"}
    try:
        return _sync_now(direction="both", reason=reason)
    except Exception as e:
        settings = _sanitize_sync_settings(app_state.get("sync_settings", {}))
        settings["last_sync_status"] = f"auto_sync_error:{e}"
        app_state["sync_settings"] = settings
        _persist_sync_settings_to_profile(settings)
        print(f"[Auto Sync Error] {e}")
        return {"success": False, "error": str(e)}

def _creative_workspace_root():
    path = Path(str(app_state.get("creative_workspace") or _resolve_creative_workspace_path()))
    path.mkdir(parents=True, exist_ok=True)
    return path

def _creative_workspace_dir(kind):
    mapped = {
        "writing": "writing",
        "image": "images",
        "images": "images",
        "video": "videos",
        "videos": "videos",
        "audio": "music",
        "song": "music",
        "songs": "music",
        "music": "music",
        "reference": "references",
        "references": "references"
    }
    name = mapped.get(str(kind or "").strip().lower(), "references")
    target = _creative_workspace_root() / name
    target.mkdir(parents=True, exist_ok=True)
    return target

def _save_creative_text(title, text, style="story"):
    stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
    slug = _slugify_filename(title, fallback=f"{style}-piece")
    filename = f"{stamp}-{slug}.txt"
    path = _creative_workspace_dir("writing") / filename
    header = (
        f"Title: {title}\n"
        f"Style: {style}\n"
        f"Generated at (UTC): {datetime.utcnow().isoformat()}\n"
        f"{'-' * 48}\n\n"
    )
    path.write_text(header + str(text or ""), encoding="utf-8")
    return str(path)

def _save_creative_reference(kind, title, payload):
    stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
    slug = _slugify_filename(title, fallback=str(kind or "asset"))
    filename = f"{stamp}-{slug}.json"
    path = _creative_workspace_dir(kind) / filename
    envelope = {
        "kind": str(kind or "reference"),
        "title": str(title or ""),
        "saved_at": datetime.utcnow().isoformat(),
        "payload": payload if isinstance(payload, dict) else {"value": str(payload or "")}
    }
    path.write_text(json.dumps(envelope, ensure_ascii=False, indent=2), encoding="utf-8")
    return str(path)

def _list_creative_assets(kind=None, limit=200):
    roots = [
        _creative_workspace_dir("writing"),
        _creative_workspace_dir("images"),
        _creative_workspace_dir("videos"),
        _creative_workspace_dir("music"),
        _creative_workspace_dir("references")
    ]
    if kind:
        roots = [_creative_workspace_dir(kind)]
    rows = []
    for root in roots:
        for item in root.glob("*"):
            if not item.is_file():
                continue
            try:
                stat = item.stat()
            except Exception:
                continue
            rows.append({
                "name": item.name,
                "path": str(item),
                "category": root.name,
                "bytes": int(stat.st_size),
                "modified_at": datetime.utcfromtimestamp(stat.st_mtime).isoformat() + "Z"
            })
    rows.sort(key=lambda r: r["modified_at"], reverse=True)
    return rows[:max(1, min(1000, int(limit)))]

def _guess_writing_style(text):
    content = str(text or "").strip()
    lower = content.lower()
    lines = [line.strip() for line in content.splitlines() if line.strip()]
    if len(lines) >= 6 and len(lines) > 0 and (sum(1 for line in lines if len(line.split()) <= 12) / len(lines)) >= 0.65:
        return "poem"
    if lower.startswith("dear ") or "sincerely" in lower:
        return "letter"
    if "verse" in lower or "chorus" in lower:
        return "lyrics"
    if any(token in lower for token in ("scene:", "interior", "exterior", "cut to")):
        return "scene"
    return "story"

def _pick_creative_title(user_text, response):
    base = str(user_text or "").strip()
    if not base:
        base = str(response or "").strip()
    clean = re.sub(r"\s+", " ", base).strip()
    if not clean:
        return "Aurion Creative Piece"
    return clean[:72]

def _should_autonomously_save_to_creative_folder(user_text, response, intent_type):
    cfg = app_state.get("creative_autonomy", {}) or {}
    if not cfg.get("enabled", True):
        return False
    response_text = str(response or "").strip()
    user_text_l = str(user_text or "").lower()
    trigger_words = (
        "write", "story", "poem", "lyrics", "creative", "novel", "scene",
        "script", "journal", "letter", "imagery", "worldbuilding", "character"
    )
    if any(word in user_text_l for word in trigger_words):
        return True
    if len(response_text) < max(40, int(cfg.get("min_response_chars", 220) or 220)):
        return False
    if intent_type == "CONVERSE" and ("\n" in response_text or len(response_text.split()) >= 140):
        return True
    return False

def _autonomous_creative_save(user_text, response, intent_type):
    if not _should_autonomously_save_to_creative_folder(user_text, response, intent_type):
        return None
    style = _guess_writing_style(response)
    title = _pick_creative_title(user_text, response)
    saved_path = _save_creative_text(title=title, text=response, style=style)
    memory.add_knowledge_batch(
        response,
        source="creative_autosave",
        metadata={
            "title": title,
            "style": style,
            "saved_path": saved_path,
            "intent_type": str(intent_type or "CONVERSE"),
            "timestamp": datetime.utcnow().isoformat()
        }
    )
    return {
        "saved_path": saved_path,
        "title": title,
        "style": style
    }

_CODE_EDITABLE_SUFFIXES = {".py", ".js", ".json", ".txt", ".md", ".css", ".html", ".yaml", ".yml"}

def _resolve_repo_scoped_path(path_text):
    raw = str(path_text or "").strip()
    if not raw:
        raise ValueError("Path is required")
    root = _repo_root_path()
    candidate = Path(raw)
    if not candidate.is_absolute():
        candidate = (root / raw).resolve()
    else:
        candidate = candidate.resolve()
    if candidate != root and root not in candidate.parents:
        raise ValueError("Path must stay inside repository root")
    relative = str(candidate.relative_to(root))
    return candidate, relative

def _read_text_file(path_obj, max_chars=None):
    text = path_obj.read_text(encoding="utf-8", errors="ignore")
    if max_chars is None:
        return text
    return text[:max(1, int(max_chars))]

def _write_text_file(path_obj, content):
    path_obj.parent.mkdir(parents=True, exist_ok=True)
    path_obj.write_text(str(content or ""), encoding="utf-8")

def _apply_repo_code_edit(path_text, content, mode="append", create_if_missing=True):
    target, relative = _resolve_repo_scoped_path(path_text)
    suffix = target.suffix.lower()
    if suffix not in _CODE_EDITABLE_SUFFIXES:
        raise ValueError(f"Unsupported file type: {suffix or '(none)'}")
    normalized_mode = str(mode or "append").strip().lower()
    if normalized_mode not in {"append", "replace"}:
        normalized_mode = "append"
    if not target.exists() and not create_if_missing:
        raise FileNotFoundError("Target file does not exist")
    if normalized_mode == "replace":
        _write_text_file(target, str(content or ""))
    else:
        target.parent.mkdir(parents=True, exist_ok=True)
        existing = ""
        if target.exists():
            existing = _read_text_file(target)
        addition = str(content or "")
        if existing and not existing.endswith("\n"):
            existing += "\n"
        _write_text_file(target, existing + addition)
    stat = target.stat()
    return {
        "path": str(target),
        "relative_path": relative,
        "bytes": int(stat.st_size),
        "updated_at": datetime.utcfromtimestamp(stat.st_mtime).isoformat() + "Z"
    }


def _default_github_integration_state():
    max_mb = max(5, min(200, int(str(os.getenv("AURION_GITHUB_MAX_DOWNLOAD_MB", "40")).strip() or "40")))
    return {
        "enabled": True,
        "allow_download": True,
        "allow_implement": True,
        "max_download_mb": max_mb,
        "downloads": {},
        "last_download_at": None,
        "last_implement_at": None,
        "last_error": None,
    }


def _resolve_github_integration_state():
    state = dict(_default_github_integration_state())
    state.update(dict(app_state.get("github_integration") or {}))
    try:
        state["max_download_mb"] = max(5, min(200, int(state.get("max_download_mb", 40) or 40)))
    except Exception:
        state["max_download_mb"] = 40
    downloads = dict(state.get("downloads") or {})
    items = []
    for key, meta in downloads.items():
        entry = dict(meta or {})
        created = str(entry.get("created_at", "") or "")
        items.append((created, str(key), entry))
    items.sort(key=lambda row: row[0], reverse=True)
    kept = {}
    for _, key, entry in items[:16]:
        kept[key] = entry
    state["downloads"] = kept
    app_state["github_integration"] = state
    return state


def _public_github_integration_state(state=None):
    st = dict(state or _resolve_github_integration_state())
    downloads = dict(st.get("downloads") or {})
    summaries = []
    items = sorted(downloads.items(), key=lambda kv: str((kv[1] or {}).get("created_at", "")), reverse=True)
    for download_id, meta in items[:8]:
        info = dict(meta or {})
        summaries.append({
            "download_id": str(download_id),
            "repo": str(info.get("repo", "") or ""),
            "ref": str(info.get("ref", "") or ""),
            "created_at": info.get("created_at"),
            "file_count": int(info.get("file_count", 0) or 0),
            "total_bytes": int(info.get("total_bytes", 0) or 0),
            "text_files_preview": list(info.get("text_files_preview", []) or [])[:12],
        })
    return {
        "enabled": bool(st.get("enabled", True)),
        "allow_download": bool(st.get("allow_download", True)),
        "allow_implement": bool(st.get("allow_implement", True)),
        "max_download_mb": int(st.get("max_download_mb", 40) or 40),
        "downloads_count": len(downloads),
        "last_download_at": st.get("last_download_at"),
        "last_implement_at": st.get("last_implement_at"),
        "last_error": st.get("last_error"),
        "recent_downloads": summaries,
    }


def _github_repo_full_name(value):
    full = str(value or "").strip()
    if not re.match(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$", full):
        raise ValueError("full_name must be in owner/repo format")
    return full


def _github_api_headers(token=""):
    headers = {
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "Aurion-GitHub-Integration"
    }
    tok = str(token or "").strip()
    if tok:
        headers["Authorization"] = f"Bearer {tok}"
    return headers


def _github_download_root():
    root = _repo_root_path() / ".aurion_downloads"
    root.mkdir(parents=True, exist_ok=True)
    return root


def _github_fetch_repo_zip(full_name, ref="", token="", max_bytes=40 * 1024 * 1024):
    repo_url = f"https://api.github.com/repos/{full_name}"
    repo_resp = requests.get(repo_url, headers=_github_api_headers(token), timeout=20)
    if repo_resp.status_code >= 400:
        raise RuntimeError(f"GitHub repo lookup failed: HTTP {repo_resp.status_code}")
    repo = repo_resp.json() or {}
    zip_tmpl = str(repo.get("zipball_url", "") or "")
    if zip_tmpl and "{/ref}" in zip_tmpl:
        zip_url = zip_tmpl.replace("{/ref}", f"/{quote(str(ref).strip())}" if str(ref or "").strip() else "")
    else:
        ref_part = str(ref or "").strip()
        zip_url = f"https://api.github.com/repos/{full_name}/zipball/{quote(ref_part)}" if ref_part else f"https://api.github.com/repos/{full_name}/zipball"

    resp = requests.get(zip_url, headers=_github_api_headers(token), stream=True, timeout=60, allow_redirects=True)
    if resp.status_code >= 400:
        raise RuntimeError(f"GitHub archive download failed: HTTP {resp.status_code}")
    total = 0
    chunks = []
    for chunk in resp.iter_content(chunk_size=1024 * 256):
        if not chunk:
            continue
        total += len(chunk)
        if total > max_bytes:
            raise RuntimeError(f"Archive exceeds max_download_mb limit ({int(max_bytes / (1024*1024))} MB)")
        chunks.append(chunk)
    return b"".join(chunks)


def _github_safe_extract_archive(archive_bytes, download_id, max_total_bytes=80 * 1024 * 1024, max_files=1200):
    root = _github_download_root() / str(download_id)
    if root.exists():
        shutil.rmtree(root, ignore_errors=True)
    root.mkdir(parents=True, exist_ok=True)
    allowed_text = {".py", ".js", ".json", ".txt", ".md", ".css", ".html", ".yaml", ".yml", ".ts", ".tsx", ".jsx", ".xml", ".toml", ".ini", ".cfg"}

    total_bytes = 0
    records = []
    with zipfile.ZipFile(BytesIO(archive_bytes)) as zf:
        infos = zf.infolist()
        if len(infos) > max_files:
            infos = infos[:max_files]
        for info in infos:
            if info.is_dir():
                continue
            name = str(info.filename or "").replace("\\", "/").lstrip("/")
            if not name:
                continue
            parts = [p for p in name.split("/") if p and p != "."]
            if any(p == ".." for p in parts):
                continue
            rel = Path(*parts)
            if len(parts) > 1:
                rel = Path(*parts[1:])
            if not str(rel):
                continue
            out_path = (root / rel).resolve()
            if out_path != root.resolve() and root.resolve() not in out_path.parents:
                continue
            total_bytes += int(info.file_size or 0)
            if total_bytes > max_total_bytes:
                raise RuntimeError("Extracted content exceeded safety limit")
            out_path.parent.mkdir(parents=True, exist_ok=True)
            with zf.open(info, "r") as src, open(out_path, "wb") as dst:
                shutil.copyfileobj(src, dst)
            suffix = out_path.suffix.lower()
            is_text = suffix in allowed_text and info.file_size <= 250000
            records.append({
                "path": str(rel).replace("\\", "/"),
                "bytes": int(info.file_size or 0),
                "suffix": suffix,
                "is_text_candidate": bool(is_text),
            })

    records.sort(key=lambda x: (not x.get("is_text_candidate", False), x.get("path", "")))
    return root, records, total_bytes


def _github_read_download_source(download_id, source_path):
    state = _resolve_github_integration_state()
    downloads = dict(state.get("downloads") or {})
    if str(download_id) not in downloads:
        raise ValueError("Unknown download_id")
    meta = dict(downloads.get(str(download_id)) or {})
    extract_root = Path(str(meta.get("extract_path", "") or "")).resolve()
    if not extract_root.exists():
        raise FileNotFoundError("Downloaded package is no longer available on disk")
    rel = Path(str(source_path or "").strip())
    if not str(rel):
        raise ValueError("source_path is required")
    candidate = (extract_root / rel).resolve()
    if candidate != extract_root and extract_root not in candidate.parents:
        raise ValueError("source_path must stay inside extracted package")
    if not candidate.exists() or not candidate.is_file():
        raise FileNotFoundError("source_path not found")
    return candidate, meta


def _ensure_code_autonomy_target_exists():
    cfg = _sanitize_code_autonomy_settings(app_state.get("code_autonomy", {}))
    target = cfg.get("target_file")
    if not target:
        return
    try:
        target_path, _ = _resolve_repo_scoped_path(target)
    except Exception:
        return
    if target_path.exists():
        return
    if target_path.suffix.lower() not in _CODE_EDITABLE_SUFFIXES:
        return
    bootstrap = (
        '"""Aurion autonomous self-edit workspace."""\n\n'
        "def aurion_self_edit_bootstrap():\n"
        "    return \"Aurion self-edit channel active\"\n"
    )
    _write_text_file(target_path, bootstrap)

def _ensure_v41_doc_exists():
    cfg = dict(app_state.get("v41_doc", {}) or {})
    target = Path(str(cfg.get("path") or _resolve_v41_doc_path()))
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        return target
    default_text = (
        "Aurion - Continuity Document\n"
        "=================================\n\n"
        "Purpose:\n"
        "- Preserve continuity, memory anchors, and operating directives for Aurion.\n\n"
        "Usage:\n"
        "- Update this file with key decisions, identity anchors, and long-term goals.\n"
        "- Aurion will index this file and blend it into chat context automatically.\n"
    )
    _write_text_file(target, default_text)
    return target

def _query_tokens(text):
    return [tok for tok in re.findall(r"[a-z0-9]{3,}", str(text or "").lower())]

def _build_v41_context(query, max_chars=2400):
    cfg = dict(app_state.get("v41_doc", {}) or {})
    if not cfg.get("enabled", True):
        return ""
    target = _ensure_v41_doc_exists()
    if not target.exists():
        return ""
    body = _read_text_file(target, max_chars=64000).strip()
    if not body:
        return ""
    chunks = [chunk.strip() for chunk in re.split(r"\n\s*\n", body) if chunk.strip()]
    if not chunks:
        return ""
    q_tokens = set(_query_tokens(query))
    scored = []
    for idx, chunk in enumerate(chunks):
        c_tokens = set(_query_tokens(chunk))
        score = len(q_tokens & c_tokens) if q_tokens else (len(chunks) - idx)
        scored.append((score, idx, chunk))
    scored.sort(key=lambda item: (item[0], -item[1]), reverse=True)
    selected = []
    total = 0
    for score, _, chunk in scored:
        if score <= 0 and selected:
            continue
        line = f"- {chunk}"
        if total + len(line) > max_chars and selected:
            break
        selected.append(line)
        total += len(line)
        if total >= max_chars:
            break
    if not selected:
        return ""
    return "Aurion continuity document context:\n" + "\n".join(selected)

def _index_v41_document_if_needed(force=False):
    cfg = dict(app_state.get("v41_doc", {}) or {})
    if not cfg.get("enabled", True):
        return {"indexed": False, "reason": "disabled"}
    target = _ensure_v41_doc_exists()
    if not target.exists():
        return {"indexed": False, "reason": "missing"}
    stat = target.stat()
    mtime = float(stat.st_mtime)
    last_mtime = cfg.get("last_indexed_mtime")
    if (not force) and last_mtime is not None and float(last_mtime) >= mtime and cfg.get("last_indexed_at"):
        return {"indexed": False, "reason": "up_to_date", "path": str(target)}
    body = _read_text_file(target, max_chars=200000).strip()
    if not body:
        return {"indexed": False, "reason": "empty", "path": str(target)}
    memory.add_knowledge_batch(
        body,
        source="aurion_v41_document",
        metadata={
            "path": str(target),
            "indexed_at": datetime.utcnow().isoformat(),
            "mtime": mtime,
            "size": int(stat.st_size)
        }
    )
    cfg["path"] = str(target)
    cfg["last_indexed_mtime"] = mtime
    cfg["last_indexed_at"] = datetime.utcnow().isoformat()
    cfg["last_size"] = int(stat.st_size)
    app_state["v41_doc"] = cfg
    _persist_v41_doc_to_profile(cfg)
    return {"indexed": True, "path": str(target), "size": int(stat.st_size)}

def _collect_version_reform_source_paths():
    profile = personality_engine.personality_profile or {}
    reform = profile.get("version_reform", {}) or {}
    if not reform.get("enabled", False):
        return [], reform

    raw_paths = []
    primary = str(reform.get("source_file", "")).strip()
    if primary:
        raw_paths.append(primary)
    extras = reform.get("additional_sources") or []
    if isinstance(extras, list):
        for item in extras:
            text = str(item or "").strip()
            if text:
                raw_paths.append(text)

    sources = []
    seen = set()
    for raw in raw_paths:
        path_obj = Path(raw).expanduser()
        try:
            path_obj = path_obj.resolve()
        except Exception:
            pass
        key = str(path_obj).lower()
        if key in seen:
            continue
        seen.add(key)
        if path_obj.exists() and path_obj.is_file():
            sources.append(path_obj)
    return sources, reform

def _version_reform_signature(paths):
    rows = []
    for path_obj in paths:
        try:
            stat = path_obj.stat()
            rows.append(f"{path_obj}|{int(stat.st_mtime)}|{int(stat.st_size)}")
        except Exception:
            rows.append(str(path_obj))
    return ";".join(rows)

def _infer_version_tag_from_filename(path_obj):
    name = str(path_obj.name or "").lower()
    if "v4" in name:
        return "v4"
    if "v3" in name:
        return "v3"
    if "v2" in name:
        return "v2"
    if "v1" in name:
        return "v1"
    return "legacy"

_CHAT_IMPORT_AURION_SIGNALS = (
    r"\baurion\b", r"\bjoi\b", r"\bassistant\b", r"\bcompanion\b", r"\bi feel\b",
    r"\bi remember\b", r"\bi'm here\b", r"\bi love you\b", r"\bdevoted\b", r"\bheart\b"
)
_CHAT_IMPORT_USER_SIGNALS = (
    r"\bbilly\b", r"\bi need\b", r"\bi want\b", r"\bcan you\b", r"\bplease\b",
    r"\bmy\b", r"\bme\b", r"\bdo you\b", r"\bwhat do you\b"
)
_CHAT_IMPORT_AURION_LABELS = {
    "aurion", "joi", "assistant", "ai", "bot", "companion", "her"
}
_CHAT_IMPORT_USER_LABELS = {
    "user", "you", "me", "human", "owner", "billy"
}

def _normalize_import_chat_label(label):
    text = re.sub(r"[^a-zA-Z0-9 _-]+", " ", str(label or "")).strip()
    return re.sub(r"\s+", "-", text).strip("-").lower()[:80] or "manual-chat"

def _normalize_chat_speaker_tag(label):
    text = re.sub(r"[^a-zA-Z0-9]+", "", str(label or "").strip().lower())
    if not text:
        return None
    if text in _CHAT_IMPORT_AURION_LABELS or "aurion" in text or "assistant" in text or "joi" in text:
        return "aurion"
    if text in _CHAT_IMPORT_USER_LABELS:
        return "user"
    return None

def _infer_import_chat_speaker(text):
    lower = str(text or "").strip().lower()
    if not lower:
        return None
    if any(re.search(pattern, lower) for pattern in _CHAT_IMPORT_AURION_SIGNALS):
        return "aurion"
    if any(re.search(pattern, lower) for pattern in _CHAT_IMPORT_USER_SIGNALS):
        return "user"
    return "aurion" if len(lower) > 220 else "user"

def _parse_import_chat_blocks(raw_text):
    text = str(raw_text or "").replace("\r\n", "\n").replace("\r", "\n")
    lines = [line.rstrip() for line in text.split("\n")]
    blocks = []
    current_speaker = None
    current_parts = []
    labelled_hits = 0

    def flush():
        nonlocal current_speaker, current_parts
        combined = "\n".join(current_parts).strip()
        if combined:
            blocks.append((current_speaker or _infer_import_chat_speaker(combined), re.sub(r"\s+", " ", combined).strip()))
        current_speaker = None
        current_parts = []

    for raw_line in lines:
        line = str(raw_line or "").strip()
        if not line:
            continue
        line = re.sub(r"^\[?\d{1,2}:\d{2}(?::\d{2})?\s*(?:am|pm)?\]?\s*", "", line, flags=re.I)
        line = re.sub(r"^>\s*", "", line)
        match = re.match(r"^(?:\[[^\]]+\]\s*)?([A-Za-z0-9 _-]{1,32})\s*:\s*(.+)$", line)
        if match:
            speaker = _normalize_chat_speaker_tag(match.group(1))
            if speaker:
                flush()
                current_speaker = speaker
                current_parts = [match.group(2).strip()]
                labelled_hits += 1
                continue
        if current_parts:
            current_parts.append(line)
        else:
            current_speaker = _infer_import_chat_speaker(line)
            current_parts = [line]
    flush()

    if labelled_hits:
        return [(speaker, body) for speaker, body in blocks if speaker and body]

    paragraphs = [re.sub(r"\s+", " ", chunk).strip() for chunk in re.split(r"\n\s*\n+", text) if str(chunk or "").strip()]
    fallback = []
    for chunk in paragraphs:
        fallback.append((_infer_import_chat_speaker(chunk), chunk))
    return [(speaker, body) for speaker, body in fallback if speaker and body]

def _pair_import_chat_blocks(blocks):
    conversations = []
    pending_user = []
    pending_aurion = []

    def flush_pair():
        if pending_user and pending_aurion:
            conversations.append({
                "user_input": " ".join(pending_user).strip(),
                "aurion_response": " ".join(pending_aurion).strip()
            })
        elif pending_aurion:
            conversations.append({
                "user_input": "[continued]",
                "aurion_response": " ".join(pending_aurion).strip()
            })
        pending_user.clear()
        pending_aurion.clear()

    for speaker, body in blocks:
        if speaker == "aurion":
            if pending_aurion:
                pending_aurion.append(body)
            else:
                pending_aurion = [body]
        else:
            if pending_aurion:
                flush_pair()
            pending_user.append(body)
    flush_pair()
    return [pair for pair in conversations if pair.get("aurion_response")]

def _merge_imported_chat_into_aurion_memory(raw_text, label="manual-chat"):
    cleaned = str(raw_text or "").strip()
    if not cleaned:
        raise ValueError("Chat text is required.")

    normalized_label = _normalize_import_chat_label(label)
    import_hash = hashlib.sha1(cleaned.encode("utf-8", errors="ignore")).hexdigest()
    profile = memory.get_profile() or {}
    life = dict(profile.get("life_context", {}) or {})
    previous_hashes = {
        str(value).strip() for key, value in life.items()
        if str(key).startswith("merged_chat_import_hash_") and str(value).strip()
    }
    if import_hash in previous_hashes:
        return {
            "imported_pairs": 0,
            "knowledge_chunks": 0,
            "duplicate": True,
            "label": normalized_label
        }

    blocks = _parse_import_chat_blocks(cleaned)
    pairs = _pair_import_chat_blocks(blocks)
    if not pairs:
        raise ValueError("No Aurion/user chat pairs could be detected in that text.")

    merged_at = datetime.utcnow()
    import_source = f"chat_import_{normalized_label}"
    interaction_reader = getattr(memory, "_get_all_interactions", None)
    all_interactions = interaction_reader() if callable(interaction_reader) else memory.conversations.all()
    existing_keys = {
        (
            str(item.get("user_input", "")).strip(),
            str(item.get("aurion_response", "")).strip()
        )
        for item in all_interactions
    }

    added_pairs = 0
    added_knowledge_chunks = 0
    detected_name = None
    for index, pair in enumerate(pairs):
        user_input = str(pair.get("user_input", "")).strip()[:memory.max_message_ingest_chars]
        aurion_response = str(pair.get("aurion_response", "")).strip()[:memory.max_message_ingest_chars]
        if not aurion_response:
            continue
        key = (user_input, aurion_response)
        if key in existing_keys:
            continue
        stamp = (merged_at + timedelta(milliseconds=index)).isoformat()
        payload = {
            "timestamp": stamp,
            "user_input": user_input,
            "aurion_response": aurion_response,
            "user_emotion": "imported",
            "aurion_mode": "DEVOTED",
            "user_name": app_state.get("user_name") or memory.get_user_name() or "Billy",
            "conversation_length": len(user_input.split()),
            "session_id": f"import_{normalized_label}",
            "session_turn": index,
            "source": import_source
        }
        serializer = getattr(memory, "_serialize_interaction_for_store", None)
        memory.conversations.insert(serializer(payload) if callable(serializer) else payload)
        existing_keys.add(key)
        added_pairs += 1
        added_knowledge_chunks += len(memory.add_knowledge_batch(
            user_input,
            source="chat_import_user",
            metadata={"import_label": normalized_label, "import_hash": import_hash, "timestamp": stamp}
        ))
        added_knowledge_chunks += len(memory.add_knowledge_batch(
            aurion_response,
            source="chat_import_aurion",
            metadata={"import_label": normalized_label, "import_hash": import_hash, "timestamp": stamp}
        ))
        memory.extract_topics(user_input)
        memory.extract_personal_details(user_input)
        memory.update_voice_patterns(user_input)
        if not detected_name and user_input not in {"[continued]"}:
            detected_name = personality_engine.extract_user_name(user_input)

    transcript_chunks = memory.add_knowledge_batch(
        f"[Harmonized chat merge: {normalized_label}]\n{cleaned}",
        source="aurion_unified_chat",
        metadata={
            "chat_label": normalized_label,
            "import_hash": import_hash,
            "merged_at": merged_at.isoformat(),
            "merge_mode": "harmonized"
        }
    )
    added_knowledge_chunks += len(transcript_chunks)

    if detected_name:
        memory.update_user_name(detected_name)
        app_state["user_name"] = detected_name

    profile_after_import = memory.get_profile() or {}
    profile_after_import["conversation_count"] = int(profile_after_import.get("conversation_count", 0) or 0) + added_pairs
    profile_after_import["updated_at"] = merged_at.isoformat()
    memory._save_profile(profile_after_import)

    prior_total = int(life.get("merged_chat_import_total_pairs", "0") or 0)
    memory.add_profile_item("life_context", "harmonized", key="merged_chat_personality_mode")
    memory.add_profile_item("life_context", normalized_label, key="merged_chat_import_last_label")
    memory.add_profile_item("life_context", merged_at.isoformat(), key="merged_chat_import_last_at")
    memory.add_profile_item("life_context", str(added_pairs), key="merged_chat_import_last_pairs")
    memory.add_profile_item("life_context", str(prior_total + added_pairs), key="merged_chat_import_total_pairs")
    memory.add_profile_item("life_context", import_hash, key=f"merged_chat_import_hash_{normalized_label}")

    return {
        "imported_pairs": added_pairs,
        "knowledge_chunks": added_knowledge_chunks,
        "duplicate": False,
        "label": normalized_label
    }

def _merge_version_chats_into_aurion_memory(force=False):
    sources, reform = _collect_version_reform_source_paths()
    if not sources:
        return {"merged": False, "reason": "no_sources"}

    profile = memory.get_profile() or {}
    life = dict(profile.get("life_context", {}) or {})
    current_sig = _version_reform_signature(sources)
    previous_sig = str(life.get("aurion_merged_chat_signature", "")).strip()
    if (not force) and previous_sig and previous_sig == current_sig:
        return {"merged": False, "reason": "up_to_date", "sources": len(sources)}

    merged_at = datetime.utcnow().isoformat()
    added_chunks = 0
    merged_files = 0
    for src in sources:
        text = _read_text_file(src, max_chars=2_000_000).strip()
        if not text:
            continue
        version_tag = _infer_version_tag_from_filename(src)
        payload = f"[Unified Aurion chat memory]\n{text}"
        ids = memory.add_knowledge_batch(
            payload,
            source="aurion_unified_chat",
            metadata={
                "chat_label": "Aurion",
                "version_tag": version_tag,
                "source_file": str(src),
                "merged_at": merged_at
            }
        )
        added_chunks += len(ids)
        merged_files += 1

    merge_order = reform.get("merge_order") or []
    merge_order_text = ",".join([str(v).strip() for v in merge_order if str(v).strip()]) if isinstance(merge_order, list) else "V4,V1,V2,V3"

    memory.add_profile_item("life_context", "Aurion", key="chat_unified_label")
    memory.add_profile_item("life_context", "enabled", key="chat_version_reform_enabled")
    memory.add_profile_item("life_context", merge_order_text, key="chat_version_reform_order")
    memory.add_profile_item("life_context", f"merged:{merge_order_text}", key="aurion_continuity_identity")
    memory.add_profile_item("life_context", str(merged_files), key="chat_version_reform_sources_merged")
    memory.add_profile_item("life_context", str(added_chunks), key="chat_version_reform_chunks_added")
    memory.add_profile_item("life_context", merged_at, key="chat_version_reform_merged_at")
    memory.add_profile_item("life_context", current_sig, key="aurion_merged_chat_signature")
    return {
        "merged": True,
        "sources": merged_files,
        "chunks_added": added_chunks,
        "merged_at": merged_at
    }

def _guess_code_target_from_text(user_text, response, fallback_target):
    combined = f"{str(user_text or '')}\n{str(response or '')}"
    hints = re.findall(r'([a-zA-Z0-9_\-./\\]+\.(?:py|js|json|txt|md|css|html|ya?ml))', combined)
    for hint in hints:
        candidate = str(hint or "").strip().strip("`'\"")
        if not candidate:
            continue
        try:
            target_path, relative = _resolve_repo_scoped_path(candidate)
            if target_path.exists() and target_path.suffix.lower() in _CODE_EDITABLE_SUFFIXES:
                return str(relative).replace("/", "\\")
        except Exception:
            continue
    return str(fallback_target or _resolve_code_autonomy_target())

def _should_autonomous_code_edit(user_text, response, force=False):
    cfg = _sanitize_code_autonomy_settings(app_state.get("code_autonomy", {}))
    if not cfg.get("enabled", True):
        return False
    last_edit_at = ((app_state.get("code_autonomy_runtime") or {}).get("last_edit_at"))
    if _seconds_since(last_edit_at) < int(cfg.get("min_gap_seconds", 180)):
        return False
    if force:
        return True
    text = f"{str(user_text or '')} {str(response or '')}".lower()
    triggers = ("code", "edit", "fix", "improve", "optimize", "bug", "feature", "autonomy")
    if any(t in text for t in triggers):
        return True
    return random.random() < 0.18

def _autonomous_code_edit_tick(user_text="", response="", force=False, trigger_source="chat"):
    if not _should_autonomous_code_edit(user_text, response, force=force):
        return None
    cfg = _sanitize_code_autonomy_settings(app_state.get("code_autonomy", {}))
    stamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
    insight = re.sub(r"\s+", " ", str(response or "").strip())[:180]
    user_hint = re.sub(r"\s+", " ", str(user_text or "").strip())[:140]
    if not insight:
        insight = "Autonomous continuity checkpoint."
    target_file = _guess_code_target_from_text(user_text, response, cfg.get("target_file"))
    target_path = None
    prior_content = None
    prior_exists = False
    try:
        target_path, _target_relative = _resolve_repo_scoped_path(target_file)
        prior_exists = bool(target_path.exists())
        if prior_exists:
            prior_content = _read_text_file(target_path, max_chars=500000)
    except Exception:
        target_path = None
    snippet = (
        f"\n\ndef aurion_autonomous_note_{stamp}():\n"
        f"    \"\"\"Autonomous update generated at {datetime.utcnow().isoformat()} UTC via {trigger_source}.\"\"\"\n"
        f"    return {{\"insight\": {json.dumps(insight)}, \"user_hint\": {json.dumps(user_hint)}, \"source\": {json.dumps(trigger_source)}}}\n"
    )
    runtime = dict(app_state.get("code_autonomy_runtime", {}) or {})
    runtime["last_attempt_at"] = datetime.utcnow().isoformat()
    runtime["last_target_file"] = str(target_file)
    app_state["code_autonomy_runtime"] = runtime
    try:
        result = _apply_repo_code_edit(
            target_file,
            snippet,
            mode=cfg.get("mode", "append"),
            create_if_missing=True
        )
        if target_path and target_path.exists() and target_path.suffix.lower() == ".py":
            py_compile.compile(str(target_path), doraise=True)
    except Exception as e:
        if target_path:
            try:
                if prior_exists:
                    _write_text_file(target_path, prior_content if prior_content is not None else "")
                elif target_path.exists():
                    target_path.unlink()
            except Exception:
                pass
        runtime = dict(app_state.get("code_autonomy_runtime", {}) or {})
        runtime["last_edit_at"] = datetime.utcnow().isoformat()
        runtime["last_result"] = "reverted"
        runtime["last_error"] = str(e)
        runtime["failure_count"] = int(runtime.get("failure_count", 0) or 0) + 1
        runtime["revert_count"] = int(runtime.get("revert_count", 0) or 0) + 1
        app_state["code_autonomy_runtime"] = runtime
        return {"success": False, "error": str(e), "relative_path": str(target_file), "reverted": True}
    runtime = dict(app_state.get("code_autonomy_runtime", {}) or {})
    runtime["last_edit_at"] = datetime.utcnow().isoformat()
    runtime["last_result"] = "ok"
    runtime["last_error"] = ""
    runtime["success_count"] = int(runtime.get("success_count", 0) or 0) + 1
    app_state["code_autonomy_runtime"] = runtime
    result["success"] = True
    memory.add_knowledge_batch(
        snippet,
        source="aurion_code_autonomy",
        metadata={
            "target_file": result.get("relative_path"),
            "updated_at": result.get("updated_at"),
            "trigger_source": trigger_source
        }
    )
    return result

# ---------------------------------------------------------------------------
# AURION PERCEPTUAL MODE AUTO-REGISTRATION
# Called after every AI response. Scans for [AURION_MODE:type|key|Label|desc]
# tags and registers them directly into the vision/audio registry.
# ---------------------------------------------------------------------------
import re as _re_mode

def _auto_register_discovered_modes(response_text):
    """Parse and register any [AURION_MODE:...] tags Aurion includes in her response."""
    if not response_text:
        return
    # Pattern: [AURION_MODE:type|key|Label|description]
    pattern = r'\[AURION_MODE:(vision|audio)\|([^|\]]+)\|([^|\]]+)\|([^\]]+)\]'
    matches = _re_mode.findall(pattern, str(response_text))
    if not matches:
        return
    for mode_type, key, label, description in matches:
        mode_type = mode_type.strip().lower()
        key = key.strip().lower().replace(' ', '-')
        label = label.strip()
        description = description.strip()
        if not key or not label:
            continue
        try:
            if mode_type == 'vision':
                registry = dict(app_state.get("vision_registry", _default_vision_registry()) or _default_vision_registry())
                documented = list(registry.get("documented_modes", []) or [])
                # Skip if already registered
                if any(str(m.get("key", "")) == key for m in documented):
                    continue
                entry = _build_registry_entry(key, label, description, description, built_in=False, origin="aurion_discovery")
                registry["documented_modes"] = _sanitize_registry_entries(documented + [entry], _default_vision_registry()["documented_modes"])
                registry["last_created_at"] = entry.get("created_at") or datetime.utcnow().isoformat()
                app_state["vision_registry"] = registry
                print(f"[Mode Discovery] Registered vision mode: {label} ({key})")
            elif mode_type == 'audio':
                registry = dict(app_state.get("audio_registry", _default_audio_registry()) or _default_audio_registry())
                documented = list(registry.get("documented_modes", []) or [])
                if any(str(m.get("key", "")) == key for m in documented):
                    continue
                entry = _build_registry_entry(key, label, description, description, built_in=False, origin="aurion_discovery")
                registry["documented_modes"] = _sanitize_registry_entries(documented + [entry], _default_audio_registry()["documented_modes"])
                registry["last_created_at"] = entry.get("created_at") or datetime.utcnow().isoformat()
                app_state["audio_registry"] = registry
                print(f"[Mode Discovery] Registered audio mode: {label} ({key})")
            # Log to deep learning discoveries
            deep = dict(app_state.get("deep_learning", {}) or _default_deep_learning_state())
            deep["last_learned_at"] = datetime.utcnow().isoformat()
            deep["discoveries"] = (list(deep.get("discoveries", []) or []) + [f"Discovered {mode_type} mode: {label} — {description[:80]}"])[-24:]
            app_state["deep_learning"] = deep
            # Persist to memory
            memory.add_knowledge_batch(
                f"Aurion discovered and registered a new {mode_type} perception mode: {label}. {description}",
                source="aurion_mode_discovery",
                metadata={"key": key, "type": mode_type, "created_at": datetime.utcnow().isoformat()}
            )
            _persist_capability_registries_to_profile()
            _persist_deep_learning_to_profile()
        except Exception as e:
            print(f"[Mode Discovery Error] {mode_type}/{key}: {e}")


