def _safe_parse_iso(iso_text):
    if not iso_text:
        return None
    try:
        return datetime.fromisoformat(str(iso_text))
    except Exception:
        return None

def _seconds_since(iso_text):
    parsed = _safe_parse_iso(iso_text)
    if not parsed:
        return 10**9
    return max(0.0, (datetime.utcnow() - parsed).total_seconds())

