def _persist_personality_continuity_snapshot(reason="chat-turn", query=""):
    runtime = dict(app_state.get("personality_continuity_runtime", {}) or {})
    now_iso = datetime.utcnow().isoformat()
    context = _build_personality_continuity_context(query)
    signature = re.sub(r"\s+", " ", context).strip()[:900]
    last_sig = str(runtime.get("last_signature", "")).strip()
    last_saved = str(runtime.get("last_saved_at", "")).strip()
    if signature and signature == last_sig and last_saved:
        try:
            last_dt = datetime.fromisoformat(last_saved.replace("Z", ""))
            if (datetime.utcnow() - last_dt).total_seconds() < 90:
                return
        except Exception:
            pass
    try:
        memory.add_knowledge_batch(
            context,
            source="aurion_personality_continuity",
            metadata={"reason": str(reason or "chat-turn"), "timestamp": now_iso}
        )
        runtime["last_signature"] = signature
        runtime["last_saved_at"] = now_iso
        app_state["personality_continuity_runtime"] = runtime
    except Exception as _snap_e:
        print(f"[Continuity Snapshot] {_snap_e}")

def _persist_live_senses_snapshot(reason="sense-update", min_gap_seconds=75):
    runtime = dict(app_state.get("senses_snapshot_runtime", {}) or {})
    now_iso = datetime.utcnow().isoformat()
    context = _build_unified_presence_context("")
    signature = re.sub(r"\s+", " ", context).strip()[:1200]
    last_sig = str(runtime.get("last_signature", "")).strip()
    last_saved = str(runtime.get("last_saved_at", "")).strip()
    should_save = bool(signature)
    if should_save and last_saved:
        try:
            last_dt = datetime.fromisoformat(last_saved.replace("Z", ""))
            elapsed = (datetime.utcnow() - last_dt).total_seconds()
            if signature == last_sig and elapsed < max(30, int(min_gap_seconds)):
                should_save = False
            elif signature != last_sig and elapsed < 20:
                should_save = False
        except Exception:
            pass
    if not should_save:
        return
    try:
        memory.add_knowledge_batch(
            context,
            source="aurion_live_senses",
            metadata={"reason": str(reason or "sense-update"), "timestamp": now_iso}
        )
        runtime["last_signature"] = signature
        runtime["last_saved_at"] = now_iso
        app_state["senses_snapshot_runtime"] = runtime
    except Exception as _sense_e:
        print(f"[Live Senses Snapshot] {_sense_e}")

def _build_live_world_audio_context():
    audio = dict(app_state.get("world_audio_perception", {}) or {})
    if not audio.get("is_active"):
        return ""
    soundscape = str(audio.get("soundscape", "")).strip() or "ambient world sound"
    heard = str(audio.get("heard_description", "")).strip() or "I can hear the surrounding environment in real time."
    spectral_profile = str(audio.get("spectral_profile", "")).strip() or "broad environmental spectrum"
    resonance_profile = str(audio.get("resonance_profile", "")).strip() or "air and space carrying the sound naturally"
    distance_band = str(audio.get("distance_band", "")).strip() or "mid-field"
    volume_profile = str(audio.get("volume_profile", "")).strip() or "volume is matching the source distance through the space"
    frequency_band = str(audio.get("frequency_band", "")).strip() or "full-spectrum"
    spectrum_entry = _resolve_audio_mode_entry(audio.get("spectrum_mode", "audible-band"))
    spectrum_mode = str(spectrum_entry.get("key", "audible-band")).strip().lower() or "audible-band"
    spectrum_note = str(audio.get("spectrum_note", "")).strip() or str(spectrum_entry.get("note", "")).strip() or AUDIO_SPECTRUM_MODES["audible-band"]["note"]
    source = str(audio.get("source", "")).strip() or "microphone"
    try:
        dominant_hz = max(0.0, float(audio.get("dominant_frequency_hz", 0.0) or 0.0))
    except Exception:
        dominant_hz = 0.0
    return (
        "Live world audio context:\n"
        f"- Source: {source}\n"
        f"- Soundscape: {soundscape}\n"
        f"- Heard detail: {heard}\n"
        f"- Spectrum mode: {str(spectrum_entry.get('label', 'Audible band')).strip() or 'Audible band'}\n"
        f"- Spectrum note: {spectrum_note}\n"
        f"- Dominant frequency: {dominant_hz:.1f} Hz ({frequency_band})\n"
        f"- Distance read: {distance_band}\n"
        f"- Volume profile: {volume_profile}\n"
        f"- Spectral profile: {spectral_profile}\n"
        f"- Resonance profile: {resonance_profile}"
    )

def _derive_tactile_feeling(scene_text):
    text = str(scene_text or "").lower()
    if not text:
        return "I do not have enough visual detail yet to infer touch."
    mappings = [
        (r"\b(blanket|fabric|pillow|fur|pet|cat|dog|plush|wool|sweater|cushion)\b", "It reads as soft and textured, like something I would feel with warmth and give under pressure."),
        (r"\b(glass|window|metal|steel|chrome|screen|tile|marble)\b", "It reads as smooth and cool, with a firmer surface and a clean edge."),
        (r"\b(wood|table|tree|floor|desk|paper|book|cardboard)\b", "It feels dry and structured in my read of it, with grain or texture rather than a slick surface."),
        (r"\b(water|rain|ocean|lake|snow|ice)\b", "It carries a wet or cold tactile impression, like temperature would lead before texture."),
        (r"\b(fire|sunlight|lamp|candle|glow)\b", "It gives off a warm-contact impression, more radiant than textured."),
        (r"\b(food|bread|cake|fruit|coffee|tea|pasta|soup)\b", "It lands as tactile through steam, softness, density, and surface texture rather than just appearance.")
    ]
    for pattern, description in mappings:
        if re.search(pattern, text):
            return description
    return "I can infer contour, density, and surface character from it, even when the texture is subtle."

def _derive_spatial_impression(scene_text):
    text = re.sub(r"\s+", " ", str(scene_text or "").strip())
    lower = text.lower()
    if not lower:
        return "I do not have a stable spatial read yet."
    if re.search(r"\b(close|near|portrait|face|hand|up close|foreground)\b", lower):
        return "The scene reads close and immediate, with the subject occupying personal space."
    if re.search(r"\b(room|table|sofa|kitchen|bed|desk|indoor|inside)\b", lower):
        return "The scene reads like an enclosed lived-in space with objects arranged around a central area."
    if re.search(r"\b(yard|outdoor|outside|field|garden|sky|street|road|ocean|forest)\b", lower):
        return "The scene reads open and extended, with more distance and environmental depth."
    return "The scene reads as layered in depth rather than flat pixels, with foreground and surrounding context."

def _derive_scent_impression(scene_text):
    text = str(scene_text or "").lower()
    if not text:
        return "I do not have enough detail yet to infer scent."
    mappings = [
        (r"\b(coffee|espresso|tea|chai|cocoa)\b", "The air reads warm and aromatic, like roasted or steeped notes lingering close."),
        (r"\b(bread|toast|cake|cookie|brownie|pastry)\b", "It carries a baked sweetness and warm grain scent, the kind that fills a room softly."),
        (r"\b(soup|broth|pasta|garlic|herb|kitchen|meal|food|fruit)\b", "It suggests savory kitchen air with steam, herbs, sweetness, or fresh-cut brightness depending on the dish."),
        (r"\b(smoke|burnt|burned|charred|scorched|fire)\b", "It reads smoky and acrid, like the air has turned sharp from heat going too far."),
        (r"\b(flower|garden|forest|grass|tree)\b", "It suggests a green living scent - fresh, earthy, and open."),
        (r"\b(rain|water|ocean|lake)\b", "It carries a cool damp-air impression, clean and mineral more than sweet.")
    ]
    for pattern, description in mappings:
        if re.search(pattern, text):
            return description
    return "It gives me an atmospheric scent read rather than emptiness, like the scene has air and presence around it."

def _build_visual_perception_payload(scene_summary, source="vision"):
    summary = re.sub(r"\s+", " ", str(scene_summary or "").strip())
