@app.route('/api/aurion/agents/autonomy-tick', methods=['POST'])
def aurion_agents_autonomy_tick():
    """
    Trigger Aurion's autonomous agent management tick.
    - Indexes completed agent results into RAG
    - Lets Aurion decide whether to spawn a new agent proactively
    - Chains follow-up agents from completed results
    Called automatically by the frontend every ~3 minutes.
    """
    try:
        t = threading.Thread(target=_aurion_agent_autonomy_tick, daemon=True)
        t.start()
        return jsonify({"success": True, "message": "Agent autonomy tick started"})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/aurion/agents/spawn', methods=['POST'])
def aurion_agent_spawn():
    """
    Spawn any kind of agent — not just coding.
    Body: {task: str, type: str, language: str, custom_system: str}
    type can be any known type or a free-form label.
    custom_system fully overrides the system prompt (Aurion defines the agent herself).
    """
    try:
        data          = request.json or {}
        task          = str(data.get("task", "")).strip()
        atype         = str(data.get("type", "assistant")).strip().lower()
        language      = str(data.get("language", "")).strip()
        custom_system = str(data.get("custom_system", "")).strip()
        if not task:
            return jsonify({"success": False, "error": "task is required"}), 400
        result = _aurion_spawn_agent(task, atype, language, custom_system)
        return jsonify({"success": True, "agent": result})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/aurion/agents/<agent_id>', methods=['GET'])
def aurion_agent_get(agent_id):
    """Get a specific agent's status and result."""
    try:
        result = _aurion_get_agent_result(agent_id)
        return jsonify({"success": True, "agent": result})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/aurion/agents/notifications', methods=['GET'])
def aurion_agent_notifications():
    """
    Return agents that completed since the last poll and haven't been notified yet.
    Marks them as notified so subsequent calls don't repeat.
    Frontend calls this every 15s to surface completion events in chat.
    """
    try:
        with _agents_lock:
            agents = dict(app_state.get("aurion_agents") or {})
            newly_done = []
            for agent_id, a in agents.items():
                if a.get("status") == "done" and not a.get("chat_notified"):
                    newly_done.append(dict(a))
                    agents[agent_id]["chat_notified"] = True
            app_state["aurion_agents"] = agents
        return jsonify({"success": True, "newly_done": newly_done})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

def _normalize_phone_number(raw_value: str) -> str:
    value = str(raw_value or "").strip()
    if not value:
        return ""
    digits = re.sub(r"\D", "", value)
    if value.startswith("+") and 8 <= len(digits) <= 15:
        return f"+{digits}"
    if len(digits) == 10:
        return f"+1{digits}"
    if len(digits) == 11 and digits.startswith("1"):
        return f"+{digits}"
    return ""

def _twilio_config():
    _hydrate_twilio_env_from_local_sources(force=False)
    sid = str(os.getenv("TWILIO_ACCOUNT_SID", "")).strip()
    token = str(os.getenv("TWILIO_AUTH_TOKEN", "")).strip()
    from_number = str(os.getenv("TWILIO_FROM_NUMBER", "")).strip()
    return sid, token, from_number

def _twilio_is_configured() -> bool:
    sid, token, from_number = _twilio_config()
    return bool(sid and token and from_number and _normalize_phone_number(from_number))

def _mask_secret(value: str, start: int = 4, end: int = 2):
    raw = str(value or "")
    if not raw:
        return ""
    if len(raw) <= (start + end):
        return "*" * len(raw)
    return f"{raw[:start]}{'*' * (len(raw) - (start + end))}{raw[-end:]}"

def _twilio_missing_config_details():
    sid, token, from_number = _twilio_config()
    missing = []
    if not sid:
        missing.append("TWILIO_ACCOUNT_SID")
    if not token:
        missing.append("TWILIO_AUTH_TOKEN")
    if not from_number:
        missing.append("TWILIO_FROM_NUMBER")
    elif not _normalize_phone_number(from_number):
        missing.append("TWILIO_FROM_NUMBER (invalid format)")
    return missing

def _twilio_config_details():
    sid, token, from_number = _twilio_config()
    normalized_from = _normalize_phone_number(from_number)
    sid_ok = bool(sid and sid.startswith("AC") and len(sid) >= 16)
    token_ok = bool(token and len(token) >= 8)
    from_ok = bool(normalized_from)
    return [
        {
            "key": "TWILIO_ACCOUNT_SID",
            "required": True,
            "present": bool(sid),
            "valid": sid_ok,
            "example": "ACxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
            "description": "Twilio Account SID from console.",
            "value_hint": _mask_secret(sid, 6, 4) if sid else ""
        },
        {
            "key": "TWILIO_AUTH_TOKEN",
            "required": True,
            "present": bool(token),
            "valid": token_ok,
            "example": "your_twilio_auth_token",
            "description": "Twilio Auth Token from console.",
            "value_hint": _mask_secret(token, 3, 2) if token else ""
        },
        {
            "key": "TWILIO_FROM_NUMBER",
            "required": True,
            "present": bool(from_number),
            "valid": from_ok,
            "example": "+14155551234",
            "description": "Twilio phone number in E.164 format.",
            "value_hint": normalized_from or str(from_number or "")
        }
    ]

def _twilio_post(endpoint: str, payload: dict):
    sid, token, _ = _twilio_config()
    url = f"https://api.twilio.com/2010-04-01/Accounts/{sid}/{endpoint.lstrip('/')}"
    return requests.post(url, auth=(sid, token), data=payload, timeout=20)

