def _discord_fetch_channel_messages(bot_token: str, channel_id: str, limit: int = 25):
    safe_limit = max(1, min(50, int(limit or 25)))
    url = f"https://discord.com/api/v10/channels/{channel_id}/messages"
    headers = {
        "Authorization": f"Bot {bot_token}",
        "User-Agent": "AurionPhoneLink/1.0"
    }
    resp = requests.get(url, params={"limit": safe_limit}, headers=headers, timeout=20)
    return resp

def _snowflake_to_int(value: str) -> int:
    text = str(value or "").strip()
    if not text.isdigit():
        return 0
    try:
        return int(text)
    except Exception:
        return 0

def _normalize_discord_message(row):
    row = row if isinstance(row, dict) else {}
    author = row.get("author") if isinstance(row.get("author"), dict) else {}
    attachments = row.get("attachments") if isinstance(row.get("attachments"), list) else []
    return {
        "id": str(row.get("id", "")).strip(),
        "author": str(author.get("global_name") or author.get("username") or "Unknown"),
        "author_id": str(author.get("id", "")).strip(),
        "is_bot": bool(author.get("bot")),
        "is_webhook": bool(row.get("webhook_id")),
        "platform": "discord",
        "content": str(row.get("content", "")).strip(),
        "created_at": str(row.get("timestamp", "")).strip(),
        "attachments": [
            {
                "url": str(att.get("url", "")).strip(),
                "filename": str(att.get("filename", "")).strip()
            }
            for att in attachments
            if isinstance(att, dict) and str(att.get("url", "")).strip()
        ]
    }

def _normalize_twitch_oauth(token_value: str) -> str:
    token = str(token_value or "").strip()
    if not token:
        return ""
    return token if token.lower().startswith("oauth:") else f"oauth:{token}"

def _is_twitch_oauth_token(token_value: str) -> bool:
    token = _normalize_twitch_oauth(token_value)
    return token.lower().startswith("oauth:") and len(token) >= 16

def _is_twitch_username(username_value: str) -> bool:
    username = str(username_value or "").strip().lower()
    return bool(re.match(r"^[a-z0-9_]{3,25}$", username))

def _is_twitch_channel(channel_value: str) -> bool:
    channel = str(channel_value or "").strip().lower().lstrip("#")
    return bool(re.match(r"^[a-z0-9_]{3,25}$", channel))

