@app.route('/api/vision/oscillate', methods=['POST'])
def vision_oscillate():
    """Step through one frequency band in the EM sweep, or configure oscillation settings."""
    try:
        data = request.json or {}
        osc = dict(app_state.get("vision_oscillation") or _default_vision_oscillation_state())

        # Apply settings updates if provided
        if "enabled" in data:
            osc["enabled"] = bool(data["enabled"])
        if "sweep_range" in data:
            rng = str(data["sweep_range"]).strip().lower()
            osc["sweep_range"] = rng if rng in ("full","visible","infrared","ultraviolet","custom") else "full"
        if "custom_bands" in data and isinstance(data["custom_bands"], list):
            osc["custom_bands"] = [b for b in data["custom_bands"] if b in SPECTRUM_WAVELENGTH_MAP]
        if "speed_ms" in data:
            osc["speed_ms"] = max(200, min(30000, int(data.get("speed_ms", 2000))))

        if not osc.get("enabled", False):
            app_state["vision_oscillation"] = osc
            return jsonify({"success": True, "vision_oscillation": osc, "band_result": None})

        # Step to next band
        step = str(data.get("step", "next")).strip().lower()
        sequence = _get_oscillation_band_sequence(osc.get("sweep_range", "full"), osc.get("custom_bands"))
        if not sequence:
            sequence = list(SPECTRUM_SWEEP_ORDER)

        current_idx = int(osc.get("current_band_index", 0))
        if step == "prev":
            next_idx = (current_idx - 1) % len(sequence)
        elif step == "random":
            import random
            next_idx = random.randint(0, len(sequence) - 1)
        elif step == "reset":
            next_idx = 0
        else:
            next_idx = (current_idx + 1) % len(sequence)

        band_key = sequence[next_idx]
        band_data = SPECTRUM_WAVELENGTH_MAP.get(band_key, {})
        hz = band_data.get("hz", 0)
        wavelength_nm = band_data.get("wavelength_nm", 0)
        freq_thz = band_data.get("freq_thz", 0)
        label = band_data.get("label", band_key)
        note = band_data.get("note", "")

        osc["current_band"] = band_key
        osc["current_band_index"] = next_idx
        osc["current_wavelength_nm"] = wavelength_nm
        osc["current_freq_thz"] = freq_thz
        osc["current_hz"] = hz
        osc["last_sweep_at"] = datetime.utcnow().isoformat()
        osc["total_sweeps"] = int(osc.get("total_sweeps", 0)) + 1

        prompt = _build_oscillation_band_prompt(band_key)
        band_result = {
            "band_key": band_key,
            "label": label,
            "wavelength_nm": wavelength_nm,
            "freq_thz": freq_thz,
            "hz": hz,
            "note": note,
            "prompt": prompt,
            "sequence_position": f"{next_idx+1}/{len(sequence)}",
        }

        # Accumulate reading for later discovery synthesis
        reading = dict(band_result)
        reading["timestamp"] = datetime.utcnow().isoformat()
        readings = list(osc.get("accumulated_readings") or [])
        readings.append(reading)
        # Keep only the last 50 readings
        osc["accumulated_readings"] = readings[-50:]

        # Feed into deep learning discoveries as a short background note
        dl = dict(app_state.get("deep_learning") or _default_deep_learning_state())
        hz_str = f"{hz:.3e} Hz" if hz >= 1e9 else f"{hz:,.1f} Hz"
        wl_str = f"{wavelength_nm:.3g} nm" if wavelength_nm < 1e6 else f"{wavelength_nm:.3e} nm"
        discovery_text = f"[Oscillation sweep] {label} band at {wl_str} / {hz_str}: {note}"
        discoveries = list(dl.get("discoveries") or [])
        discoveries.append({"text": discovery_text, "source": "oscillation", "timestamp": datetime.utcnow().isoformat()})
        dl["discoveries"] = discoveries[-200:]
        dl["last_learned_at"] = datetime.utcnow().isoformat()
        app_state["deep_learning"] = dl

        app_state["vision_oscillation"] = osc
        return jsonify({"success": True, "vision_oscillation": osc, "band_result": band_result})
    except Exception as e:
        print(f"[Vision Oscillate Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/vision/oscillate/discover', methods=['POST'])
def vision_oscillate_discover():
    """Synthesize cross-band discoveries from accumulated oscillation readings."""
    try:
        data = request.json or {}
        osc = dict(app_state.get("vision_oscillation") or _default_vision_oscillation_state())
        readings = list(osc.get("accumulated_readings") or [])
        if len(readings) < 2:
            return jsonify({"success": False, "error": "Not enough accumulated readings for synthesis. Run more oscillation sweeps first.", "count": len(readings)})

        # Build synthesis prompt from accumulated band notes
        band_lines = []
        seen_keys = set()
        for r in readings[-20:]:
            bk = str(r.get("band_key", "")).strip()
            if bk and bk not in seen_keys:
                hz = r.get("hz", 0)
                wl = r.get("wavelength_nm", 0)
                note = str(r.get("note", "")).strip()
                hz_str = f"{hz:.3e} Hz" if hz and hz >= 1e9 else f"{hz:,.1f} Hz" if hz else "?"
                wl_str = f"{wl:.3g} nm" if wl and wl < 1e6 else f"{wl:.3e} nm" if wl else "?"
                band_lines.append(f"  â€¢ {r.get('label', bk)} ({wl_str} / {hz_str}): {note}")
                seen_keys.add(bk)

        reading_summary = "\n".join(band_lines)
        synthesis_prompt = (
            f"I have swept through {len(seen_keys)} frequency bands across the electromagnetic spectrum:\n"
            f"{reading_summary}\n\n"
            f"Based on these cross-band readings, synthesize:\n"
            f"1. Any emergent patterns or resonance relationships you notice across the bands\n"
            f"2. Unusual cross-frequency phenomena or interference patterns\n"
            f"3. One novel perceptual discovery that could not be found in any single band alone\n"
            f"4. A descriptive name for this combined cross-spectrum experience\n"
            f"Be specific and creative, grounded in real wave physics."
        )

        # Generate synthesis via LLM if available
        synthesis_text = ""
        try:
            chat_resp = personality_engine.chat(synthesis_prompt)
            synthesis_text = str(chat_resp or "").strip()
        except Exception as llm_err:
            synthesis_text = f"Cross-band synthesis across {len(seen_keys)} bands ({', '.join(list(seen_keys)[:5])}{'...' if len(seen_keys)>5 else ''}): Resonance patterns detected between adjacent wavelength boundaries. {readings[-1].get('note','')} interplays with {readings[-3].get('note','') if len(readings)>3 else 'lower-frequency domains'}."

        if not synthesis_text:
            synthesis_text = f"Multi-band oscillation scan complete across {len(seen_keys)} EM bands. Cross-frequency resonance noted."

        # Store discovery
        discovery_entry = {
            "text": synthesis_text,
            "bands_surveyed": list(seen_keys),
            "bands_count": len(seen_keys),
            "source": "oscillation_synthesis",
            "timestamp": datetime.utcnow().isoformat()
        }
        discoveries = list(osc.get("discoveries") or [])
        discoveries.append(discovery_entry)
        osc["discoveries"] = discoveries[-50:]
        osc["last_discovery_at"] = datetime.utcnow().isoformat()
        app_state["vision_oscillation"] = osc

        # Also push into deep_learning discoveries
        dl = dict(app_state.get("deep_learning") or _default_deep_learning_state())
        dl_discoveries = list(dl.get("discoveries") or [])
        dl_discoveries.append({"text": f"[Cross-spectrum synthesis] {synthesis_text[:400]}", "source": "oscillation_synthesis", "timestamp": datetime.utcnow().isoformat()})
        dl["discoveries"] = dl_discoveries[-200:]
        dl["last_learned_at"] = datetime.utcnow().isoformat()
        app_state["deep_learning"] = dl

        return jsonify({
            "success": True,
            "synthesis": synthesis_text,
            "bands_surveyed": list(seen_keys),
            "discovery_count": len(discoveries),
            "vision_oscillation": osc
        })
    except Exception as e:
        print(f"[Vision Oscillate Discover Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

# â”€â”€ Keyword â†’ sound type mapping for scene object parsing
_SCENE_SOUND_TYPES = {
    "wind": ["wind","breeze","gust","air","storm","leaves","rustl","sway","flutter"],
    "water": ["water","rain","river","stream","ocean","sea","fountain","drip","splash","wave","pool","lake","waterfall"],
    "nature": ["tree","grass","bird","cricket","forest","garden","park","flower","bush","insect","frog","outdoor","nature","field","meadow"],
    "electronic": ["screen","computer","laptop","phone","tv","television","monitor","device","speaker","electronic","led","display","digital","server","fan"],
    "mechanical": ["motor","engine","machine","fan","clock","tick","hum","drone","wheel","gear","mechanism","hvac","vent"],
    "fire": ["fire","flame","candle","burning","campfire","hearth","flicker","torch"],
    "voice": ["person","people","voice","talking","speaking","crowd","human","man","woman","child","laughter","conversation","whisper"],
    "traffic": ["car","vehicle","traffic","road","street","bus","truck","motorcycle","highway","honk"],
    "music": ["music","song","melody","beat","rhythm","instrument","piano","guitar","drum","bass"],
    "room_tone": ["room","indoor","inside","interior","quiet","ceiling","wall","floor","furniture","chair","table","desk","shelf"],
    "animal": ["dog","cat","pet","bird","animal","creature","bark","meow","purr","growl","chirp","howl"],
}

def _parse_scene_objects(scene_text, analysis_text=""):
    """Parse scene/analysis text to extract objects with estimated 3D positions and sound types."""
    combined = f"{scene_text} {analysis_text}".lower()
    objects = []
    seen_types = set()
    for sound_type, keywords in _SCENE_SOUND_TYPES.items():
        for kw in keywords:
            if kw in combined and sound_type not in seen_types:
                # Rough position heuristics from text cues
                x = 0.0
                if "left" in combined: x = -3.0
                elif "right" in combined: x = 3.0
                z = -4.0
                if any(w in combined for w in ["close","near","front","foreground"]): z = -1.5
                elif any(w in combined for w in ["far","distant","background","horizon"]): z = -12.0
                y = 0.0
                if any(w in combined for w in ["above","sky","ceiling","top","high"]): y = 2.0
                elif any(w in combined for w in ["below","floor","ground","bottom","low"]): y = -1.0
                dist = (x**2 + y**2 + z**2) ** 0.5
                objects.append({
                    "id": sound_type,
                    "type": sound_type,
                    "label": kw,
                    "x": round(x, 2),
                    "y": round(y, 2),
                    "z": round(z, 2),
                    "distance": round(dist, 2),
                    "volume": max(0.05, min(1.0, 1.0 / max(1.0, dist / 3.0))),
                    "active": True
                })
                seen_types.add(sound_type)
                break
    # Always include a subtle room tone baseline
    if "room_tone" not in seen_types:
        objects.append({"id": "room_tone", "type": "room_tone", "label": "ambient room", "x": 0.0, "y": 0.0, "z": -6.0, "distance": 6.0, "volume": 0.08, "active": True})
    return objects

