@app.route('/api/home/window', methods=['POST'])
def set_home_window():
    try:
        data = request.get_json(force=True) or {}
        home = dict(app_state.get("home_environment") or _default_home_state())
        wins   = list(home.get("windows_open") or [])
        action = str(data.get("action", "toggle"))
        win_id = str(data.get("window_id", "living_room_w1"))
        if action == "open"   and win_id not in wins: wins.append(win_id)
        elif action == "close" and win_id in wins:    wins.remove(win_id)
        elif action == "toggle":
            if win_id in wins: wins.remove(win_id)
            else:              wins.append(win_id)
        home["windows_open"] = wins
        app_state["home_environment"] = home
        return jsonify({"success": True, "windows_open": wins})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

