@app.route('/api/world-engine/control', methods=['POST'])
def control_world_engine():
    try:
        data = request.get_json(force=True) or {}
        home = dict(app_state.get("home_environment") or _default_home_state())
        life_reg = dict(app_state.get("life_registry") or _default_life_registry())
        weather = dict(home.get("weather") or {})
        we = _compute_live_world_engine_state()
        # Allow manual overrides for select fields
        rp = dict(we.get("rendering_pipeline") or {})
        if "render_scale" in data:
            rp["render_scale"] = max(0.5, min(2.0, float(data["render_scale"])))
        if "shadow_quality" in data and data["shadow_quality"] in ("low","medium","high","ultra"):
            rp["shadow_quality"] = data["shadow_quality"]
        if "volumetrics" in data:
            rp["volumetrics"] = bool(data["volumetrics"])
        we["rendering_pipeline"] = rp
        ux = dict(we.get("ux_polish") or {})
        if "clarity_pct" in data:
            ux["clarity_pct"] = max(0.0, min(100.0, float(data["clarity_pct"])))
        if "accessibility_pct" in data:
            ux["accessibility_pct"] = max(0.0, min(100.0, float(data["accessibility_pct"])))
        we["ux_polish"] = ux
        phys = dict(we.get("dynamic_physics_engine") or {})
        if "enabled" in data:
            phys["enabled"] = bool(data["enabled"])
        if "tick_rate_hz" in data and data["tick_rate_hz"] in (30, 60, 120):
            phys["tick_rate_hz"] = int(data["tick_rate_hz"])
        we["dynamic_physics_engine"] = phys
        app_state["world_engine"] = we
        return jsonify({"success": True, "world_engine": we})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

