@app.route('/api/world/motion-sound', methods=['POST'])
def update_motion_sound():
    """Receive scene analysis, extract objects, build real-time spatial audio + motion source list."""
    try:
        data = request.json or {}
        current = dict(app_state.get("spatial_audio") or {})
        scene_text  = str(data.get("scene_summary", "") or "").strip()
        analysis    = str(data.get("analysis",      "") or "").strip()
        ambient_hint = str(data.get("ambient_profile", current.get("ambient_profile", "indoor_quiet"))).strip()
        if "enabled" in data:
            current["enabled"] = bool(data["enabled"])
        current["ambient_profile"] = ambient_hint
        objects = _parse_scene_objects(scene_text, analysis)
        current["scene_objects"] = objects
        current["sound_sources"] = objects
        current["last_updated_at"] = datetime.utcnow().isoformat()
        current["total_updates"] = int(current.get("total_updates", 0)) + 1
        app_state["spatial_audio"] = current
        return jsonify({"success": True, "spatial_audio": current})
    except Exception as e:
        print(f"[Motion Sound Update Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/status')
def get_status():
    auto_self_repair_if_due(trigger="status_poll", min_interval_seconds=8)
    _sync_realtime_emotion(trigger="status")
    _sync_realtime_behavior(trigger="status")
    _auto_sync_if_due(reason="status_poll")
    memory_count = 0
    repair_info = None
    try:
        memory_count = memory.get_interaction_count()
    except Exception as e:
        print(f"[Status Error] Memory read failed: {e}")
        repair_info = run_self_repair(trigger="status_exception")
        try:
            memory_count = memory.get_interaction_count()
        except Exception as inner:
            print(f"[Status Error] Memory read still failing after repair: {inner}")
            memory_count = 0
    memory_resilience = {}
    try:
        memory_resilience = memory.get_memory_resilience_status()
    except Exception as e:
        memory_resilience = {"error": str(e)}

    senses_state = {}
    memory_continuity = {}
    video_state = {}
    chat_state = {}
    perception_state = {}
    world_state = {}
    capabilities_state = {}
