@app.route('/api/github/search', methods=['GET'])
def github_search_repos():
    try:
        query = str(request.args.get("q", "") or "").strip()
        if not query:
            return jsonify({"success": False, "error": "q is required"}), 400
        per_page = max(1, min(12, int(request.args.get("per_page", 8) or 8)))
        token = str(request.args.get("token", "") or "").strip()
        url = "https://api.github.com/search/repositories"
        resp = requests.get(url, params={"q": query, "sort": "stars", "order": "desc", "per_page": per_page}, headers=_github_api_headers(token), timeout=20)
        if resp.status_code >= 400:
            return jsonify({"success": False, "error": f"GitHub search failed: HTTP {resp.status_code}"}), 400
        payload = resp.json() or {}
        items = []
        for row in list(payload.get("items") or [])[:per_page]:
            items.append({
                "full_name": row.get("full_name"),
                "description": row.get("description"),
                "stargazers_count": int(row.get("stargazers_count", 0) or 0),
                "language": row.get("language"),
                "default_branch": row.get("default_branch"),
                "html_url": row.get("html_url"),
                "updated_at": row.get("updated_at"),
            })
        return jsonify({"success": True, "results": items, "total_count": int(payload.get("total_count", 0) or 0)})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/github/download', methods=['POST'])
def github_download_repo():
    try:
        data = request.get_json(force=True) or {}
        state = _resolve_github_integration_state()
        if not state.get("enabled", True):
            return jsonify({"success": False, "error": "GitHub integration is disabled"}), 403
        if not state.get("allow_download", True):
            return jsonify({"success": False, "error": "GitHub download is disabled"}), 403

        full_name = _github_repo_full_name(data.get("full_name"))
        ref = str(data.get("ref", "") or "").strip()
        token = str(data.get("token", "") or "").strip()
        max_mb = int(state.get("max_download_mb", 40) or 40)
        archive_bytes = _github_fetch_repo_zip(full_name, ref=ref, token=token, max_bytes=max_mb * 1024 * 1024)
        download_id = str(uuid.uuid4())[:10]
        extract_root, files, total_bytes = _github_safe_extract_archive(archive_bytes, download_id)

        text_files = [
            {"path": row.get("path"), "bytes": int(row.get("bytes", 0) or 0), "suffix": row.get("suffix")}
            for row in files if row.get("is_text_candidate")
        ][:160]

        downloads = dict(state.get("downloads") or {})
        downloads[download_id] = {
            "repo": full_name,
            "ref": ref,
            "created_at": datetime.utcnow().isoformat(),
            "extract_path": str(extract_root),
            "file_count": len(files),
            "total_bytes": int(total_bytes),
            "text_files_preview": text_files[:40],
        }
        state["downloads"] = downloads
        state["last_download_at"] = datetime.utcnow().isoformat()
        state["last_error"] = None
        app_state["github_integration"] = state

        return jsonify({
            "success": True,
            "download_id": download_id,
            "repo": full_name,
            "ref": ref,
            "file_count": len(files),
            "total_bytes": int(total_bytes),
            "text_files": text_files,
            "github_integration": _public_github_integration_state(state),
        })
    except Exception as e:
        state = _resolve_github_integration_state()
        state["last_error"] = str(e)
        app_state["github_integration"] = state
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/github/implement', methods=['POST'])
def github_implement_from_download():
    try:
        data = request.get_json(force=True) or {}
        state = _resolve_github_integration_state()
        if not state.get("enabled", True):
            return jsonify({"success": False, "error": "GitHub integration is disabled"}), 403
        if not state.get("allow_implement", True):
            return jsonify({"success": False, "error": "GitHub implementation is disabled"}), 403

        download_id = str(data.get("download_id", "") or "").strip()
        source_path = str(data.get("source_path", "") or "").strip()
        target_path = str(data.get("target_path", "") or "").strip()
        mode = str(data.get("mode", "append") or "append").strip().lower()
        if mode not in {"append", "replace"}:
            mode = "append"
        if not download_id or not source_path or not target_path:
            return jsonify({"success": False, "error": "download_id, source_path, and target_path are required"}), 400

        source_file, meta = _github_read_download_source(download_id, source_path)
        if source_file.suffix.lower() not in _CODE_EDITABLE_SUFFIXES:
            return jsonify({"success": False, "error": "source_path must be a supported text/code file"}), 400
        max_chars = max(500, min(300000, int(data.get("max_chars", 70000) or 70000)))
        source_text = _read_text_file(source_file, max_chars=max_chars)
        truncated = int(source_file.stat().st_size) > len(source_text.encode("utf-8", errors="ignore"))

        result = _apply_repo_code_edit(
            path_text=target_path,
            content=source_text,
            mode=mode,
            create_if_missing=bool(data.get("create_if_missing", True)),
        )

        state["last_implement_at"] = datetime.utcnow().isoformat()
        state["last_error"] = None
        app_state["github_integration"] = state
        return jsonify({
            "success": True,
            "download_id": download_id,
            "source_path": source_path,
            "repo": str(meta.get("repo", "") or ""),
            "target": result,
            "mode": mode,
            "source_truncated": bool(truncated),
            "github_integration": _public_github_integration_state(state),
        })
    except Exception as e:
        state = _resolve_github_integration_state()
        state["last_error"] = str(e)
        app_state["github_integration"] = state
        return jsonify({"success": False, "error": str(e)}), 500



