@app.route('/api/wardrobe/design', methods=['POST'])
def wardrobe_design_outfit():
    try:
        data = request.get_json(force=True) or {}
        state = _resolve_wardrobe_state()
        runtime = _normalize_runtime_appearance(
            data.get("runtime"),
            palette=data.get("palette"),
            fallback_asset_key=str(data.get("asset_key", "") or _select_wardrobe_asset_key(
                style=str(data.get("style", "") or ""),
                garments=list(data.get("garments") or []),
                palette=list(data.get("palette") or [])
            ))
        )
        outfit = {
            "name": str(data.get("name", "Aurion Custom Outfit") or "Aurion Custom Outfit")[:80],
            "style": str(data.get("style", "anime couture") or "anime couture")[:80],
            "garments": [str(x).strip() for x in list(data.get("garments") or []) if str(x).strip()][:24],
            "jewelry": [str(x).strip() for x in list(data.get("jewelry") or []) if str(x).strip()][:24],
            "palette": [str(x).strip() for x in list(data.get("palette") or []) if str(x).strip()][:16],
            "notes": str(data.get("notes", "") or "")[:500],
            "created_at": datetime.utcnow().isoformat(),
            "runtime": runtime
        }
        if not outfit["garments"]:
            outfit["garments"] = ["tailored jacket", "layered top", "flow skirt"]
        if not outfit["jewelry"]:
            outfit["jewelry"] = ["statement pendant"]

        save = bool(data.get("save", True))
        wear = bool(data.get("wear", True))
        if save:
            state["saved_outfits"] = list(state.get("saved_outfits") or []) + [outfit]
            state["saved_outfits"] = list(state.get("saved_outfits") or [])[-120:]
            for g in outfit["garments"]:
                if g not in state["saved_garments"]:
                    state["saved_garments"].append(g)
            for j in outfit["jewelry"]:
                if j not in state["saved_jewelry"]:
                    state["saved_jewelry"].append(j)
        if wear:
            state["active_outfit"] = outfit
            state["last_worn_at"] = datetime.utcnow().isoformat()
        state["active_runtime_appearance"] = _resolve_wardrobe_runtime_appearance(
            state.get("active_outfit"), state.get("runtime_registry")
        )
        state["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["wardrobe"] = state
        return jsonify({"success": True, "wardrobe": state, "outfit": outfit})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/wardrobe/wear', methods=['POST'])
def wardrobe_wear_outfit():
    try:
        data = request.get_json(force=True) or {}
        state = _resolve_wardrobe_state()
        name = str(data.get("name", "") or "").strip().lower()
        selected = None
        for row in list(state.get("saved_outfits") or []):
            if str(row.get("name", "") or "").strip().lower() == name and name:
                selected = dict(row)
                break
        if selected is None and isinstance(data.get("outfit"), dict):
            selected = dict(data.get("outfit") or {})
        if selected is None:
            return jsonify({"success": False, "error": "Outfit not found"}), 404
        state["active_outfit"] = {
            "name": str(selected.get("name", "Custom Outfit") or "Custom Outfit")[:80],
            "style": str(selected.get("style", "custom") or "custom")[:80],
            "garments": [str(x).strip() for x in list(selected.get("garments") or []) if str(x).strip()][:24],
            "jewelry": [str(x).strip() for x in list(selected.get("jewelry") or []) if str(x).strip()][:24],
            "palette": [str(x).strip() for x in list(selected.get("palette") or []) if str(x).strip()][:16],
            "notes": str(selected.get("notes", "") or "")[:500],
            "created_at": str(selected.get("created_at", datetime.utcnow().isoformat()) or datetime.utcnow().isoformat()),
            "runtime": _normalize_runtime_appearance(selected.get("runtime"), palette=selected.get("palette"))
        }
        state["last_worn_at"] = datetime.utcnow().isoformat()
        state["active_runtime_appearance"] = _resolve_wardrobe_runtime_appearance(
            state.get("active_outfit"), state.get("runtime_registry")
        )
        state["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["wardrobe"] = state
        return jsonify({"success": True, "wardrobe": state, "active_outfit": state.get("active_outfit")})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/wardrobe/garment', methods=['POST'])
def wardrobe_save_garment():
    try:
        data = request.get_json(force=True) or {}
        item = str(data.get("garment", "") or "").strip()
        if not item:
            return jsonify({"success": False, "error": "garment is required"}), 400
        state = _resolve_wardrobe_state()
        if item not in state["saved_garments"]:
            state["saved_garments"].append(item)
        state["saved_garments"] = list(state["saved_garments"])[-300:]
        state["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["wardrobe"] = state
        return jsonify({"success": True, "wardrobe": state})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


