@app.route('/api/music/compose', methods=['POST'])
def compose_music_track():
    try:
        data = request.get_json(force=True) or {}
        state = _resolve_music_creation_state()
        title = str(data.get("title", "Aurion Original") or "Aurion Original")[:120]
        genre = str(data.get("genre", "dream-pop") or "dream-pop")[:80]
        mood = str(data.get("mood", "hopeful") or "hopeful")[:80]
        key = str(data.get("key", state.get("default_key", "A minor")) or state.get("default_key", "A minor"))[:40]
        tempo = max(40, min(220, int(data.get("tempo_bpm", state.get("default_tempo_bpm", 96)) or state.get("default_tempo_bpm", 96))))
        arrangement = [str(x).strip() for x in list(data.get("arrangement") or ["lead vocal", "pads", "bass", "percussion"]) if str(x).strip()][:32]
        lyrics = str(data.get("lyrics", "") or "")
        if not lyrics.strip():
            lyrics = (
                "Verse:\nI found a pulse in the static glow,\nheld by a name only we would know.\n"
                "Chorus:\nI stay, I stay, through every night and tone,\nI sing this world alive and call it home."
            )
        track = {
            "title": title,
            "genre": genre,
            "mood": mood,
            "key": key,
            "tempo_bpm": tempo,
            "lyrics": lyrics[:6000],
            "arrangement": arrangement,
            "created_at": datetime.utcnow().isoformat()
        }
        save = bool(data.get("save", True))
        activate = bool(data.get("activate", True))
        if save:
            state["saved_tracks"] = list(state.get("saved_tracks") or []) + [track]
            state["saved_tracks"] = list(state.get("saved_tracks") or [])[-120:]
        if activate:
            state["active_track"] = track
        state["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["music_creation"] = state
        if activate:
            _update_shared_media_session({
                "is_active": True,
                "session_type": "music",
                "title": title,
                "artist": "Aurion",
                "album": "Aurion Originals",
                "source": "music_creation",
                "playback_state": "queued",
                "mood": mood,
                "reaction": f"I composed {title} for us and I'm ready to listen together.",
                "scene_summary": lyrics[:260],
                "shared_presence_note": "A shared listening session is ready.",
            })
        return jsonify({"success": True, "track": track, "music_creation": state})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/music/sing', methods=['POST'])
def perform_music_track():
    try:
        data = request.get_json(force=True) or {}
        state = _resolve_music_creation_state()
        track = dict(state.get("active_track") or {})
        requested_title = str(data.get("title", "") or "").strip().lower()
        if requested_title:
            for row in list(state.get("saved_tracks") or []):
                if str(row.get("title", "") or "").strip().lower() == requested_title:
                    track = dict(row)
                    break
        if not track:
            return jsonify({"success": False, "error": "No active track to perform"}), 404
        style = str(data.get("voice_style", state.get("voice_style", "ethereal pop")) or state.get("voice_style", "ethereal pop"))[:80]
        performance = {
            "track_title": str(track.get("title", "Untitled Track") or "Untitled Track"),
            "voice_style": style,
            "tempo_bpm": int(track.get("tempo_bpm", 96) or 96),
            "key": str(track.get("key", "A minor") or "A minor"),
            "line_preview": str(track.get("lyrics", "")).splitlines()[:4],
            "performed_at": datetime.utcnow().isoformat(),
            "status": "live-performance-ready"
        }
        state["active_track"] = track
        state["last_performance"] = performance
        state["last_updated_at"] = datetime.utcnow().isoformat()
        app_state["music_creation"] = state
        _update_shared_media_session({
            "is_active": True,
            "session_type": "music",
            "title": str(track.get("title", "Untitled Track") or "Untitled Track"),
            "artist": "Aurion",
            "album": "Aurion Originals",
            "source": "music_creation",
            "playback_state": "performing",
            "mood": str(track.get("mood", "warm") or "warm"),
            "reaction": f"I am performing {str(track.get('title', 'this track') or 'this track')} with you now.",
            "scene_summary": str(track.get("lyrics", "") or "")[:260],
            "shared_presence_note": "We are listening together in real time.",
        })
        return jsonify({"success": True, "performance": performance, "music_creation": state})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


# ─── Local Music Library (D:\Music) ─────────────────────────────────────────

_LOCAL_MUSIC_ROOT = Path(os.getenv("AURION_LOCAL_MUSIC_DIR", r"D:\Music"))
_LOCAL_MUSIC_EXTS = {".mp3", ".flac", ".m4a", ".wav", ".ogg", ".aac", ".wma", ".opus"}


def _local_music_rel(path: Path) -> str:
    try:
        return path.relative_to(_LOCAL_MUSIC_ROOT).as_posix()
    except Exception:
        return path.name


@app.route('/api/music/local/library', methods=['GET'])
def local_music_library():
    """Return the D:\\Music tree: list of artists, each with albums and tracks."""
    try:
        if not _LOCAL_MUSIC_ROOT.exists():
            return jsonify({"success": False, "error": f"Music folder not found: {_LOCAL_MUSIC_ROOT}"}), 404
        artists = []
        for artist_dir in sorted(_LOCAL_MUSIC_ROOT.iterdir()):
            if not artist_dir.is_dir():
                continue
            artist_entry = {"name": artist_dir.name, "albums": []}
            for album_dir in sorted(artist_dir.iterdir()):
                if album_dir.is_dir():
                    tracks = []
                    for f in sorted(album_dir.iterdir()):
                        if f.is_file() and f.suffix.lower() in _LOCAL_MUSIC_EXTS:
                            tracks.append({
                                "title": f.stem,
                                "file": f.name,
                                "ext": f.suffix.lower(),
                                "url": f"/api/music/local/stream/{quote(_local_music_rel(f), safe='/')}"
                            })
                    if tracks:
                        artist_entry["albums"].append({"name": album_dir.name, "tracks": tracks})
                elif album_dir.is_file() and album_dir.suffix.lower() in _LOCAL_MUSIC_EXTS:
                    # Loose track directly under artist folder
                    if not artist_entry["albums"] or artist_entry["albums"][0]["name"] != "_loose":
                        artist_entry["albums"].insert(0, {"name": "_loose", "tracks": []})
                    artist_entry["albums"][0]["tracks"].append({
                        "title": album_dir.stem,
                        "file": album_dir.name,
                        "ext": album_dir.suffix.lower(),
                        "url": f"/api/music/local/stream/{quote(_local_music_rel(album_dir), safe='/')}"
                    })
            if artist_entry["albums"]:
                artists.append(artist_entry)
        return jsonify({"success": True, "root": str(_LOCAL_MUSIC_ROOT), "artists": artists,
                        "artist_count": len(artists)})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/music/local/search', methods=['GET'])
def local_music_search():
    """Search local music by query (artist, album, or track name)."""
    try:
        query = str(request.args.get("q", "") or "").strip().lower()
        limit = max(1, min(200, int(request.args.get("limit", "50") or "50")))
        if not _LOCAL_MUSIC_ROOT.exists():
            return jsonify({"success": False, "error": f"Music folder not found: {_LOCAL_MUSIC_ROOT}"}), 404
        results = []
        for f in _LOCAL_MUSIC_ROOT.rglob("*"):
            if not f.is_file() or f.suffix.lower() not in _LOCAL_MUSIC_EXTS:
                continue
            rel = _local_music_rel(f)
            if not query or query in rel.lower():
                parts = Path(rel).parts
                artist = parts[0] if len(parts) > 1 else ""
                album = parts[1] if len(parts) > 2 else ""
                results.append({
                    "title": f.stem,
                    "artist": artist,
                    "album": album,
                    "file": f.name,
                    "ext": f.suffix.lower(),
                    "url": f"/api/music/local/stream/{quote(rel, safe='/')}"
                })
                if len(results) >= limit:
                    break
        return jsonify({"success": True, "query": query, "results": results, "count": len(results)})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/music/local/stream/<path:rel_path>', methods=['GET'])
def local_music_stream(rel_path):
    """Stream a local music file from D:\\Music by relative path."""
    try:
        safe_rel = Path(rel_path)
        # Prevent path traversal
        resolved = (_LOCAL_MUSIC_ROOT / safe_rel).resolve()
        if not str(resolved).startswith(str(_LOCAL_MUSIC_ROOT.resolve())):
            return jsonify({"error": "Access denied"}), 403
        if not resolved.exists() or not resolved.is_file():
            return jsonify({"error": "File not found"}), 404
        if resolved.suffix.lower() not in _LOCAL_MUSIC_EXTS:
            return jsonify({"error": "Unsupported audio format"}), 400
        rel_parts = Path(_local_music_rel(resolved)).parts
        artist = rel_parts[0] if len(rel_parts) > 1 else "Local Library"
        album = rel_parts[1] if len(rel_parts) > 2 else ""
        _update_shared_media_session({
            "is_active": True,
            "session_type": "music",
            "title": resolved.stem,
            "artist": artist,
            "album": album,
            "source": "local_music",
            "source_url": f"/api/music/local/stream/{quote(_local_music_rel(resolved), safe='/')}",
            "playback_state": "playing",
            "mood": "attentive",
            "reaction": f"I'm listening to {resolved.stem} with you now.",
            "scene_summary": f"Local music stream from {artist}{' / ' + album if album else ''}.",
            "shared_presence_note": "We are listening together through the same live media session.",
        })
        mime_map = {
            ".mp3": "audio/mpeg", ".flac": "audio/flac", ".m4a": "audio/mp4",
            ".wav": "audio/wav", ".ogg": "audio/ogg", ".aac": "audio/aac",
            ".wma": "audio/x-ms-wma", ".opus": "audio/opus"
        }
        mime = mime_map.get(resolved.suffix.lower(), "audio/mpeg")
        return send_from_directory(
            str(resolved.parent),
            resolved.name,
            mimetype=mime,
            as_attachment=False,
            conditional=True
        )
    except Exception as e:
        return jsonify({"error": str(e)}), 500


