@app.route('/api/proactive/settings', methods=['POST'])
def update_proactive_settings():
    data = request.json or {}
    setting = data.get("setting")
    value = data.get("value")
    settings = app_state.setdefault("proactive_settings", {
        "enabled": True,
        "min_idle_seconds": 60,
        "min_gap_seconds": 120
    })

    if setting == "enabled":
        settings["enabled"] = str(value).lower() == "enabled"
    elif setting == "cadence":
        settings["min_gap_seconds"] = max(30, min(900, int(value)))
    else:
        return jsonify({"error": "Invalid proactive setting"}), 400

    return jsonify({
        "success": True,
        "settings": settings
    })

@app.route('/api/proactive/next', methods=['GET'])
def get_next_proactive_message():
    settings = app_state.get("proactive_settings", {})
    if not settings.get("enabled", True):
        return jsonify({"has_message": False})

    # Don't compete with an active user-message LLM call
    if _LLM_BUSY.is_set():
        return jsonify({"has_message": False})

    idle_seconds = _seconds_since(app_state.get("last_user_activity_at"))
    gap_seconds = _seconds_since(app_state.get("last_proactive_at"))
    min_idle = int(settings.get("min_idle_seconds", 60))
    min_gap = int(settings.get("min_gap_seconds", 120))
    if idle_seconds < min_idle or gap_seconds < min_gap:
        return jsonify({"has_message": False})

    _sync_realtime_emotion(trigger="proactive")
    _sync_realtime_behavior(trigger="proactive")
    message = _build_proactive_message()
    app_state["last_proactive_at"] = datetime.utcnow().isoformat()

    try:
        memory.log_interaction(
            "[PROACTIVE_CHECKIN]",
            message,
            app_state["current_emotion"],
            app_state["current_mode"],
            user_name=app_state.get("user_name")
        )
    except Exception as e:
        print(f"[Proactive Log Error] {e}")

    return jsonify({
        "has_message": True,
        "message": message,
        "voice_enabled": app_state.get("voice_enabled", False),
        "behavior_settings": _sanitize_behavior_settings(app_state.get("behavior_settings", {}))
    })

