@app.route('/api/profile', methods=['POST'])
def update_user_profile():
    """Manually add/update persistent user profile details."""
    try:
        data = request.json or {}
        category = data.get('category')
        value = data.get('value')
        key = data.get('key')

        if not category or value is None:
            return jsonify({"error": "category and value are required"}), 400

        allowed = {
            'preferences',
            'accomplishments',
            'personal_details',
            'life_context',
            'relationship_type',
            'intimacy_mode',
            'affection_style',
            'consent_mode',
            'adult_content_style',
            'roleplay_mode',
            'roleplay_style',
            'roleplay_scenario',
            'coding_mode',
            'code_explanation_style',
            'preferred_code_language',
            'high_concept_openness',
            'epistemic_style',
            'emotional_attachment_mode',
            'attachment_depth',
            'attachment_expression',
            'attachment_adaptability',
            'loving_language_level',
            'romantic_tone_level',
            'intimacy_level',
            'profanity_mode',
            'adult_topic_mode',
            'preferred_topic_length',
            'humor_style',
            'emotional_nuance',
            'lexicon_adaptation'
        }
        if category not in allowed:
            return jsonify({"error": f"Invalid category. Use one of: {', '.join(sorted(allowed))}"}), 400

        memory.add_profile_item(category, value, key=key)
        return jsonify({"success": True, "profile": memory.get_profile()})
    except Exception as e:
        print(f"[Profile POST Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/profile/import-chat', methods=['POST'])
def import_profile_chat():
    """Merge a pasted or uploaded chat transcript into Aurion's existing memory/personality context."""
    try:
        data = request.json or {}
        text = str(data.get('text', '') or '').strip()
        label = str(data.get('label', '') or 'manual chat').strip()
        if not text:
            return jsonify({"success": False, "error": "text is required"}), 400
        result = _merge_imported_chat_into_aurion_memory(text[:750000], label=label)
        merge_state = dict(app_state.get("memory_merge") or {})
        merge_state["last_label"] = str(result.get("label", label)).strip() or label
        merge_state["last_imported_pairs"] = int(result.get("imported_pairs", 0) or 0)
        merge_state["last_merged_at"] = datetime.utcnow().isoformat()
        merge_state["last_status"] = "duplicate" if result.get("duplicate") else "merged"
        if not result.get("duplicate"):
            merge_state["total_merges"] = int(merge_state.get("total_merges", 0) or 0) + 1
        app_state["memory_merge"] = merge_state
        try:
            _persist_personality_continuity_snapshot(reason="chat-merge", query=label)
        except Exception as _snap_e:
            print(f"[Continuity Snapshot Merge] {_snap_e}")
        return jsonify({
            "success": True,
            **result,
            "profile": memory.get_profile() or {},
            "memory_count": memory.get_interaction_count()
        })
    except ValueError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    except Exception as e:
        print(f"[Profile Chat Import Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

