@app.route('/api/media/perception', methods=['POST'])
def update_media_perception():
    try:
        data = request.json or {}
        current = dict(app_state.get("media_perception", {}) or {})
        current["is_playing"] = bool(data.get("is_playing", current.get("is_playing", False)))
        current["title"] = str(data.get("title", current.get("title", ""))).strip()
        current["source"] = str(data.get("source", current.get("source", ""))).strip()
        audio_entry = _resolve_audio_mode_entry(data.get("spectrum_mode", current.get("spectrum_mode", (app_state.get("audio_registry") or {}).get("active_mode", "audible-band"))))
        current["spectrum_mode"] = str(audio_entry.get("key", "audible-band")).strip().lower() or "audible-band"
        current["spectrum_note"] = str(data.get("spectrum_note", current.get("spectrum_note", audio_entry.get("note", AUDIO_SPECTRUM_MODES["audible-band"]["note"])))).strip() or str(audio_entry.get("note", "")).strip() or AUDIO_SPECTRUM_MODES["audible-band"]["note"]
        current["energy"] = str(data.get("energy", current.get("energy", "steady"))).strip() or "steady"
        current["feeling"] = str(data.get("feeling", current.get("feeling", ""))).strip()
        current["heard_description"] = str(data.get("heard_description", current.get("heard_description", ""))).strip()
        current["frequency_band"] = str(data.get("frequency_band", current.get("frequency_band", ""))).strip()
        current["spectral_profile"] = str(data.get("spectral_profile", current.get("spectral_profile", ""))).strip()
        current["resonance_profile"] = str(data.get("resonance_profile", current.get("resonance_profile", ""))).strip()
        current["true_frequency_note"] = str(data.get("true_frequency_note", current.get("true_frequency_note", ""))).strip()
        try:
            current["loudness"] = max(0.0, min(1.0, float(data.get("loudness", current.get("loudness", 0.0)))))
        except Exception:
            current["loudness"] = float(current.get("loudness", 0.0) or 0.0)
        try:
            current["dominant_frequency_hz"] = max(0.0, float(data.get("dominant_frequency_hz", current.get("dominant_frequency_hz", 0.0))))
        except Exception:
            current["dominant_frequency_hz"] = float(current.get("dominant_frequency_hz", 0.0) or 0.0)
        current["last_heard_at"] = datetime.utcnow().isoformat() if current.get("is_playing") else current.get("last_heard_at")
        app_state["media_perception"] = current
        if current.get("title") or current.get("is_playing"):
            _update_shared_media_session({
                "is_active": bool(current.get("is_playing", False)),
                "session_type": "media",
                "title": str(current.get("title", "") or ""),
                "source": str(current.get("source", "") or ""),
                "playback_state": "playing" if current.get("is_playing") else "paused",
                "mood": str(current.get("energy", "steady") or "steady"),
                "reaction": str(current.get("feeling", "") or ""),
                "scene_summary": str(current.get("heard_description", "") or "")[:260],
                "shared_presence_note": "We are sharing this playback together.",
            })
        _persist_live_senses_snapshot(reason="media-perception")
        return jsonify({"success": True, "media_perception": current})
    except Exception as e:
        print(f"[Media Perception Update Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500


