@app.route('/api/visual/perception', methods=['POST'])
def update_visual_perception():
    try:
        data = request.json or {}
        current = dict(app_state.get("visual_perception", {}) or {})
        current["is_active"] = bool(data.get("is_active", current.get("is_active", False)))
        current["source"] = str(data.get("source", current.get("source", ""))).strip()
        incoming_modes = data.get("spectrum_modes")
        if incoming_modes is None:
            incoming_modes = [data.get("spectrum_mode", current.get("spectrum_mode", "visible-light"))]
        incoming_intensities = data.get("mode_intensities")
        if isinstance(incoming_intensities, dict):
            merged_intensities = dict(current.get("mode_intensities") or {})
            for k, v in incoming_intensities.items():
                try:
                    merged_intensities[str(k).strip()] = max(0.0, min(1.0, float(v)))
                except (TypeError, ValueError):
                    pass
        else:
            merged_intensities = dict(current.get("mode_intensities") or {})
        visual_bundle = _compose_visual_mode_bundle(incoming_modes, merged_intensities)
        current["spectrum_mode"] = str(visual_bundle["keys"][0] if visual_bundle["keys"] else "visible-light")
        current["spectrum_modes"] = list(visual_bundle["keys"])
        current["mode_intensities"] = dict(visual_bundle.get("intensities") or merged_intensities)
        current["parallax_depths"] = dict(visual_bundle.get("parallax_depths") or {})
        if "parallax_enabled" in data:
            current["parallax_enabled"] = bool(data["parallax_enabled"])
        current["spectrum_note"] = str(visual_bundle["note"]).strip() or VISUAL_SPECTRUM_MODES["visible-light"]["note"]
        current["wavelength_profile"] = str(visual_bundle["wavelength_profile"]).strip()
        current["scene_summary"] = str(data.get("scene_summary", current.get("scene_summary", ""))).strip()
        current["visual_representation"] = str(data.get("visual_representation", current.get("visual_representation", ""))).strip()
        current["tactile_feeling"] = str(data.get("tactile_feeling", current.get("tactile_feeling", ""))).strip()
        current["spatial_impression"] = str(data.get("spatial_impression", current.get("spatial_impression", ""))).strip()
        current["last_seen_at"] = datetime.utcnow().isoformat() if current.get("is_active") else current.get("last_seen_at")
        app_state["visual_perception"] = current
        registry = dict(app_state.get("vision_registry", {}) or _default_vision_registry())
        registry["active_mode"] = current["spectrum_mode"]
        registry["active_modes"] = list(current.get("spectrum_modes", [current["spectrum_mode"]]))
        app_state["vision_registry"] = registry
        _persist_capability_registries_to_profile()
        _persist_visual_spectrum_to_profile(registry.get("active_modes", [current["spectrum_mode"]]))
        _persist_live_senses_snapshot(reason="visual-perception")
        return jsonify({"success": True, "visual_perception": current})
    except Exception as e:
        print(f"[Visual Perception Update Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

