@app.route('/api/audio/registry', methods=['POST'])
def update_audio_registry():
    try:
        data = request.json or {}
        registry = dict(app_state.get("audio_registry", _default_audio_registry()) or _default_audio_registry())
        if "active_mode" in data:
            registry["active_mode"] = _resolve_mode_key_from_entries(data.get("active_mode", registry.get("active_mode", "audible-band")), list(registry.get("documented_modes", []) or []), "audible-band")
        elif any(data.get(field) for field in ("label", "note", "prompt")):
            if not str(data.get("label", "")).strip():
                return jsonify({"success": False, "error": "label is required for a new audio mode"}), 400
            entry = _build_registry_entry(
                data.get("key") or data.get("label"),
                data.get("label"),
                data.get("note"),
                data.get("prompt"),
                built_in=False,
                origin="aurion"
            )
            registry["documented_modes"] = _sanitize_registry_entries(list(registry.get("documented_modes", []) or []) + [entry], _default_audio_registry()["documented_modes"])
            registry["last_created_at"] = entry.get("created_at") or datetime.utcnow().isoformat()
            deep = dict(app_state.get("deep_learning", {}) or _default_deep_learning_state())
            deep["last_learned_at"] = datetime.utcnow().isoformat()
            deep["discoveries"] = list(deep.get("discoveries", []) or []) + [f"Formed new audio mode: {entry['label']}"]
            deep["discoveries"] = deep["discoveries"][-24:]
            app_state["deep_learning"] = deep
            _persist_deep_learning_to_profile()
            _update_cymatics_mastery_from_text(f"{entry['label']} {entry['note']} {entry['prompt']}", base_increment=6)
            memory.add_knowledge_batch(
                f"Audio capability documented: {entry['label']}. {entry['note']} {entry['prompt']}",
                source="aurion_audio_registry",
                metadata={"key": entry["key"], "created_at": entry["created_at"]}
            )
        app_state["audio_registry"] = registry
        _sync_audio_registry_modes_to_perception()
        _persist_capability_registries_to_profile()
        return jsonify({
            "success": True,
            "audio_registry": registry,
            "media_perception": dict(app_state.get("media_perception", {}) or {}),
            "world_audio_perception": dict(app_state.get("world_audio_perception", {}) or {}),
            "vision_registry": dict(app_state.get("vision_registry", {}) or {}),
            "deep_learning": dict(app_state.get("deep_learning", {}) or {}),
            "sound_creation": dict(app_state.get("sound_creation", {}) or {})
        })
    except Exception as e:
        print(f"[Audio Registry Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

