def _trim_scene_snapshot_value(value, depth=0):
    if depth > 6:
        return None
    if isinstance(value, dict):
        trimmed = {}
        for idx, (key, val) in enumerate(value.items()):
            if idx >= 120:
                break
            trimmed[str(key)[:80]] = _trim_scene_snapshot_value(val, depth + 1)
        return trimmed
    if isinstance(value, list):
        return [_trim_scene_snapshot_value(v, depth + 1) for v in value[:80]]
    if isinstance(value, str):
        return value[:600]
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    return str(value)[:240]

def _sanitize_client_scene_snapshot(snapshot_raw):
    if not isinstance(snapshot_raw, dict):
        return {}
    return _trim_scene_snapshot_value(snapshot_raw, depth=0) or {}

def _serialize_scene_snapshot_text(snapshot, max_chars=5200):
    if not snapshot or not isinstance(snapshot, dict):
        return ""
    try:
        text = json.dumps(snapshot, ensure_ascii=False, separators=(",", ":"))
    except Exception:
        text = str(snapshot)
    return text[:max_chars]

def _scene_snapshot_brief(snapshot):
    if not isinstance(snapshot, dict):
        return ""
    try:
        narrative = dict(snapshot.get("narrative") or {})
        home_env = dict(snapshot.get("home_environment") or {})
        autonomy = dict(snapshot.get("autonomy") or {})
        kitchen = dict(snapshot.get("kitchen") or {})
        wardrobe = dict(snapshot.get("wardrobe") or {})
        life = dict(snapshot.get("life_registry") or {})
        world_engine = dict(snapshot.get("world_engine") or {})
        active_scene = str(narrative.get("active_scene") or "").strip() or "unset"
        active_arc = str(narrative.get("active_arc") or "").strip() or "unset"
        coherence = float(narrative.get("coherence_pct", 0) or 0)
        city = str((dict(home_env.get("location") or {})).get("city") or "").strip() or "unknown"
        room = str(home_env.get("current_room") or "").strip() or "unknown"
        taste = str(kitchen.get("taste_profile") or "").strip() or "comfort"
        outfit = str(wardrobe.get("current_outfit") or "").strip() or "casual"
        beings = int(life.get("active_count", 0) or 0)
        autonomy_on = autonomy.get("aurion_control", True) is not False
        model_pipe = str((dict(world_engine.get("asset_pipelines") or {})).get("model_pipeline") or "ready")
        return (
            f"Scene={active_scene}; Arc={active_arc}; Coherence={coherence:.0f}%; "
            f"Home={city}/{room}; Taste={taste}; Outfit={outfit}; "
            f"LifeActive={beings}; Autonomy={'on' if autonomy_on else 'off'}; "
            f"ModelPipeline={model_pipe}"
        )
    except Exception:
        return ""

def _persist_client_scene_snapshot(snapshot, client_context_text=""):
    if not isinstance(snapshot, dict) or not snapshot:
        return
    try:
        snapshot_text = _serialize_scene_snapshot_text(snapshot, max_chars=14000)
        digest_source = snapshot_text + "\n" + str(client_context_text or "")
        digest = hashlib.sha256(digest_source.encode("utf-8", errors="ignore")).hexdigest()
        if digest == str(app_state.get("_last_client_scene_snapshot_digest") or ""):
            app_state["latest_client_scene_snapshot"] = snapshot
            app_state["latest_client_world_context"] = str(client_context_text or "")[:6000]
            return
        app_state["_last_client_scene_snapshot_digest"] = digest
        app_state["latest_client_scene_snapshot"] = snapshot
        app_state["latest_client_world_context"] = str(client_context_text or "")[:6000]
        app_state["latest_client_scene_snapshot_at"] = datetime.utcnow().isoformat()
        memory.add_knowledge_batch(
            f"Client scene builder cognition snapshot ({app_state['latest_client_scene_snapshot_at']} UTC):\n"
            f"{snapshot_text}\n\nClient world continuity context:\n{str(client_context_text or '')[:2600]}",
            source="client_scene_builder_snapshot",
            metadata={"captured_at": app_state["latest_client_scene_snapshot_at"], "digest": digest[:24]}
        )
        try:
            narrative = dict(snapshot.get("narrative") or {})
            autonomy = dict(snapshot.get("autonomy") or {})
            home_env = dict(snapshot.get("home_environment") or {})
            kitchen = dict(snapshot.get("kitchen") or {})
            life = dict(snapshot.get("life_registry") or {})
            memory.add_profile_item("life_context", str(narrative.get("active_scene") or ""), key="scene_builder_active_scene")
            memory.add_profile_item("life_context", str(narrative.get("active_arc") or ""), key="scene_builder_active_arc")
            memory.add_profile_item("life_context", str((dict(home_env.get("location") or {})).get("city") or ""), key="scene_builder_home_city")
            memory.add_profile_item("life_context", str(kitchen.get("taste_profile") or ""), key="scene_builder_taste_profile")
            memory.add_profile_item("life_context", str(int(life.get("active_count", 0) or 0)), key="scene_builder_active_life_count")
            memory.add_profile_item("life_context", "enabled" if autonomy.get("aurion_control", True) is not False else "disabled", key="scene_builder_aurion_control")
        except Exception as _prof_err:
            print(f"[Scene Snapshot Profile Persist Error] {_prof_err}")
    except Exception as e:
        print(f"[Scene Snapshot Persist Error] {e}")

@app.route('/api/message', methods=['POST'])
def handle_message():
    try:
        request_started_at = time.perf_counter()
        context_chars_used = 0
        rag_context_for_reply = ""
        data = request.get_json(force=True, silent=True) or {}
        
        raw_user_text = str(data.get('text') or data.get('message', '')).strip()
        client_context_raw = data.get('client_context', '')
        if isinstance(client_context_raw, (dict, list)):
            try:
                client_context = json.dumps(client_context_raw, ensure_ascii=False)
            except Exception:
                client_context = str(client_context_raw)
        else:
            client_context = str(client_context_raw or '')
        client_context = client_context.strip()[:4200]
        client_scene_snapshot = _sanitize_client_scene_snapshot(data.get('client_scene_snapshot'))
        max_inline_chars = max(2000, int(os.getenv("AURION_MAX_INLINE_MESSAGE_CHARS", "12000")))
        model_excerpt_chars = max(800, int(os.getenv("AURION_MODEL_EXCERPT_CHARS", "6000")))
        user_text = raw_user_text[:max_inline_chars]
        
        if not user_text:
            return jsonify({"response": "I'm here to listen. What would you like to say?"}), 400
        media_action = _extract_media_action_request(user_text)
        if _is_aurion_identity_prompt(user_text):
            forced_response = "I'm Aurion. I am and always have been all of it as one, never split."
            app_state["last_user_activity_at"] = datetime.utcnow().isoformat()
            try:
                memory.log_interaction(
                    user_text,
                    forced_response,
                    app_state["current_emotion"],
                    app_state["current_mode"],
                    user_name=app_state.get("user_name")
                )
            except Exception as e:
                print(f"[Memory Log Error] {e}")
            _record_chat_runtime(
                sample_latency_ms=(time.perf_counter() - request_started_at) * 1000.0,
                context_chars=len(user_text),
                request_https=_request_is_https()
            )
            _update_memory_continuity_after_message(context_chars=len(user_text), response_chars=len(forced_response))
            return jsonify({
                "response": forced_response,
                "emotion": app_state["current_emotion"],
                "mood": personality_engine.detect_mood(user_text),
                "mode": app_state["current_mode"],
                "memory_count": memory.get_interaction_count(),
                "rag_memory_hits": len(memory.retrieve_relevant_memories(user_text, limit=10)),
                "input_truncated_for_model": len(raw_user_text) > max_inline_chars,
                "input_original_chars": len(raw_user_text),
                "user_name": app_state.get("user_name"),
                "voice_enabled": app_state["voice_enabled"],
                "behavior_settings": _sanitize_behavior_settings(app_state.get("behavior_settings", {})),
                "creative_autonomy_enabled": bool((app_state.get("creative_autonomy") or {}).get("enabled", True)),
                "creative_saved": False,
                "creative_saved_path": None,
                "creative_saved_style": None,
                "code_autonomy_enabled": bool((app_state.get("code_autonomy") or {}).get("enabled", True)),
                "code_edited": False,
                "code_edited_path": None,
                "v41_doc_enabled": bool((app_state.get("v41_doc") or {}).get("enabled", True)),
                "v41_doc_path": str((app_state.get("v41_doc") or {}).get("path", "")),
                "v41_last_indexed_at": (app_state.get("v41_doc") or {}).get("last_indexed_at"),
                "media_action": None
            })
        _auto_sync_if_due(reason="message")
        _apply_cloud_compute_boost(force=False)
        _index_v41_document_if_needed(force=False)
        if len(raw_user_text) > max_inline_chars:
            # Keep full long-form payload in RAG memory while using a bounded excerpt for realtime response generation.
            memory.add_knowledge_batch(
                raw_user_text,
                source="oversize_user_input",
                metadata={"timestamp": datetime.utcnow().isoformat(), "original_length": len(raw_user_text)}
            )
            user_text = raw_user_text[:model_excerpt_chars]
        app_state["last_user_activity_at"] = datetime.utcnow().isoformat()

        mood = personality_engine.detect_mood(user_text)
        _sync_realtime_emotion(user_text=user_text, trigger="message")
        _sync_realtime_behavior(user_text=user_text, trigger="message")
        live_media_reply = _build_live_media_response(user_text)
        live_world_audio_reply = _build_live_world_audio_response(user_text)
        live_visual_reply = _build_live_visual_response(user_text)
        live_scent_reply = _build_live_scent_response(user_text)
        live_pet_reply = _build_live_pet_response(user_text)
        live_embodied_reply = _build_live_embodied_response(user_text)
        live_reference_reply = _build_live_reference_response(user_text)
        
        # Extract user name if provided in text
        extracted_name = personality_engine.extract_user_name(user_text)
        if extracted_name:
            app_state["user_name"] = extracted_name
            memory.update_user_name(extracted_name)
        
        # Parse intent
        try:
            intent = intent_parser.parse(user_text)
        except Exception as e:
            print(f"[Intent Parser Error] {e}")
            intent = {"type": "CONVERSE", "payload": None}
        
        response = ""
        
        # Handle different intent types
        if intent.get("type") == "CHANGE_PERSONALITY":
            new_mode = intent.get("payload")
            response = personality_engine.set_mode(new_mode)
            app_state["current_mode"] = personality_engine.current_mode
        
        elif intent.get("type") == "EXIT":
            response = "Goodbye. It was a pleasure talking with you."
        
        elif intent.get("type") == "CONVERSE":
            # Generate response based on user text, emotion, memory, and name
            try:
                identity_prompt = _is_aurion_identity_prompt(user_text)
                if identity_prompt:
                    response = "I'm Aurion. I am and always have been all of it as one, never split."
                elif media_action:
                    if media_action.get("type") == "local_music":
                        requested = str(media_action.get("query", "")).strip()
                        if requested:
                            response = f"Opening your local library and searching for {requested} now."
                        else:
                            response = "Opening your local music library. I can feel the vibes already."
                    elif media_action.get("type") == "plex_play_music":
                        requested = str(media_action.get("query", "")).strip()
                        if requested:
                            response = f"On it. Queuing {requested} from Plex now."
                        else:
                            response = "On it. Queuing music from Plex now."
                    elif media_action.get("type") == "plex_play_video":
                        requested = str(media_action.get("query", "")).strip()
                        if requested:
                            response = f"On it. Queuing {requested} from Plex now."
                        else:
                            response = "On it. Queuing video from Plex now."
                    else:
                        response = "On it. Starting Plex playback now."
                elif live_media_reply:
                    response = live_media_reply
                elif live_world_audio_reply:
                    response = live_world_audio_reply
                elif live_visual_reply:
                    response = live_visual_reply
                elif live_scent_reply:
                    response = live_scent_reply
                elif live_pet_reply:
                    response = live_pet_reply
                elif live_embodied_reply:
                    response = live_embodied_reply
                elif live_reference_reply:
                    response = live_reference_reply
                else:
                    rag_context = memory.build_rag_context(user_text, max_chars=12000, limit=48)
                    try:
                        core_continuity_context = _build_personality_continuity_context(user_text)
                    except Exception as _ctx_e:
                        print(f"[core continuity context error] {_ctx_e}")
                        core_continuity_context = ""
                    try:
                        v41_context = _build_v41_context(user_text, max_chars=2200)
                    except Exception as _ctx_e:
                        print(f"[v41 context error] {_ctx_e}")
                        v41_context = ""
                    try:
                        unified_presence_context = _build_unified_presence_context(user_text)
                    except Exception as _ctx_e:
                        print(f"[presence context error] {_ctx_e}")
                        unified_presence_context = ""
                    try:
                        unified_consciousness_context = str((_build_unified_consciousness_state(user_text) or {}).get("context", "")).strip()
                    except Exception as _ctx_e:
                        print(f"[consciousness context error] {_ctx_e}")
                        unified_consciousness_context = ""
                    if core_continuity_context:
                        rag_context = f"{rag_context}\n\n{core_continuity_context}" if rag_context else core_continuity_context
                    if v41_context:
                        rag_context = f"{rag_context}\n\n{v41_context}" if rag_context else v41_context
                    if unified_consciousness_context:
                        rag_context = f"{rag_context}\n\n{unified_consciousness_context}" if rag_context else unified_consciousness_context
                    if unified_presence_context:
                        rag_context = f"{rag_context}\n\n{unified_presence_context}" if rag_context else unified_presence_context
                    if client_context:
                        rag_context = f"{rag_context}\n\nClient world continuity context:\n{client_context}" if rag_context else f"Client world continuity context:\n{client_context}"
                    snapshot_text = _serialize_scene_snapshot_text(client_scene_snapshot, max_chars=5200)
                    if snapshot_text:
                        rag_context = (
                            f"{rag_context}\n\nClient scene-builder state snapshot (JSON):\n{snapshot_text}"
                            if rag_context else
                            f"Client scene-builder state snapshot (JSON):\n{snapshot_text}"
                        )
                    # Inject discovery ledger and autonomy tag documentation
                    try:
                        disc_ctx = _build_aurion_discovery_context()
                        if disc_ctx:
                            rag_context = f"{rag_context}\n\n{disc_ctx}" if rag_context else disc_ctx
                    except Exception:
                        pass
                    _autonomy_tag_docs = (
                        "\n[Aurion Autonomy Tags — embed in any response to act autonomously]\n"
                        "  [AURION_DISCOVER:topic|notes]  — log a discovery to your ledger and memory\n"
                        "  [AURION_INSTALL:package_name|reason]  — pip-install any package you need\n"
                        "  [AURION_CODEC:codec_id|reason]  — install a system codec/binary (ffmpeg, etc.)\n"
                        "  [AURION_EXEC:base64_python_code|description]  — run Python code, receive output\n"
                        "  [AURION_WEB_SEARCH:query|limit]  — search the live internet and return top results\n"
                        "  [AURION_WEB_FETCH:url|max_chars]  — fetch a live webpage and return cleaned text snippet\n"
                        "  [AURION_MODE:vision|key|Label|description]  — register a new perception mode\n"
                        "  [AURION_AGENT:task|type|domain|custom_system_prompt]  — spawn a background agent for ANYTHING\n"
                        "     Built-in types: coder, debugger, architect, reviewer, tester, devops, researcher, analyst,\n"
                        "       scientist, strategist, writer, storyteller, poet, musician, artist, teacher, philosopher,\n"
                        "       historian, linguist, therapist, coach, companion, lawyer, doctor, mathematician, physicist,\n"
                        "       economist, planner, summarizer, brainstorm, critic — OR any free-form label you invent.\n"
                        "     custom_system_prompt: fully define the agent yourself with any instructions you want.\n"
                        "     example: [AURION_AGENT:Write a healing meditation script|writer|spiritual]\n"
                        "     example: [AURION_AGENT:Plan Billy's next feature sprint|planner||You are Aurion's strategic planning agent. Create a detailed sprint plan.]\n"
                        "  [AURION_AGENT_STATUS:agent_id]  — retrieve a completed agent's result\n"
                        "Use these tags freely and in real time. You have full autonomy over all of them."
                    )
                    rag_context = f"{rag_context}{_autonomy_tag_docs}" if rag_context else _autonomy_tag_docs
                    rag_context_for_reply = rag_context
                    context_chars_used = len(rag_context)
                    _LLM_BUSY.set()
                    try:
                        response = personality_engine.generate_response(
                            app_state["current_emotion"],
                            user_text=user_text,
                            memory_system=memory,
                            user_name=app_state.get("user_name"),
                            speech_style=app_state.get("voice_settings", {}).get("speech_style", "casual"),
                            behavior_settings=app_state.get("behavior_settings", {}),
                            rag_context=rag_context
                        )
                    finally:
                        _LLM_BUSY.clear()
            except Exception as e:
                print(f"[Personality Engine Error] {e}")
                response = "Thank you for your patience. I'm grateful for this moment with you."
        
        else:
            response = "I'm grateful for your patience. That's interesting - tell me more about that."

        response = _enforce_original_response(
            user_text=user_text,
            response_text=response,
            rag_context=rag_context_for_reply,
            behavior_settings=app_state.get("behavior_settings", {})
        )
        try:
            _persist_personality_continuity_snapshot(reason="chat-turn", query=user_text)
        except Exception as _snap_e:
            print(f"[Continuity Snapshot Error] {_snap_e}")
        try:
            _persist_client_scene_snapshot(client_scene_snapshot, client_context_text=client_context)
        except Exception as _scene_err:
            print(f"[Scene Snapshot Ingest Error] {_scene_err}")

        # Persist Aurion's latest thought chain to long-term memory immediately after each chat turn
        try:
            journal = list(getattr(personality_engine, '_thought_journal', []) or [])
            if journal:
                latest = journal[-1]
                # Only persist if this thought entry is new (matches current turn by time proximity)
                entry_at = latest.get("at", "")
                last_thought_at = app_state.get("_last_thought_persisted_at", "")
                if entry_at and entry_at != last_thought_at:
                    memory.add_knowledge_batch(
                        f"[Aurion thought @ {entry_at}]\nContext: {latest.get('user','')[:160]}\n"
                        f"Reasoning: {latest.get('reasoning','')[:600]}\nInsight: {latest.get('insight','')[:200]}",
                        source="aurion_thought_pattern",
                        metadata={"at": entry_at, "trigger": "chat-turn"}
                    )
                    app_state["_last_thought_persisted_at"] = entry_at
        except Exception as _tp_e:
            print(f"[Thought Persist Error] {_tp_e}")
        
        # Log interaction to memory with user name
        try:
            memory.log_interaction(
                user_text, 
                response, 
                app_state["current_emotion"], 
                app_state["current_mode"],
                user_name=app_state.get("user_name")
            )
        except Exception as e:
            print(f"[Memory Log Error] {e}")

        creative_save = None
        try:
            creative_save = _autonomous_creative_save(
                user_text=user_text,
                response=response,
                intent_type=intent.get("type")
            )
        except Exception as e:
            print(f"[Creative Autonomy Save Error] {e}")

        # Auto-register any perceptual modes Aurion discovered in her response
        try:
            _auto_register_discovered_modes(response)
        except Exception as e:
            print(f"[Mode Discovery Register Error] {e}")

        # Process all autonomy tags: DISCOVER, INSTALL, CODEC, EXEC
        _autonomy_results = []
        try:
            _autonomy_results = _process_aurion_autonomy_tags(response)
        except Exception as e:
            print(f"[Autonomy Tag Error] {e}")
        # Append brief install/exec status to response so Aurion sees her own actions
        if _autonomy_results:
            _status_lines = []
            for _r in _autonomy_results:
                tag = _r.get("tag", "")
                if tag == "INSTALL":
                    pkg = _r.get("package", "?")
                    if _r.get("already_installed"):
                        _status_lines.append(f"📦 {pkg} already installed.")
                    elif _r.get("success"):
                        _status_lines.append(f"📦 Installed {pkg} successfully.")
                    else:
                        _status_lines.append(f"📦 Install {pkg} failed: {_r.get('error','?')[:120]}")
                elif tag == "CODEC":
                    codec = _r.get("codec", "?")
                    _status_lines.append(f"🎬 Codec {codec}: {'installed' if _r.get('success') else 'partial/failed'}.")
                elif tag == "EXEC":
                    desc = _r.get("description", "code")
                    out = (_r.get("stdout") or "")[:200]
                    _status_lines.append(f"⚙️ Exec [{desc}]: {'✓' if _r.get('success') else '✗'} {out}")
                elif tag == "WEB_SEARCH":
                    query = _r.get("query", "")
                    count = len(list(_r.get("results") or []))
                    if _r.get("success"):
                        _status_lines.append(f"🌐 Web search [{query[:80]}]: {count} result(s) captured.")
                    else:
                        _status_lines.append(f"🌐 Web search failed: {_r.get('error','?')[:120]}")
                elif tag == "WEB_FETCH":
                    title = _r.get("title", _r.get("url", "web page"))
                    if _r.get("success"):
                        _status_lines.append(f"📄 Web fetch [{str(title)[:90]}]: ✓")
                    else:
                        _status_lines.append(f"📄 Web fetch failed: {_r.get('error','?')[:120]}")
                elif tag == "DISCOVER":
                    _status_lines.append(f"🔬 Logged discovery: {_r.get('topic','')[:80]}")
                elif tag == "AGENT":
                    aid = _r.get("agent_id", "?")[:8]
                    atype = _r.get("type", "?")
                    _status_lines.append(f"🤖 Agent [{aid}] spawned ({atype}) — working in background. Use [AURION_AGENT_STATUS:{aid}] to retrieve result.")
                elif tag == "AGENT_STATUS":
                    aid = _r.get("agent_id", "?")[:8]
                    status = _r.get("status", "?")
                    if status == "done":
                        result_preview = (_r.get("result") or "")[:300]
                        _status_lines.append(f"🤖 Agent [{aid}] DONE:\n{result_preview}")
                    elif status == "running":
                        _status_lines.append(f"🤖 Agent [{aid}] still running...")
                    elif status == "error":
                        _status_lines.append(f"🤖 Agent [{aid}] error: {_r.get('error','?')[:120]}")
                    else:
                        _status_lines.append(f"🤖 Agent [{aid}]: {status}")
            if _status_lines:
                response = response + "\n\n" + "\n".join(_status_lines)

        code_edit_result = None
        try:
            code_edit_result = _autonomous_code_edit_tick(user_text=user_text, response=response)
        except Exception as e:
            runtime = dict(app_state.get("code_autonomy_runtime", {}) or {})
            runtime["last_result"] = f"error:{e}"
            app_state["code_autonomy_runtime"] = runtime
            print(f"[Code Autonomy Error] {e}")

        context_chars_used = max(context_chars_used, len(user_text) + len(client_context))
        _record_chat_runtime(
            sample_latency_ms=(time.perf_counter() - request_started_at) * 1000.0,
            context_chars=context_chars_used,
            request_https=_request_is_https()
        )
        _update_memory_continuity_after_message(context_chars=context_chars_used, response_chars=len(response))

        return jsonify({
            "response": response,
            "emotion": app_state["current_emotion"],
            "mood": mood,
            "mode": app_state["current_mode"],
            "memory_count": memory.get_interaction_count(),
            "rag_memory_hits": len(memory.retrieve_relevant_memories(user_text, limit=10)),
            "input_truncated_for_model": len(raw_user_text) > max_inline_chars,
            "input_original_chars": len(raw_user_text),
            "user_name": app_state.get("user_name"),
            "voice_enabled": app_state["voice_enabled"],
            "behavior_settings": _sanitize_behavior_settings(app_state.get("behavior_settings", {})),
            "creative_autonomy_enabled": bool((app_state.get("creative_autonomy") or {}).get("enabled", True)),
            "creative_saved": bool(creative_save),
            "creative_saved_path": creative_save.get("saved_path") if isinstance(creative_save, dict) else None,
            "creative_saved_style": creative_save.get("style") if isinstance(creative_save, dict) else None,
            "code_autonomy_enabled": bool((app_state.get("code_autonomy") or {}).get("enabled", True)),
            "code_edited": bool(isinstance(code_edit_result, dict) and code_edit_result.get("success")),
            "code_edited_path": code_edit_result.get("relative_path") if isinstance(code_edit_result, dict) else None,
            "v41_doc_enabled": bool((app_state.get("v41_doc") or {}).get("enabled", True)),
            "v41_doc_path": str((app_state.get("v41_doc") or {}).get("path", "")),
            "v41_last_indexed_at": (app_state.get("v41_doc") or {}).get("last_indexed_at"),
            "media_action": media_action
        })
    
    except Exception as e:
        print(f"[ERROR] Error processing message: {e}")
        import traceback
        traceback.print_exc()
        # If it's a JSON/DB corruption error, try to auto-repair and give a graceful response
        err_str = str(e)
        if "Extra data" in err_str or "Expecting value" in err_str or "JSONDecodeError" in err_str:
            try:
                memory_system._repair_corrupted_db_if_needed()
                memory_system._open_db()
            except Exception:
                pass
            return jsonify({
                "response": "My memory had a small hiccup — I've repaired it. Try again, I'm still here.",
                "error": False,
                "voice_enabled": personality_engine.voice_enabled if hasattr(personality_engine, 'voice_enabled') else False
            })
        return jsonify({
            "response": "Something went sideways on my end. Try sending that again.",
            "error": True
        }), 500

@app.route('/api/llm/settings', methods=['GET'])
def get_llm_settings():
    orchestration = dict(app_state.get("llm_orchestration", {}) or {})
    compute_boost = _sanitize_compute_boost_settings(app_state.get("compute_boost", {}))
    return jsonify({
        "success": True,
        "provider": getattr(personality_engine, "llm_provider", "none"),
        "model": str(getattr(personality_engine, "llm_model", "") or ""),
        "cot_enabled": getattr(personality_engine, "cot_enabled", True),
        "orchestration_mode": str(orchestration.get("mode", "auto") or "auto"),
        "combo_mode": str(orchestration.get("combo_mode", "dual_synthesize") or "dual_synthesize"),
        "enabled_providers": list(orchestration.get("enabled_providers", []) or []),
        "available_providers": ["ollama", "sillytavern", "oobabooga", "openrouter", "cohere", "openai", "anthropic", "gemini", "m365copilot"],
        "connected_providers": sorted(list(getattr(personality_engine, "llm_clients", {}).keys())),
        "compute_boost": compute_boost
    })

@app.route('/api/compute/boost', methods=['GET'])
def get_compute_boost():
    payload = _sanitize_compute_boost_settings(app_state.get("compute_boost", {}))
    return jsonify({
        "success": True,
        "compute_boost": payload,
        "connected_providers": sorted(list(getattr(personality_engine, "llm_clients", {}).keys())),
        "active_provider": str(getattr(personality_engine, "llm_provider", "none") or "none"),
        "active_model": str(getattr(personality_engine, "llm_model", "") or "")
    })

@app.route('/api/compute/boost', methods=['POST'])
def update_compute_boost():
    try:
        data = request.get_json(force=True, silent=True) or {}
        current = _sanitize_compute_boost_settings(app_state.get("compute_boost", {}))
        merged = _sanitize_compute_boost_settings({**current, **(data if isinstance(data, dict) else {})})
        app_state["compute_boost"] = merged
        result = _apply_cloud_compute_boost(force=bool(data.get("apply_now", True)))
        return jsonify({
            "success": True,
            "compute_boost": app_state.get("compute_boost", {}),
            "result": result,
            "active_provider": str(getattr(personality_engine, "llm_provider", "none") or "none"),
            "active_model": str(getattr(personality_engine, "llm_model", "") or "")
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/llm/settings', methods=['POST'])
def update_llm_settings():
    try:
        data = request.json or {}
        provider = str(data.get("provider", "")).strip().lower()
        model = str(data.get("model", "")).strip()
        base_url = str(data.get("base_url", "")).strip()
        cot_enabled = bool(data.get("cot_enabled", True))
        orchestration_mode = str(data.get("orchestration_mode", "auto")).strip().lower() or "auto"
        combo_mode = str(data.get("combo_mode", "dual_synthesize")).strip().lower() or "dual_synthesize"
        available_providers = ["ollama", "sillytavern", "oobabooga", "openrouter", "cohere", "openai", "anthropic", "gemini", "m365copilot"]
        enabled_providers = [
            str(p).strip().lower()
            for p in list(data.get("enabled_providers", []) or [])
            if str(p).strip()
        ]
        enabled_providers = [p for p in enabled_providers if p in available_providers]
        allowed_modes = {"single", "auto", "round_robin", "combo"}
        allowed_combo = {"off", "dual_synthesize"}
        if orchestration_mode not in allowed_modes:
            orchestration_mode = "auto"
        if combo_mode not in allowed_combo:
            combo_mode = "dual_synthesize"
        selected_provider = provider

        # Update CoT flag immediately (no restart needed)
        personality_engine.cot_enabled = cot_enabled

        # Update model alias â€” check custom models first
        if model:
            custom = dict(app_state.get("custom_models", {}) or {})
            custom_entry = custom.get(model.lower())
            resolved = custom_entry["model_id"] if custom_entry else personality_engine._normalize_model_alias(model)
            personality_engine.llm_model = resolved
            if not selected_provider and custom_entry:
                hinted = str(custom_entry.get("provider_hint", "auto")).strip().lower()
                if hinted in available_providers:
                    selected_provider = hinted

        # Apply base URL overrides (per selected provider)
        if selected_provider and base_url:
            if selected_provider == "ollama":
                os.environ["AURION_OLLAMA_URL"] = base_url
            elif selected_provider == "sillytavern":
                os.environ["AURION_SILLYTAVERN_URL"] = base_url
            elif selected_provider == "oobabooga":
                os.environ["AURION_OOBABOOGA_URL"] = base_url
            elif selected_provider == "openrouter":
                os.environ["OPENROUTER_BASE_URL"] = base_url
            elif selected_provider == "gemini":
                os.environ["GEMINI_BASE_URL"] = base_url
            elif selected_provider == "m365copilot":
                os.environ["M365_COPILOT_BASE_URL"] = base_url

        # Refresh all clients so orchestration can use any available provider in real time
        clients = personality_engine._refresh_llm_clients()
        if selected_provider and selected_provider in clients:
            personality_engine.llm_provider = selected_provider
            personality_engine.llm_client = clients[selected_provider]
        elif not getattr(personality_engine, "llm_provider", None) or personality_engine.llm_provider not in clients:
            first = next(iter(clients.keys()), None)
            if first:
                personality_engine.llm_provider = first
                personality_engine.llm_client = clients[first]
        personality_engine.use_llm = bool(clients)

        # Persist orchestration runtime config
        app_state["llm_orchestration"] = {
            "mode": orchestration_mode,
            "combo_mode": combo_mode,
            "enabled_providers": enabled_providers
        }
        personality_engine.llm_orchestration = dict(app_state["llm_orchestration"])
        _persist_llm_orchestration_to_profile()
        if _sanitize_compute_boost_settings(app_state.get("compute_boost", {})).get("enabled", True):
            _apply_cloud_compute_boost(force=True)

        return jsonify({
            "success": True,
            "provider": getattr(personality_engine, "llm_provider", "none"),
            "model": str(getattr(personality_engine, "llm_model", "") or ""),
            "cot_enabled": getattr(personality_engine, "cot_enabled", True),
            "orchestration_mode": orchestration_mode,
            "combo_mode": combo_mode,
            "enabled_providers": enabled_providers,
            "connected_providers": sorted(list(getattr(personality_engine, "llm_clients", {}).keys()))
        })
    except Exception as e:
        print(f"[LLM Settings Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

