# â”€â”€ In-Browser Code Editor â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
_CODE_EDITOR_WHITELIST = {
    "web_ui.py":     "web_ui.py",
    "personality_engine.py": "joi_companion/core/personality_engine.py",
    "env":           ".env",
    ".env":          ".env"
}

def _code_editor_resolve(filename):
    key = str(filename or "").strip()
    path = _CODE_EDITOR_WHITELIST.get(key) or _CODE_EDITOR_WHITELIST.get(key.lower())
    if not path:
        return None
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), path)

@app.route('/api/code/read', methods=['GET'])
def code_editor_read():
    filename = request.args.get("file", "web_ui.py")
    resolved = _code_editor_resolve(filename)
    if not resolved:
        return jsonify({"success": False, "error": "File not in editor whitelist"}), 403
    try:
        content = open(resolved, encoding="utf-8").read()
        return jsonify({"success": True, "file": filename, "content": content, "lines": content.count("\n") + 1})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/code/write', methods=['POST'])
def code_write():
    try:
        data = request.json or {}
        filename = str(data.get("file", "")).strip()
        content = str(data.get("content", ""))
        resolved = _code_editor_resolve(filename)
        if not resolved:
            return jsonify({"success": False, "error": "File not in editor whitelist"}), 403
        # Syntax check for Python files
        if resolved.endswith(".py"):
            try:
                compile(content, resolved, "exec")
            except SyntaxError as se:
                return jsonify({"success": False, "error": f"Syntax error at line {se.lineno}: {se.msg}"}), 422
        # dry_run: syntax-only, no write
        if data.get("dry_run"):
            return jsonify({"success": True, "file": filename, "dry_run": True})
        # Backup before overwrite
        import shutil
        backup = resolved + ".bak"
        if os.path.exists(resolved):
            shutil.copy2(resolved, backup)
        with open(resolved, "w", encoding="utf-8") as f:
            f.write(content)
        lines = content.count("\n") + 1
        return jsonify({"success": True, "file": filename, "lines": lines, "backup": os.path.basename(backup)})
    except Exception as e:
        print(f"[Code Write Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

