@app.route('/api/creative/upload', methods=['POST'])
def upload_creative_file():
    try:
        if 'file' not in request.files:
            return jsonify({"success": False, "error": "No file was attached."}), 400
        uploaded = request.files['file']
        source_name = Path(str(uploaded.filename or "")).name
        if not source_name:
            return jsonify({"success": False, "error": "No file selected."}), 400
        suffix = str(Path(source_name).suffix or "").lower()[:16]
        stem = _slugify_filename(Path(source_name).stem, fallback="upload")
        mime = str(uploaded.mimetype or "").lower()
        kind_hint = str(request.form.get("kind", "")).strip().lower()
        if kind_hint in {"images", "videos", "music", "writing", "references"}:
            kind = kind_hint
        elif mime.startswith("image/"):
            kind = "images"
        elif mime.startswith("video/"):
            kind = "videos"
        elif mime.startswith("audio/") or suffix in {".mp3", ".flac", ".m4a", ".wav", ".ogg", ".aac", ".wma", ".opus", ".webm"}:
            kind = "music"
        elif mime.startswith("text/") or suffix in {".txt", ".md", ".json", ".csv", ".log"}:
            kind = "writing"
        else:
            kind = "references"
        target_dir = _creative_workspace_dir(kind)
        stamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S")
        target_name = f"{stamp}-{stem}{suffix}"
        target_path = target_dir / target_name
        uploaded.save(target_path)
        return jsonify({
            "success": True,
            "kind": kind,
            "filename": target_name,
            "public_url": f"/api/creative/media/{kind}/{quote(target_name)}",
            "saved_path": str(target_path),
            "size_bytes": int(target_path.stat().st_size if target_path.exists() else 0),
            "workspace": app_state.get("creative_workspace")
        })
    except Exception as e:
        print(f"[Creative Upload Error] {e}")
        return jsonify({"success": False, "error": str(e)}), 500

