@app.route('/api/create/video', methods=['POST'])
def create_video():
    """Generate a video using content generator"""
    try:
        data = request.get_json(force=True, silent=True) or {}
        prompt = data.get('prompt', '').strip()
        
        if not prompt:
            return jsonify({"error": "No prompt provided"}), 400
        
        # First, get video description with scenes
        video_data = content_generator.generate_video_description(prompt)
        
        if not video_data:
            return jsonify({
                "success": False,
                "error": "Could not generate video. Please add OPENAI_API_KEY to .env file."
            }), 400
        
        # Then create images for each scene
        result = content_generator.create_video_from_scenes(video_data["scenes"], prompt)
        
        if not result:
            return jsonify({
                "success": False,
                "error": "Could not generate video frames. Please try again."
            }), 400
        
        saved_ref_path = _save_creative_reference(
            "videos",
            prompt,
            {
                "prompt": prompt,
                "scenes": result["scenes"],
                "images": result["images"],
                "frame_count": result["frame_count"],
                "source": "api/create/video"
            }
        )
        return jsonify({
            "success": True,
            "prompt": prompt,
            "scenes": result["scenes"],
            "images": result["images"],
            "frame_count": result["frame_count"],
            "saved_ref_path": saved_ref_path,
            "creative_workspace": app_state.get("creative_workspace")
        })
    
    except Exception as e:
        print(f"[Video Generation Error] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({
            "success": False,
            "error": str(e)
        }), 500

# Flask error handler  
from werkzeug.exceptions import HTTPException

@app.errorhandler(HTTPException)
def handle_http_exception(e):
    return jsonify({"error": e.description, "code": e.code}), e.code

@app.errorhandler(Exception)
def handle_error(e):
    import traceback
    error_id = uuid.uuid4().hex[:12]
    print(f"[FLASK ERROR:{error_id}] {e}")
    traceback.print_exc()
    if app.config.get("DEBUG"):
        return jsonify({"error": str(e), "traceback": traceback.format_exc(), "error_id": error_id}), 500
    return jsonify({"error": "Internal server error", "error_id": error_id}), 500


